def _current_auth_headers() -> dict[str, str]:
    """The headers `auth_headers` installed for this context, else ``{}``.

    Always returns a fresh/owned mapping view for callers to splat or copy —
    the ``None`` default never leaks and nothing shared is ever mutated.
    """
    return _auth_headers.get() or {}

@contextlib.contextmanager
def _api_errors(what: str):
    """Turn raw HTTP / JSON / response-shape failures into a structured error.

    Without this, an ``HTTPError``/``URLError`` or an unexpected payload
    (``KeyError``/``JSONDecodeError``) bubbles to the dispatcher's catch-all and
    appears as ``unexpected: ...`` with no remediation.
    """
    try:
        yield
    except ModelGearError:
        raise
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            raise _unauthorized_error() from exc
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"{what} failed: {exc}",
            remediation=_STATUS_REMEDIATION,
        ) from exc
    except OSError as exc:
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"{what} failed: {exc}",
            remediation=_STATUS_REMEDIATION,
        ) from exc
    except (json.JSONDecodeError, KeyError, IndexError, TypeError) as exc:
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"{what}: unexpected response shape ({exc.__class__.__name__}: {exc})",
            remediation="the served model returned an unexpected payload; check the vLLM logs",
        ) from exc

def _get(url: str, path: str, timeout: int = 10):
    req = urllib.request.Request(url + path, headers=dict(_current_auth_headers()))
    with urllib.request.urlopen(req, timeout=timeout) as r:  # local endpoint only
        if r.headers.get("content-type", "").startswith("application/json"):
            return r.status, json.load(r)
        return r.status, r.read().decode()

def _trace_field(msg: dict) -> tuple[str | None, int]:
    """Return ``(field_name, length)`` of the reasoning trace, whichever key holds it.

    vLLM builds vary: the ``<think>`` trace lands in ``reasoning`` on the nv26.04
    image, ``reasoning_content`` on older builds.
    """
    for key in ("reasoning", "reasoning_content"):
        val = msg.get(key)
        if isinstance(val, str) and val:
            return key, len(val)
    return None, 0

def health_status(url: str) -> int:
    """Return the ``/health`` status code, or raise if the endpoint is unreachable."""
    try:
        status, _ = _get(url, "/health")
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            raise _unauthorized_error() from exc
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"/health unreachable at {url} ({exc})",
            remediation="start the server with 'lobes serve --apply'",
        ) from exc
    except OSError as exc:
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"/health unreachable at {url} ({exc})",
            remediation="start the server with 'lobes serve --apply'",
        ) from exc
    return status

def served_model(url: str, override: str | None = None) -> tuple[str, object]:
    """Return ``(model_id, max_model_len)`` from ``/v1/models``. Raises if none served."""
    with _api_errors("/v1/models"):
        _, models = _get(url, "/v1/models")
        data = models.get("data") if isinstance(models, dict) else None
        if not data:
            raise ModelGearError(
                code=EXIT_ENV_ERROR,
                message=f"/v1/models returned no models at {url}",
                remediation=_STATUS_REMEDIATION,
            )
        first = data[0]
        return (override or first["id"]), first.get("max_model_len")

def _tool_probe(url: str, model: str) -> dict:
    """Probe OpenAI tool calling; degrade gracefully, never abort the assess run.

    A server without ``--enable-auto-tool-choice`` rejects ``tool_choice:"auto"``
    with HTTP 400. A server that *has* the flags but returns an unexpected payload
    (no ``choices``/``message``, or a wrong-shaped ``tool_calls``) would otherwise
    raise inside :func:`run_correctness`'s ``_api_errors`` block and abort. Both
    cases are surfaced here as a structured ``ok=False`` result with a FAIL row.
    """
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": _TOOL_PROBE_PROMPT}],
        "tools": _TOOL_PROBE_TOOLS,
        "tool_choice": "auto",
        "max_tokens": 512,
        "temperature": 0,
    }
    try:
        d = _post(url, payload)
    except urllib.error.HTTPError as exc:
        body = exc.read().decode(errors="replace").strip()
        return {
            "ok": False,
            "tool_calls": [],
            "finish": None,
            "error": f"HTTP {exc.code}: {body[:200]}",
        }
    # Defensive parsing: a malformed 200 must not abort the run (documented
    # "FAIL row, no abort"). Use .get()/isinstance throughout, with a catch-all
    # net for any remaining shape surprise.
    try:
        choices = d.get("choices") if isinstance(d, dict) else None
        choice = choices[0] if isinstance(choices, list) and choices else {}
        msg = choice.get("message") or {}
        raw_calls = msg.get("tool_calls")
        calls = raw_calls if isinstance(raw_calls, list) else []
        names = []
        for c in calls:
            fn = c.get("function") if isinstance(c, dict) else None
            name = fn.get("name") if isinstance(fn, dict) else None
            if name:
                names.append(name)
        return {
            "ok": "finish" in names,
            "tool_calls": names,
            "finish": choice.get("finish_reason"),
            "error": None,
        }
    except (KeyError, IndexError, TypeError, AttributeError) as exc:
        return {
            "ok": False,
            "tool_calls": [],
            "finish": None,
            "error": f"unexpected response shape ({exc.__class__.__name__}: {exc})",
        }

def _strict_tools_payload(model: str, *, strict: bool, enable_thinking: bool | None) -> dict:
    tools = json.loads(json.dumps(_TOOL_PROBE_TOOLS))  # deep copy — never mutate the fixture
    if strict:
        for tool in tools:
            tool["function"]["strict"] = True
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": _TOOL_PROBE_PROMPT}],
        "tools": tools,
        "tool_choice": "auto",
        "max_tokens": 2048,
        "temperature": 0,
    }
    if enable_thinking is not None:
        payload["chat_template_kwargs"] = {"enable_thinking": enable_thinking}
    return payload

def _strict_matrix_leg(url: str, model: str, *, strict: bool, enable_thinking: bool | None) -> dict:
    """One leg of the strict matrix; never raises (mirrors ``_tool_probe``).

    A CLEAN call means: at least one ``tool_calls`` entry, every name one of
    the offered tools (a parser-salvage mangle shows up as e.g.
    ``'finish"'``), and every ``arguments`` string parsing as a JSON object.
    The baseline (non-strict) leg only requires an answer — unconstrained
    decoding is allowed to drift; that is exactly why the strict legs exist.
    """
    offered = {t["function"]["name"] for t in _TOOL_PROBE_TOOLS}
    try:
        d = _post(url, _strict_tools_payload(model, strict=strict, enable_thinking=enable_thinking))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode(errors="replace").strip()
        return _leg_error(f"HTTP {exc.code}: {body[:200]}")
    except (OSError, json.JSONDecodeError) as exc:
        return _leg_error(f"probe failed: {exc}")
    try:
        choice = (d.get("choices") or [{}])[0]
        msg = choice.get("message") or {}
        names, args_ok = _parse_leg_tool_calls(msg)
        clean = bool(names) and args_ok and all(n in offered for n in names)
        answered = bool(names) or bool(msg.get("content"))
        return {
            "ok": clean if strict else answered,
            "clean": clean,
            "tool_calls": names,
            "finish": choice.get("finish_reason"),
            "error": None,
        }
    except (KeyError, IndexError, TypeError, AttributeError) as exc:
        return _leg_error(f"unexpected response shape ({exc.__class__.__name__}: {exc})")

def run_strict_tool_matrix(url: str, model: str) -> dict:
    """Run the three-leg strict tool-calling matrix; return a structured result."""
    url = url.rstrip("/")
    legs = {
        name: _strict_matrix_leg(url, model, strict=strict, enable_thinking=thinking)
        for name, strict, thinking in _STRICT_MATRIX_LEGS
    }
    return {"passed": all(leg["ok"] for leg in legs.values()), "legs": legs}

def render_strict_tool_matrix(result: dict) -> str:
    """Markdown table for ``run_strict_tool_matrix`` (text-mode output)."""
    lines = [
        "### Strict tool-calling matrix (colleague#320)",
        "",
        "| leg | ok | clean call | tool_calls | error |",
        "|---|---|---|---|---|",
    ]
    for name, leg in result["legs"].items():
        lines.append(
            f"| {name} | {'PASS' if leg['ok'] else 'FAIL'} | {leg.get('clean')} "
            f"| {leg.get('tool_calls')} | {leg.get('error') or '—'} |"
        )
    lines.append("")
    lines.append(f"**matrix: {'PASS' if result['passed'] else 'FAIL'}**")
    return "\n".join(lines)

def _decode_throughput(url: str, model: str, n_tokens: int, runs: int = 2) -> list[float]:
    rates = []
    for _ in range(runs):
        t0 = time.monotonic()
        d = _post(
            url,
            {
                "model": model,
                "messages": [
                    {"role": "user", "content": "Write a detailed essay about distributed systems."}
                ],
                "max_tokens": n_tokens,
                "temperature": 0,
                "ignore_eos": True,
            },
        )
        dt = time.monotonic() - t0
        ct = d["usage"]["completion_tokens"]
        rates.append(round(ct / dt, 1))
    return rates

def render_correctness(result: dict) -> str:
    """Render :func:`run_correctness` output as a markdown block for a per-model doc."""
    lines = [
        f"## Assessment — `{result['model']}`",
        "",
        f"- Endpoint: `{result['endpoint']}` · `/health` {result['health']} · "
        f"`max_model_len` {result['max_model_len']}",
        "",
        "| Check | Result |",
        _MD_TABLE_SEP,
    ]
    for p in result["probes"]:
        mark = "PASS" if p["ok"] else "FAIL"
        lines.append(
            f"| {p['label']} | {mark} (finish={p['finish']}, {p['completion_tokens']} tok) |"
        )
    lines.append(
        f"| reasoning trace field | `{result['trace_field']}` (len {result['trace_len']}) |"
    )
    tc = result.get("tool_calling")
    if tc is not None:
        if tc["ok"]:
            detail = f"PASS — called {', '.join(tc['tool_calls'])}"
        else:
            detail = "FAIL — " + (
                tc.get("error") or f"no finish call (tool_calls={tc['tool_calls']})"
            )
        lines.append(f"| tool calling (`tool_choice:auto`) | {detail} |")
    return "\n".join(lines)

def _cosine_similarity(a: list[float], b: list[float]) -> float:
    """Cosine similarity of two equal-length vectors; ``0.0`` for a degenerate (zero) vector."""
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(x * x for x in b))
    # Norms are non-negative; below this epsilon the vector is degenerate and
    # the similarity is meaningless (and the division would explode).
    if norm_a < 1e-12 or norm_b < 1e-12:
        return 0.0
    return dot / (norm_a * norm_b)

def _probe_result(
    role: str, probe: str, ok: bool, evidence: dict, latency_ms: float, error: str | None = None
) -> dict:
    return {
        "role": role,
        "probe": probe,
        "ok": ok,
        "evidence": evidence,
        "latency_ms": round(latency_ms, 1),
        "error": error,
    }

def _find_knee(rows: list[dict], *, threshold: float = 0.1) -> dict:
    """Pure throughput-plateau detector; no network calls.

    Walk *rows* (each a dict with ``"concurrency"`` and ``"requests_per_s"``).
    Stop when the relative gain between consecutive steps falls below *threshold*
    (see :func:`_relative_gain`).

    The *knee* is the concurrency of the last step **before** the gain dropped
    (the peak-throughput concurrency).  ``rows`` in the result contains all rows
    up to (but not including) the declining step.

    Args:
        rows: List of per-step measurement dicts, ordered by ascending concurrency.
        threshold: Minimum relative gain to keep ramping (default 0.1 = 10 %).

    Returns:
        ``{"knee": int, "rows": list[dict]}``
    """
    if not rows:
        return {"knee": 0, "rows": []}
    if len(rows) == 1:
        return {"knee": rows[0]["concurrency"], "rows": list(rows)}

    for i in range(1, len(rows)):
        gain = _relative_gain(rows[i - 1]["requests_per_s"], rows[i]["requests_per_s"])
        if gain is None:
            continue  # guard against degenerate data
        if gain < threshold:
            return {"knee": rows[i - 1]["concurrency"], "rows": rows[:i]}

    # All steps gained enough — last step is the peak.
    return {"knee": rows[-1]["concurrency"], "rows": list(rows)}

def main(argv: list[str] | None = None) -> int:
    # Pre-parse peek so argparse-level errors honour --json.
    _ModelGearArgumentParser._json_hint = _argv_has_json(argv)
    parser = _build_parser()
    args = parser.parse_args(argv)

    if args.command is None:
        parser.print_help()
        return 0

    return _dispatch(args)

def _check(id_: str, passed: bool, severity: str, message: str, remediation: str = "") -> dict:
    """Doctor's own check shape, so `--role` renders through the same path."""
    out = {"id": id_, "passed": passed, "severity": severity, "message": message}
    if remediation:
        out["remediation"] = remediation
    return out

def window_check(
    base_url: str, role: str, advertised: int | None, headers: Mapping[str, str], timeout: float
) -> dict:
    """The SERVED window, from `/tokenize` — the engine's own `max_model_len`.

    This is the check that would have caught #234's first fact directly: the
    engine answers from what it is actually serving, so a disagreement with
    the advert is visible rather than inferred.
    """
    status, body, _ = _request(
        f"{base_url}/tokenize",
        payload={"model": role, "prompt": "hello"},
        headers=headers,
        timeout=timeout,
    )
    if status != 200 or not isinstance(body, dict):
        return _check(
            "served_window",
            False,
            "warn",
            f"/tokenize did not answer for `{role}` (HTTP {status or 'no response'})",
            "a proxied role has no local engine to ask — this is expected off-box; "
            "for a hosted role, check the lane is up ('lobes status')",
        )
    served = body.get("max_model_len")
    if served is None:
        return _check("served_window", False, "warn", "/tokenize reported no max_model_len")
    if advertised is not None and served != advertised:
        return _check(
            "served_window",
            False,
            "error",
            f"advert says {advertised} tokens, engine serves {served}",
            "a consumer sizing work from the advert will overrun the real window; "
            "re-render and restart the gateway so it reads the lane's own value",
        )
    return _check("served_window", True, "info", f"engine serves {served} tokens")

def _generate(
    base_url: str, model: str, headers: Mapping[str, str], timeout: float
) -> tuple[int, dict | None, float]:
    return _request(
        f"{base_url}/v1/chat/completions",
        payload={
            "model": model,
            "messages": _PROBE_MESSAGES,
            "max_tokens": _PROBE_MAX_TOKENS,
            "temperature": 0,
            # See the module docstring: with thinking on, a small budget returns
            # a healthy-looking 200 with empty content.
            "chat_template_kwargs": {"enable_thinking": False},
        },
        headers=headers,
        timeout=timeout,
    )

def _cmd_assess_correctness(
    args: argparse.Namespace, url: str, model: str | None, json_mode: bool
) -> int:
    """Default path: the two fixed correctness probes plus host-side facts."""
    result = _assess.run_correctness(url, model, check_tools=bool(getattr(args, "tools", False)))
    host = {"image": _compose.container_image(), "gpu_memory": _compose.gpu_engine_mem()}
    if json_mode:
        emit_result({**result, "host": host}, json_mode=True)
    else:
        header = (
            "### Host-side\n"
            f"- Image: `{host['image']}`  ·  GPU memory (EngineCore): {host['gpu_memory']}\n"
        )
        emit_result(header + "\n" + _assess.render_correctness(result), json_mode=False)
    return EXIT_SUCCESS

def cmd_assess(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    port, deploy_dir = _runtime_ops.resolve_port_soft(args)
    model = args.model
    if model is None and deploy_dir is not None:
        model = _env.read_env(deploy_dir / _compose.ENV_FILE, "VLLM_SERVED_NAME")

    url = f"http://localhost:{port}"
    headers = _runtime_ops.gateway_auth_headers(deploy_dir)

    with _assess.auth_headers(headers), _runtime_ops.friendly_unauthorized_errors(deploy_dir):
        if bool(getattr(args, "probes", False)):
            return _cmd_assess_probes(args, url, json_mode)
        if bool(getattr(args, "preserve_thinking", False)):
            return _cmd_assess_preserve_thinking(url, model, json_mode)
        if bool(getattr(args, "strict_tools", False)):
            return _cmd_assess_strict_tools(url, model, json_mode)
        return _cmd_assess_correctness(args, url, model, json_mode)

def _render_profile_block(name: str, result: dict) -> str:
    """One profile's markdown block: a side-by-side table, or an unavailable note."""
    lines = [f"### {name}"]
    columns = result["columns"]
    if columns:
        flat_columns = {label: col.get("metrics", {}) for label, col in columns.items()}
        lines.append(render_side_by_side(flat_columns))
    if not result["available"]:
        note = (
            f"_unavailable — {result['reason']}_"
            if not columns
            else f"_partial — {result['reason']}_"
        )
        lines.append(note)
    return "\n".join(lines)

def cmd_benchmark(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    port, deploy_dir = _runtime_ops.resolve_port_soft(args)
    headers = _runtime_ops.gateway_auth_headers(deploy_dir)

    with _assess.auth_headers(headers), _runtime_ops.friendly_unauthorized_errors(deploy_dir):
        if getattr(args, "profile", None):
            return _run_profile_mode(args, json_mode)

        url = f"http://localhost:{port}"

        if bool(getattr(args, "all_lobes", False)):
            return _run_all_lobes(args, url, deploy_dir, json_mode)

        # Original single-model path (unchanged when --all-lobes is absent).
        model = args.model
        if model is None and deploy_dir is not None:
            model = _env.read_env(deploy_dir / _compose.ENV_FILE, "VLLM_SERVED_NAME")

        wl, input_len, output_len = _resolve_shape(args, deploy_dir)
        result = _assess.run_benchmark(
            url,
            model,
            purpose=wl.name,
            input_len=input_len,
            output_len=output_len,
            runs=args.runs,
        )
        host = {"image": _compose.container_image(), "gpu_memory": _compose.gpu_engine_mem()}

        if json_mode:
            emit_result({**result, "host": host}, json_mode=True)
        else:
            header = (
                "### Host-side\n"
                f"- Image: `{host['image']}`  ·  GPU memory (EngineCore): {host['gpu_memory']}\n"
            )
            emit_result(header + "\n" + _assess.render_benchmark(result), json_mode=False)
        return 0

def _parse_schedule(raw: str | None) -> tuple[int, ...]:
    """Parse ``--schedule "1,2,4,8"`` into an ascending tuple of positive ints."""
    if not raw:
        return _DEFAULT_SCHEDULE
    try:
        values = tuple(int(item.strip()) for item in raw.split(",") if item.strip())
    except ValueError as exc:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"--schedule must be a comma-separated list of integers; got {raw!r}",
            remediation="e.g. --schedule 1,2,4,8,16",
        ) from exc
    if not values or any(v <= 0 for v in values):
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"--schedule must contain only positive integers; got {raw!r}",
            remediation="e.g. --schedule 1,2,4,8,16",
        )
    return tuple(sorted(values))

def _render_text(result: dict) -> str:
    lines = [
        f"lobes calibrate — role={result['role']} (backend={result['backend']})",
        f"  concurrency: {result['concurrency']}",
        f"  plateaued:   {result['plateaued']}",
        f"  stopped by:  {_STOPPED_BY_PROSE.get(result['stopped_by'], result['stopped_by'])}",
        "  samples (concurrency, aggregate_tok_s, ttft_s):",
    ]
    for concurrency, tok_s, ttft_s in result["samples"]:
        lines.append(f"    {concurrency:>4}  {tok_s:>10.2f} tok/s  {ttft_s:>8.3f} s")
    if result["applied"]:
        lines.append(f"  wrote {result['env_key']}={result['concurrency']} to .env")
    elif result.get("refused"):
        lines.append(f"  --apply refused: {result['refused']}")
    else:
        lines.append("  (dry run — pass --apply to write this to .env)")
    return "\n".join(lines)

def _tri(value: object) -> str:
    """Render a nullable bool as yes/no/unknown — never guess a null."""
    if value is None:
        return "unknown"
    return "yes" if value else "no"

def _render_replicas_section(registry: dict[str, dict]) -> str:
    lines: list[str] = []
    for role in ROLES:
        rows = registry[role].get("replicas")
        if not rows:
            continue
        if lines:
            lines.append("")
        lines.extend(_render_replica_lines(role, rows))
    if not lines:
        lines.append("(no replica set declared for any role)")
    return "\n".join(lines)

def cmd_endpoint(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    replicas_mode = bool(getattr(args, "replicas", False))
    role = args.role
    if role not in ROLES:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"unknown role {role!r}",
            remediation=f"valid roles: {', '.join(ROLES)}",
        )
    _port, deploy_dir = _runtime_ops.resolve_port_soft(args)
    with _runtime_ops.friendly_unauthorized_errors(deploy_dir):
        payload, _source = _capabilities_view(args)
    endpoint = payload[role]["endpoint"]
    if json_mode:
        emit_result({"role": role, "endpoint": endpoint}, json_mode=True)
    else:
        lines = [endpoint]
        if replicas_mode:
            rows = payload[role].get("replicas")
            if rows:
                lines.extend(_render_replica_lines(role, rows))
            else:
                lines.append("(no replica set declared for this role)")
        emit_result("\n".join(lines), json_mode=False)
    return 0

def _culture_model_tail() -> str | None:
    """The model name after ``vllm-local/`` in ``culture.yaml`` (or ``None``)."""
    cfg = _find_culture_yaml()
    if cfg is None:
        return None
    try:
        text = cfg.read_text(encoding="utf-8")
    except OSError:
        return None
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith("model:"):
            _, _, value = stripped.partition("model:")
            value = value.strip().strip("'\"")
            prefix = "vllm-local/"
            return value[len(prefix) :] if value.startswith(prefix) else value
    return None

def _check(id_: str, passed: bool, severity: str, message: str, remediation: str = "") -> dict:
    return {
        "id": id_,
        "passed": passed,
        "severity": severity,
        "message": message,
        "remediation": remediation,
    }

def _docker_check() -> dict:
    ok = _compose.docker_available()
    return _check(
        "docker_available",
        ok,
        "error",
        "docker + docker compose are available" if ok else "docker / docker compose not found",
        "" if ok else "install Docker + the NVIDIA Container Toolkit",
    )

def _env_coherence_check(env_path) -> dict:
    served = _env.read_env(env_path, "VLLM_SERVED_NAME")
    expected = _culture_model_tail()
    if not served:
        return _check(
            "env_coherence",
            False,
            "warn",
            "VLLM_SERVED_NAME is not set in .env",
            "set it, or run 'lobes switch <model> --apply'",
        )
    if expected and served != expected:
        return _check(
            "env_coherence",
            False,
            "warn",
            f"VLLM_SERVED_NAME ({served}) != culture.yaml model tail ({expected})",
            "align them so the acp vllm-local provider resolves the model",
        )
    return _check("env_coherence", True, "info", f"VLLM_SERVED_NAME = {served}")

def _health_check(port: int) -> dict:
    healthy = _health.is_healthy(port)
    return _check(
        "health_reachable",
        healthy,
        "info",
        f"/health responding on :{port}" if healthy else f"/health not responding on :{port}",
        "" if healthy else "start the server with 'lobes serve --apply'",
    )

def _gateway_relevant_keys() -> tuple[str, ...]:
    """Every ``.env`` key the deployed gateway service is expected to read.

    Purely a naming enumeration (role prefix x suffix, plus the two
    singletons) — it does not read any file itself.
    """
    keys: list[str] = list(_GATEWAY_SINGLETON_KEYS)
    for prefix in _GATEWAY_ROLE_PREFIXES:
        for suffix in _GATEWAY_PEER_SUFFIXES + _GATEWAY_FINGERPRINT_SUFFIXES:
            keys.append(f"{prefix}_{suffix}")
    return tuple(keys)

def _parse_env_text(text: str) -> dict[str, str]:
    """``KEY=VALUE`` lines from template text — same contract as
    :func:`lobes.runtime._env.read_env_file`, which only reads paths."""
    out: dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.split("#", 1)[0].strip()
        if not stripped or "=" not in stripped:
            continue
        key, _, value = stripped.partition("=")
        if key.strip():
            out[key.strip()] = value.strip()
    return out

def _template_env_defaults() -> dict[str, str]:
    """The fleet ``env.example`` defaults, keyed by env var."""
    root = _resource_files(_TEMPLATES_PACKAGE)
    return _parse_env_text(_compose._read_template(root, "fleet/env.example"))

def _audio_env_defaults() -> dict[str, str]:
    """The audio overlay's ``env.audio.example`` defaults, keyed by env var."""
    root = _resource_files(_TEMPLATES_PACKAGE)
    return _parse_env_text(_compose._read_template(root, _compose.AUDIO_ENV_TEMPLATE))

def _audio_he_env_defaults() -> dict[str, str]:
    """The Hebrew overlay's ``env.audio-he.example`` defaults, keyed by env var."""
    root = _resource_files(_TEMPLATES_PACKAGE)
    return _parse_env_text(_compose._read_template(root, _compose.AUDIO_HE_ENV_TEMPLATE))

def _dropped_role_prefixes(deploy_dir: Path) -> tuple[str, ...]:
    """``PREFIX_`` env prefixes of the core roles the deployment SHAPE drops.

    Read back from the generated ``docker-compose.shape.yml`` (the single
    source of truth for the drop decision) so the staleness diff never demands
    knobs for a lobe this box deliberately does not host.

    Only the PARKED blocks count (:func:`lobes.runtime._compose.shape_parked_service_keys`):
    the same file also carries start-order reversals and, when
    ``INNEREYE_UI_PORT`` is set, a ``comfyui`` block that publishes the lane
    rather than dropping it — reading those as drops would silently stop
    checking a hosted role's knobs.
    """
    path = deploy_dir / _compose.SHAPE_OVERLAY
    if not path.is_file():
        return ()
    services = _compose.shape_parked_service_keys(path.read_text(encoding="utf-8")) - {"gateway"}
    service_to_role = {service: role for role, service in ROLE_SERVICE.items()}
    return tuple(
        ROLE_ENV_PREFIX[service_to_role[s]] + "_"
        for s in sorted(services)
        if s in service_to_role and service_to_role[s] in ROLE_ENV_PREFIX
    )

def _scaffold_files_check(deploy_dir: Path) -> tuple[dict, list[str]]:
    """Every expected scaffold file exists — the 2026-07-17 Spark incident was
    files silently absent (audio Dockerfiles) with ``/health`` green for hours."""
    expected = list(_expected_templates(deploy_dir).values())
    plugin_dest, plugin_exists = _compose.plugin_plan(deploy_dir)
    missing = sorted(dest for dest in expected if not (deploy_dir / dest).exists())
    if not plugin_exists:
        missing.append(plugin_dest)
    if missing:
        return (
            _check(
                "scaffold_files",
                False,
                "warn",
                f"missing scaffold file(s): {', '.join(missing)} — the lanes built "
                "from them cannot start",
                _FIX_REMEDIATION,
            ),
            missing,
        )
    return (
        _check(
            "scaffold_files",
            True,
            "info",
            f"all {len(expected) + 1} expected scaffold files present",
        ),
        [],
    )

def _resolve_deployment_profile(deploy_dir: Path, recorded: str | None):
    """``(profile, note)`` — the profile this deployment should be checked
    against, resolved via the SAME path ``lobes init`` uses (no forked render).

    A recorded ``LOBES_PROFILE`` wins (it is what the operator's deployment
    claims to be); an unresolvable recorded name degrades to detection with a
    note rather than failing the whole check.
    """
    try:
        profile, _card, warning = resolve_init_profile(recorded, deploy_dir)
        return profile, warning
    except ModelGearError as err:
        profile, _card, _warning = resolve_init_profile(None, deploy_dir)
        return profile, (
            f"recorded LOBES_PROFILE {recorded!r} did not resolve ({err.message}); "
            "checked against card detection instead"
        )

def _staleness_ok(profile_name: str, overridden: list[str], detail: str) -> dict:
    """The passing verdict — operator overrides only ever annotate it."""
    message = f"profile {profile_name}: every required .env key is present"
    if overridden:
        message += f" ({len(overridden)} operator-set value(s) differ — legitimate)"
    if detail:
        message += f" [{detail}]"
    return _check("profile_staleness", True, "info", message)

def _staleness_failure(
    profile_name: str, missing: dict[str, str], stale: list[str], detail: str
) -> dict:
    """The warn verdict — missing keys are fixable, stale ones named for the operator."""
    parts: list[str] = []
    remediations: list[str] = []
    if missing:
        shown = ", ".join(sorted(missing)[:6])
        more = "" if len(missing) <= 6 else f" (+{len(missing) - 6} more)"
        parts.append(f"{len(missing)} required key(s) missing from .env: {shown}{more}")
        remediations.append(_FIX_REMEDIATION)
    if stale:
        parts.append(
            f"{len(stale)} key(s) still carry the template default where profile "
            f"{profile_name} requires a divergence: {', '.join(stale)}"
        )
        remediations.append(
            "set the divergent key(s) in .env yourself — doctor --fix never "
            "rewrites an existing line"
        )
    if detail:
        parts.append(detail)
    return _check("profile_staleness", False, "warn", "; ".join(parts), "; ".join(remediations))

def _staleness_verdict(
    profile_name: str,
    missing: dict[str, str],
    stale: list[str],
    overridden: list[str],
    notes: list[str],
) -> dict:
    """Fold the staleness diff into one check dict (missing/stale warn; overrides info)."""
    detail = "; ".join(notes) if notes else ""
    if not missing and not stale:
        return _staleness_ok(profile_name, overridden, detail)
    return _staleness_failure(profile_name, missing, stale, detail)

def _lock_drift_check(deploy_dir: Path) -> dict | None:
    """The deployed files/env still match the committed ``deployment.lock.toml``.

    Returns ``None`` — no finding at all — when no lock is present: absence of
    a lock is not drift, and a deployment that has never adopted the lock
    practice must behave exactly as it did before this check existed.

    Names the SPECIFIC differing files and locked keys (never merely "drift
    exists"), mirroring :func:`_scaffold_files_check`'s precedent. Read-only:
    this never writes anything, so it does not interact with ``--fix`` at all
    (``_apply_fix`` never calls it) — the never-rewrite-an-existing-.env-line
    convention is untouched by this check's existence.
    """
    path = deploy_dir / LOCK_FILENAME
    if not path.is_file():
        return None
    lock = load_lock(path)
    file_diffs = _lock_file_diffs(deploy_dir, lock.files)
    env_diffs = _lock_env_diffs(deploy_dir, lock.env)
    if not file_diffs and not env_diffs:
        return _check("lock_drift", True, "info", f"deployed files and env match {LOCK_FILENAME}")
    parts = []
    if file_diffs:
        parts.append(
            f"{len(file_diffs)} file(s) differ from {LOCK_FILENAME}: {', '.join(file_diffs)}"
        )
    if env_diffs:
        parts.append(
            f"{len(env_diffs)} locked key(s) differ from {LOCK_FILENAME}: {', '.join(env_diffs)}"
        )
    return _check("lock_drift", False, "warn", "; ".join(parts), _LOCK_DRIFT_REMEDIATION)

def _write_missing_file(deploy_dir: Path, dest: str, by_dest: dict[str, str]) -> None:
    """Materialise ONE absent scaffold file from its packaged template."""
    if dest == _compose.PLUGIN_DEST_NAME:
        _compose.write_plugin_file(deploy_dir, force=False)
        return
    target = deploy_dir / dest
    root = _resource_files(_TEMPLATES_PACKAGE)
    target.write_text(_compose._read_template(root, by_dest[dest]), encoding="utf-8")
    if dest == _compose.ENV_FILE:
        try:
            target.chmod(0o600)  # secrets file — owner-only, like the scaffold
        except OSError:
            pass

def _write_missing_files(deploy_dir: Path, missing_files: list[str]) -> list[str]:
    actions: list[str] = []
    by_dest = {dest: name for name, dest in _expected_templates(deploy_dir).items()}
    for dest in missing_files:
        if (deploy_dir / dest).exists():  # missing-only, by construction; never overwrite
            continue
        _write_missing_file(deploy_dir, dest, by_dest)
        actions.append(f"wrote {dest}")
    return actions

def _append_missing_env(deploy_dir: Path, missing_env: dict[str, str]) -> list[str]:
    if not missing_env:
        return []
    env_path = deploy_dir / _compose.ENV_FILE
    with env_path.open("a", encoding="utf-8") as fh:
        fh.write("\n# --- appended by 'lobes doctor --fix --apply' (missing-only heal, #119) ---\n")
        for key in sorted(missing_env):
            fh.write(f"{key}={missing_env[key]}\n")
    return [f"appended {key}" for key in sorted(missing_env)]

def _mark(check: dict) -> str:
    if check["passed"]:
        return "ok"
    return "FAIL" if check["severity"] == "error" else check["severity"]

def _render_check_lines(checks: list[dict]) -> list[str]:
    """Render one ``[mark] id: message`` line per check, plus a remediation
    hint line for any that failed with one."""
    lines: list[str] = []
    for check in checks:
        lines.append(f"[{_mark(check)}] {check['id']}: {check['message']}")
        if not check["passed"] and check["remediation"]:
            lines.append(f"  hint: {check['remediation']}")
    return lines

def _render_machine_profile_lines(mp: dict) -> list[str]:
    """Render the ``machine profile:`` section (detected card, active
    profile, and any mismatch/unknown-card warning)."""
    lines = ["", "machine profile:", f"  detected card: {mp['detected_card']}"]
    if mp["device_name"]:
        lines.append(f"  device:       {mp['device_name']}")
    if mp["compute_capability"]:
        lines.append(f"  compute:      {mp['compute_capability']}")
    if mp["total_memory_gb"]:
        lines.append(f"  memory:       {mp['total_memory_gb']} GB")
    if mp["profile"]:
        lines.append(f"  profile:      {mp['profile']}")
        if not mp["validated"]:
            lines.append("  status:       NOT VALIDATED FOR THIS CARD (forced/unvalidated)")
    if mp.get("warning"):
        lines.append(f"  warning:      {mp['warning']}")
    return lines

def _render_fix_plan_lines(plan: dict, *, applied: list[str] | None) -> list[str]:
    """The ``--fix`` section: the missing-only heal plan, or what was applied."""
    if applied is not None:
        lines = ["", "fix applied (missing-only heal, #119):"]
        lines.extend(f"  {action}" for action in applied)
        if not applied:
            lines.append("  nothing to heal — no absent files or keys")
        return lines
    files = plan.get("files") or []
    env = plan.get("env") or {}
    lines = ["", "fix plan (DRY RUN — re-run with --fix --apply to write):"]
    lines.extend(f"  would write {dest}" for dest in files)
    lines.extend(f"  would append {key}={env[key]}" for key in sorted(env))
    if not files and not env:
        lines.append("  nothing to heal — no absent files or keys")
    return lines

def _render_text(report: dict) -> str:
    status = "healthy" if report["healthy"] else "unhealthy"
    lines = [f"lobes doctor: {status}", ""]
    lines.extend(_render_check_lines(report["checks"]))
    if "machine_profile" in report:
        lines.extend(_render_machine_profile_lines(report["machine_profile"]))
    if "fix_plan" in report and report.get("fix_requested"):
        lines.extend(_render_fix_plan_lines(report["fix_plan"], applied=report.get("fix_applied")))
    if report.get("repin_requested"):
        lines.extend(_render_repin_lines(report))
    return "\n".join(lines)

def _load_suite(path: Path) -> list[dict]:
    """Load and parse a JSONL suite file; return a list of case dicts.

    Raises :class:`ModelGearError` if the file is missing or a data line is
    malformed / missing required fields.
    """
    if not path.exists():
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"suite file not found: {path}",
            remediation="pass an existing .jsonl file path via --suite",
        )

    cases: list[dict] = []
    for lineno, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            obj = json.loads(stripped)
        except json.JSONDecodeError as exc:
            raise ModelGearError(
                code=EXIT_USER_ERROR,
                message=f"suite parse error at line {lineno}: {exc}",
                remediation="every non-blank, non-comment line must be valid JSON",
            ) from exc
        if "prompt" not in obj:
            raise ModelGearError(
                code=EXIT_USER_ERROR,
                message=f"suite line {lineno}: missing required field 'prompt'",
                remediation="each case object must have a 'prompt' string field",
            )
        if "expect_substring" not in obj and "expect_regex" not in obj:
            raise ModelGearError(
                code=EXIT_USER_ERROR,
                message=(
                    f"suite line {lineno}: no expectation field "
                    "(need 'expect_substring' or 'expect_regex')"
                ),
                remediation=(
                    "add 'expect_substring' (substring check) "
                    "or 'expect_regex' (re.search pattern) to the case"
                ),
            )
        cases.append(obj)
    return cases

def _check(response: str, case: dict) -> bool:
    """Return ``True`` if *response* satisfies the case expectation."""
    if "expect_substring" in case:
        return case["expect_substring"] in response
    if "expect_regex" in case:
        return bool(re.search(case["expect_regex"], response))
    return False  # unreachable after _load_suite validation

def _validate_cat_entry(obj: dict, lineno: int) -> None:
    """Validate one cat-suite case object; raise :class:`ModelGearError` on any problem.

    Ensures ``seed`` is present and integer-valued, and that the optional
    ``mode`` / ``n_characters`` fields (when present) are well-formed — so a
    malformed suite produces a structured error here rather than an uncaught
    ``ValueError`` later in :func:`cmd_eval_cat`.
    """
    if "seed" not in obj:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"suite line {lineno}: missing required field 'seed'",
            remediation="each cat-suite case object must have an integer 'seed' field",
        )
    try:
        int(obj["seed"])
    except (TypeError, ValueError):
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"suite line {lineno}: 'seed' must be an integer, got {obj['seed']!r}",
            remediation="set 'seed' to an integer value (e.g. 42)",
        )
    if "mode" in obj and obj["mode"] not in _CAT_VALID_MODES:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=(
                f"suite line {lineno}: invalid 'mode' {obj['mode']!r} "
                + f"(must be one of {_CAT_VALID_MODES})"
            ),
            remediation="set 'mode' to 'open' or 'closed'",
        )
    if "n_characters" in obj:
        try:
            if int(obj["n_characters"]) < 1:
                raise ValueError("non-positive")
        except (TypeError, ValueError):
            raise ModelGearError(
                code=EXIT_USER_ERROR,
                message=(
                    f"suite line {lineno}: 'n_characters' must be a positive integer, "
                    + f"got {obj['n_characters']!r}"
                ),
                remediation="set 'n_characters' to a positive integer (e.g. 4)",
            )

def cmd_eval_minor(args: argparse.Namespace) -> int:
    """Handler for ``lobes eval minor``."""
    json_mode = bool(getattr(args, "json", False))
    suite_path = Path(str(args.suite))
    base_url: str = getattr(args, "base_url", _DEFAULT_BASE_URL) or _DEFAULT_BASE_URL
    model: str = getattr(args, "model", None) or ""
    timeout: int = int(getattr(args, "timeout", _DEFAULT_TIMEOUT))

    cases = _load_suite(suite_path)

    results: list[dict] = []
    for idx, case in enumerate(cases):
        response = chat_text(
            case["prompt"],
            base_url=base_url,
            model=model,
            timeout=timeout,
        )
        passed = _check(response, case)
        expectation: dict = {}
        if "expect_substring" in case:
            expectation = {"expect_substring": case["expect_substring"]}
        elif "expect_regex" in case:
            expectation = {"expect_regex": case["expect_regex"]}
        results.append(
            {
                "index": idx,
                "prompt": case["prompt"],
                "response": response,
                "pass": passed,
                "expectation": expectation,
            }
        )

    passed_count = sum(1 for r in results if r["pass"])
    total = len(results)

    report: dict = {
        "passed": passed_count,
        "total": total,
        "cases": results,
    }

    if json_mode:
        emit_result(report, json_mode=True)
    else:
        lines: list[str] = []
        for r in results:
            status = "PASS" if r["pass"] else "FAIL"
            lines.append(f"  [{status}] case {r['index']}: {r['prompt']!r}")
        lines.append(f"result: {passed_count}/{total} passed")
        emit_result("\n".join(lines), json_mode=False)

    return 0

def cmd_explain(args: argparse.Namespace) -> int:
    path = tuple(args.path) if args.path else ()
    markdown = resolve(path)  # raises ModelGearError on miss → caught in _dispatch
    json_mode = bool(getattr(args, "json", False))
    if json_mode:
        emit_result({"path": list(path), "markdown": markdown}, json_mode=True)
    else:
        emit_result(markdown, json_mode=False)
    return 0

def _fleet_models(port: int) -> list[str] | None:
    """Best-effort ``/v1/models`` ids via the gateway; ``None`` if unreachable."""
    if not _health.is_healthy(port):
        return None
    try:
        _, payload = assess._get(f"http://localhost:{port}", "/v1/models")
        data = payload.get("data") if isinstance(payload, dict) else None
        return [m.get("id") for m in data] if isinstance(data, list) else None
    except OSError:
        return None

def cmd_fleet_up(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    deploy_dir = _runtime_ops.deployment_dir(args)
    env_path = deploy_dir / _compose.ENV_FILE
    port = _runtime_ops.resolve_port(args, env_path)

    if not args.apply:
        msg = (
            f"DRY RUN — would run: docker compose up -d --build in {deploy_dir}, "
            f"then wait for the gateway /health on :{port}.\nRe-run with --apply to execute."
        )
        payload = {"dry_run": True, "deployment_dir": str(deploy_dir), "port": port}
        emit_result(payload if json_mode else msg, json_mode=json_mode)
    else:
        emit_diagnostic(f">> building + starting the fleet in {deploy_dir}")
        # Ensure the durable-log dir exists (user-owned) before compose bind-mounts it.
        _compose.ensure_log_dir(deploy_dir, _env.read_env(env_path, _compose.LOG_DIR_ENV) or None)
        _runtime_ops.compose_check(
            _compose.compose_up_build(deploy_dir), "docker compose up -d --build"
        )
        # The gateway answers /health within seconds (it doesn't block on backends);
        # the vLLM backends load in the background — check them via 'lobes fleet status'.
        _health.wait_health(
            port, deadline_seconds=120, interval=5, container=_compose.FLEET_GATEWAY
        )
        result = {
            "serving": True,
            "port": port,
            "deployment_dir": str(deploy_dir),
            "containers": list(_compose.fleet_containers(deploy_dir)),
        }
        text = (
            f">> gateway up on :{port}. Backends load in the background — "
            f"check: lobes fleet status --compose-dir {deploy_dir}"
        )
        emit_result(result if json_mode else text, json_mode=json_mode)
    return 0

def cmd_fleet_down(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    deploy_dir = _runtime_ops.deployment_dir(args)

    if not args.apply:
        dry = (
            f"DRY RUN — would run: docker compose down in {deploy_dir}.\n"
            "Re-run with --apply to execute."
        )
        payload = {"dry_run": True, "deployment_dir": str(deploy_dir)}
        emit_result(payload if json_mode else dry, json_mode=json_mode)
    else:
        emit_diagnostic(f">> stopping the fleet in {deploy_dir}")
        _runtime_ops.compose_check(_compose.compose_down(deploy_dir), "docker compose down")
        result = {"stopped": True, "deployment_dir": str(deploy_dir)}
        emit_result(
            result if json_mode else f">> fleet stopped in {deploy_dir}", json_mode=json_mode
        )
    return 0

def cmd_fleet_status(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    deploy_dir = _runtime_ops.deployment_dir(args)
    env_path = deploy_dir / _compose.ENV_FILE
    port = _runtime_ops.resolve_port(args, env_path)

    containers = [
        {"name": name, "state": _compose.inspect_state(name)}
        for name in _compose.fleet_containers(deploy_dir)
    ]
    report = {
        "deployment_dir": str(deploy_dir),
        "port": port,
        "gateway_health": "ok" if _health.is_healthy(port) else "not responding",
        "containers": containers,
        "models": _fleet_models(port),
    }

    if json_mode:
        emit_result(report, json_mode=True)
    else:
        lines = [
            f"dir:     {report['deployment_dir']}",
            f"gateway: {report['gateway_health']} (:{port})",
        ]
        for c in containers:
            lines.append(f"  {c['name']} — {c['state']}")
        models = report["models"]
        lines.append("models:  " + (", ".join(models) if models else _UNSET))
        emit_result("\n".join(lines), json_mode=False)
    return 0

def _innereye_ui_reject(value: str, reason: str) -> "ModelGearError":
    """The one rejection shape: a user error naming the rule and the grammar."""
    return ModelGearError(
        code=EXIT_USER_ERROR,
        message=f"invalid {INNEREYE_UI_PORT_KEY}={value!r}: {reason}",
        remediation=_INNEREYE_UI_HINT,
    )

def _is_ipv6_literal(text: str) -> bool:
    try:
        ipaddress.IPv6Address(text)
    except ValueError:
        return False
    return True

def _innereye_ui_valid_host(host: str) -> bool:
    """Is ``host`` a plausible LITERAL bind interface?

    IPv4 address, bracketed IPv6 literal (with an optional ``%zone``), or a
    hostname. An all-digits host is refused on purpose: ``8188:8188`` reads as
    docker's ``hostPort:containerPort``, but this knob's container port is
    fixed, so it would render the nonsense bind ``8188:8188:8188``.
    """
    if host.startswith("[") or host.endswith("]"):
        if not (host.startswith("[") and host.endswith("]")):
            return False
        addr, sep, zone = host[1:-1].partition("%")
        if sep and not _HOSTNAME_LABEL.match(zone):
            return False
        return _is_ipv6_literal(addr)
    if set(host) & set(":[]%"):
        return False
    if not host:
        return False
    if set(host) <= set(string.digits + "."):
        # Digits and dots can only be an IPv4 address; `256.0.0.1` and `8188`
        # must not fall through to the hostname rule and be accepted as names.
        try:
            ipaddress.IPv4Address(host)
        except ValueError:
            return False
        return True
    if len(host) > 253:
        return False
    return all(_HOSTNAME_LABEL.match(label) for label in host.split("."))

def _innereye_ui_split(value: str, spec: str) -> tuple[str, str]:
    """Split a bind value into ``(host, port)``, defaulting the host to loopback."""
    if spec.startswith("["):
        end = spec.find("]")
        if end == -1:
            raise _innereye_ui_reject(value, "unterminated IPv6 bracket")
        host, rest = spec[: end + 1], spec[end + 1 :]
        if not rest.startswith(":"):
            raise _innereye_ui_reject(value, "expected [ipv6]:port")
        return host, rest[1:]
    if ":" not in spec:
        return _INNEREYE_UI_DEFAULT_HOST, spec
    if spec.count(":") > 1:
        if _is_ipv6_literal(spec):
            raise _innereye_ui_reject(value, "bare IPv6 literal — bracket it, then add the port")
        raise _innereye_ui_reject(value, "too many colons for <interface>:<port>")
    host, _sep, port = spec.partition(":")
    return host, port

def _shape_override_plan(target: Path, shape: Shape, profile: Profile) -> dict:
    """What ``--apply`` would do to ``docker-compose.shape.yml`` — for the dry-run plan.

    ``action`` is ``write`` (shape drops a lobe, or the deployment publishes the
    ComfyUI UI), ``remove`` (a stale override is on disk but the selected shape
    drops nothing and nothing is published), or ``none``.
    """
    dropped = _shape_dropped_services(shape, profile)
    publish = innereye_ui_publish(_innereye_ui_value(target))
    base = {"file": _compose.SHAPE_OVERLAY, "disables": dropped, "innereye_ui": publish}
    if dropped or publish is not None:
        return {**base, "action": "write"}
    if (target / _compose.SHAPE_OVERLAY).exists():
        return {**base, "action": "remove", "disables": []}
    return {**base, "action": "none", "disables": []}

def _shape_override_plan_line(plan: dict) -> str | None:
    """A human dry-run line for the shape-override plan, or ``None`` when nothing changes."""
    if plan["action"] == "write":
        what = []
        if plan["disables"]:
            what.append(
                f"parks {', '.join(plan['disables'])} in the inert "
                f"'{SHAPE_DROPPED_PROFILE}' profile"
            )
        if plan["innereye_ui"]:
            what.append(
                f"PUBLISHES ComfyUI's unauthenticated web UI on {plan['innereye_ui']} "
                f"({INNEREYE_UI_PORT_KEY})"
            )
        return f"  {plan['file']} ({'; '.join(what)})"
    if plan["action"] == "remove":
        return f"  {plan['file']} (stale — would be REMOVED: this shape drops no lobe)"
    return None

def _gpu_override_plan(target: Path, profile: Profile) -> dict:
    """What ``--apply`` would do to the GPU overrides — for the dry-run plan.

    ``action`` is ``write`` (the card declares csv-mode GPU access), ``remove``
    (stale files on disk but this card takes the default), or ``none``.
    """
    files = _gpu_override_files()
    if profile.gpu_access == GPU_ACCESS_RUNTIME:
        return {"files": files, "action": "write", "gpu_access": profile.gpu_access}
    if any((target / name).exists() for name in files):
        return {"files": files, "action": "remove", "gpu_access": profile.gpu_access}
    return {"files": [], "action": "none", "gpu_access": profile.gpu_access}

def _gpu_override_plan_line(plan: dict) -> str | None:
