                "/mesh/revoke",
                plan,
                headers={"Authorization": f"Bearer {key}"},
                timeout=5.0,
            )
        except urllib.error.HTTPError as exc:
            raise ModelGearError(
                code=EXIT_USER_ERROR,
                message=f"/mesh/revoke refused ({exc.code}): {exc.reason}",
                remediation="check the name and the configured LOBES_MESH_KEY",
            ) from exc
    result = {"status": status, "response": body, "plan": plan}
    if json_mode:
        emit_result(result, json_mode=True)
    else:
        emit_result(f">> revoked {args.name!r} — HTTP {status}", json_mode=False)
    return 0

def _docs_dir() -> Path | None:
    here = Path(__file__).resolve()
    for parent in here.parents:
        d = parent / "docs"
        if d.is_dir():
            return d
    return None

def _first_heading(path: Path) -> str:
    try:
        for line in path.read_text(encoding="utf-8").splitlines():
            if line.startswith("# "):
                return line[2:].strip()
    except OSError:
        pass
    return path.stem

def _served_section(ident: dict) -> dict[str, object]:
    gear = ident.get("gear", {})
    return {
        "title": "Currently served",
        "items": [
            f"model: {ident['served_model']}",
            f"port: {ident['port']}",
            f"gear: {gear.get('purpose', 'balanced')} / {gear.get('machine', 'spark')}",
            f"container health: {ident['container_health']}",
        ],
    }

def _candidates_section(ident: dict, candidates: list[dict[str, str]]) -> dict[str, object]:
    base = str(ident["served_model"]).split("/")[-1].lower()
    items = []
    for c in candidates:
        stem = Path(c["doc"]).stem.lower()
        served = base and (base in stem or stem in base)
        items.append(f"{c['doc']} — {c['title']}" + (" (served)" if served else ""))
    if not items:
        items = ["(no supported models in the catalog)"]
    return {"title": "Supported models", "items": items}

def cli_sections() -> list[dict[str, object]]:
    """Sections describing the CLI surface itself (used by `cli overview`)."""
    return [
        {
            "title": "Verbs",
            "items": list(_VERBS) + ["cli overview — describe the CLI surface (this command)"],
        },
        {
            "title": "Conventions",
            "items": [
                "every command supports --json",
                "write verbs (switch/serve/stop/up/init/fleet/tunnel) are dry-run by default; "
                "--apply to commit",
                "results to stdout, errors/diagnostics to stderr (never mixed)",
                "exit codes: 0 success, 1 user error, 2 environment error, 3+ reserved",
            ],
        },
    ]

def render_text(subject: str, sections: list[dict[str, object]]) -> str:
    lines = [f"# {subject}", ""]
    for section in sections:
        lines.append(f"## {section['title']}")
        for item in section["items"]:
            lines.append(f"- {item}")
        lines.append("")
    return "\n".join(lines).rstrip()

def emit_overview(subject: str, sections: list[dict[str, object]], *, json_mode: bool) -> None:
    if json_mode:
        emit_result({"subject": subject, "sections": sections}, json_mode=True)
    else:
        emit_result(render_text(subject, sections), json_mode=False)

def _served_name(args: argparse.Namespace) -> str | None:
    """Configured served-model name from ``.env`` (best-effort; None if unscaffolded).

    Resolved independently of the probed port so ``overview --live --port N`` still
    labels the model from the deployment's ``.env``.
    """
    try:
        deploy_dir = _compose.resolve_deployment_dir(getattr(args, "compose_dir", None))
    except ModelGearError:
        return None
    env_path = deploy_dir / _compose.ENV_FILE
    return (
        _env.read_env(env_path, "VLLM_SERVED_NAME") or _env.read_env(env_path, "VLLM_MODEL") or None
    )

def _parse_model_response(content: str) -> dict:
    """Parse the model's routing response JSON.

    Strategy (fail-safe):
    1. Try to parse the entire content as JSON.
    2. Try to extract the first ``{...}`` block via regex.
    3. Fall back to a safe default (primary, low confidence).
    """
    # 1. Direct JSON parse
    try:
        return json.loads(content)
    except json.JSONDecodeError:
        pass

    # 2. Regex extraction of the first { … } block
    m = re.search(r"\{.*\}", content, re.DOTALL)
    if m:
        try:
            return json.loads(m.group())
        except json.JSONDecodeError:
            pass

    # 3. Safe fallback
    return {
        "chosen_gear": "primary",
        "confidence": _DEFAULT_CONFIDENCE,
        "reason": "Could not parse model response; defaulting to primary.",
        "conditions": [],
    }

def cmd_serve(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    deploy_dir = _runtime_ops.deployment_dir(args)
    env_path = deploy_dir / _compose.ENV_FILE
    port = _runtime_ops.resolve_port(args, env_path)

    if not args.apply:
        if json_mode:
            emit_result(
                {"dry_run": True, "deployment_dir": str(deploy_dir), "port": port},
                json_mode=True,
            )
        else:
            emit_result(
                f"DRY RUN — would run: docker compose up -d in {deploy_dir}, "
                f"then wait for health on :{port}.\nRe-run with --apply to execute.",
                json_mode=False,
            )
    else:
        emit_diagnostic(f">> starting the vLLM server in {deploy_dir}")
        # Ensure the durable-log dir exists (user-owned) before compose bind-mounts it.
        _compose.ensure_log_dir(deploy_dir, _env.read_env(env_path, _compose.LOG_DIR_ENV) or None)
        _runtime_ops.compose_check(_compose.compose_up_detached(deploy_dir), "docker compose up -d")
        _health.wait_health(port, container=_liveness_container(deploy_dir, env_path))
        result = {"serving": True, "port": port, "deployment_dir": str(deploy_dir)}
        tc = None
        if not args.no_probe:
            served = _env.read_env(env_path, "VLLM_SERVED_NAME") or _env.read_env(
                env_path, "VLLM_MODEL"
            )
            tc = _runtime_ops.probe_tool_calling(port, served)
        result["tool_calling"] = tc
        if json_mode:
            emit_result(result, json_mode=True)
        else:
            out = [f">> serving on :{port}. assess with: lobes assess --port {port}"]
            if tc is not None:
                out.append(">> " + _runtime_ops.format_tool_probe(tc))
            emit_result("\n".join(out), json_mode=False)
    return 0

def _cmd_status_fleet(deploy_dir, env_path, port: int, json_mode: bool) -> int:
    """Render ``lobes status`` for a fleet deployment (one line per container)."""
    containers = [
        {"name": name, "state": _compose.inspect_state(name)}
        for name in _compose.fleet_containers(deploy_dir)
    ]
    report = {
        "model": _env.read_env(env_path, "VLLM_MODEL", _UNSET),
        "served_name": _env.read_env(env_path, "VLLM_SERVED_NAME", _UNSET),
        "port": port,
        "tool_call_parser": _env.read_env(env_path, "VLLM_TOOL_CALL_PARSER", _UNSET),
        "deployment_dir": str(deploy_dir),
        "deployment": "fleet",
        "containers": containers,
        "health": "ok" if _health.is_healthy(port) else "not responding",
        "profile": _env.read_env(env_path, "LOBES_PROFILE", _UNSET),
    }

    if json_mode:
        emit_result(report, json_mode=True)
    else:
        lines = [
            f"model:  {report['model']}",
            f"served: {report['served_name']}  port: {report['port']}",
            f"parser: {report['tool_call_parser']}",
            f"dir:    {report['deployment_dir']}",
        ]
        for c in containers:
            lines.append(f"  {c['name']} — {c['state']}")
        lines.append(f"health: {report['health']} (:{port})")
        if report["profile"] != _UNSET:
            lines.append(f"profile: {report['profile']}")
        lines.append("see 'lobes fleet status' / 'lobes capabilities' for the full fleet/role view")
        emit_result("\n".join(lines), json_mode=False)
    return 0

def cmd_status(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))

    # --pressure path: /proc sampler only — no deploy dir, no docker, no .env.
    if getattr(args, "pressure", False):
        return _cmd_status_pressure(json_mode)

    deploy_dir = _runtime_ops.deployment_dir(args)
    env_path = deploy_dir / _compose.ENV_FILE
    port = _runtime_ops.resolve_port(args, env_path)

    if _compose.is_fleet(deploy_dir):
        return _cmd_status_fleet(deploy_dir, env_path, port, json_mode)
    return _cmd_status_single(deploy_dir, env_path, port, json_mode)

def cmd_stop(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    deploy_dir = _runtime_ops.deployment_dir(args)

    if not args.apply:
        if json_mode:
            emit_result({"dry_run": True, "deployment_dir": str(deploy_dir)}, json_mode=True)
        else:
            emit_result(
                f"DRY RUN — would run: docker compose down in {deploy_dir}.\n"
                "Re-run with --apply to execute.",
                json_mode=False,
            )
    else:
        emit_diagnostic(f">> stopping the vLLM server in {deploy_dir}")
