def _mtp_primary():
    """The MTP default primary (the model whose serve flags the template bakes in)."""
    return next(
        (m for m in supported_models() if m.role_hint == "primary" and m.speculative_config),
        None,
    )

def _moe_notice(model) -> str | None:
    """MoE checkpoint: ``--moe-backend`` must be added by hand (not written to .env)."""
    if not model.moe_backend:
        return None
    return (
        "MoE model — add this to the compose `command` by hand (not written "
        "to .env; see docs/qwen3.6-35b-a3b-nvfp4.md): "
        f"--moe-backend={model.moe_backend}"
    )

def _pooling_default_util(model_id: str) -> float:
    """The pooling budget for ``model_id`` — its own if catalogued, else the shared one."""
    catalogued = next((m for m in supported_models() if m.id == model_id), None)
    if catalogued is not None and catalogued.default_gpu_mem_util > 0:
        return catalogued.default_gpu_mem_util
    return POOLING_DEFAULT_UTIL

def _task_messages(
    plan: dict, args: argparse.Namespace, effective_task: str, is_pooling: bool
) -> list[str]:
    """Set ``VLLM_TASK`` / the tool-call parser; return the human messages."""
    if not is_pooling:
        parser, parser_msg = _select_parser(args)
        if parser:
            plan["VLLM_TOOL_CALL_PARSER"] = parser
        return [parser_msg]
    # Embed/score models don't use tool calling — skip the parser entirely.
    plan["VLLM_TASK"] = effective_task
    messages = [f"tool-call parser: skipped (task={effective_task})"]
    warning = _forced_task_warning(args, effective_task)
    if warning:
        messages.append(warning)
    return messages

def _quant_messages(
    plan: dict, args: argparse.Namespace, effective_task: str, is_pooling: bool
) -> list[str]:
    """Set ``VLLM_QUANTIZATION``; embed/score gears with an empty catalog
    quantization stay unquantized (no flag written)."""
    quant, quant_msg = _select_quantization(args)
    if is_pooling and quant == "":
        return [f"quantization: none (task={effective_task})"]
    if quant:
        plan["VLLM_QUANTIZATION"] = quant
    return [quant_msg]

def _context_messages(plan: dict, args: argparse.Namespace, is_pooling: bool) -> list[str]:
    """Pooling: note the embed/score context defaults. Chat: clamp ``--max-model-len``
    DOWN to the catalogued native ceiling — vLLM refuses a larger value (no YaRN) and
    the container fails to boot, so a high machine default (spark's 256K) can't
    boot-fail a 32K-native model. An uncatalogued model has no ceiling to clamp
    against, so it inherits the machine default with a warning."""
    if is_pooling:
        messages = []
        if args.max_model_len is None:
            messages.append("max-model-len (embed/score default): 8192")
        if args.gpu_mem_util is None:
            messages.append(
                f"gpu-mem-util (embed/score default): {_pooling_default_util(args.model)}"
            )
        return messages
    if args.max_model_len is not None:
        return []
    catalogued = next((m for m in supported_models() if m.id == args.model), None)
    if catalogued is None:
        return [
            f"max-model-len: machine default {plan['VLLM_MAX_MODEL_LEN']} applied "
            "unclamped (uncatalogued model — native ceiling unknown); if the "
            "checkpoint's native context is smaller, vLLM will refuse to boot — pass "
            "--max-model-len or add the model to the catalog with native_max_model_len"
        ]
    if int(plan["VLLM_MAX_MODEL_LEN"]) <= catalogued.native_max_model_len:
        return []
    plan["VLLM_MAX_MODEL_LEN"] = str(catalogued.native_max_model_len)
    return [f"max-model-len (clamped to model native ceiling): {catalogued.native_max_model_len}"]

def _cmd_stop(args: argparse.Namespace, deploy_dir, json_mode: bool) -> int:
    if not args.apply:
        pid = _tunnel.tunnel_pid(deploy_dir)
        target = f"cloudflared (pid {pid})" if pid else "cloudflared (no running tunnel found)"
        if json_mode:
            emit_result(
                {"dry_run": True, "action": "stop", "pid": pid, "deployment_dir": str(deploy_dir)},
                json_mode=True,
            )
        else:
            emit_result(
                f"DRY RUN — would stop {target} in {deploy_dir}.\n"
                "Re-run with --apply to execute.",
                json_mode=False,
            )
        return EXIT_SUCCESS
    emit_diagnostic(f">> stopping the cloudflared tunnel in {deploy_dir}")
    status, pid = _tunnel.stop_tunnel(deploy_dir)
    if json_mode:
        emit_result(
            {
                "stopped": status == "stopped",
                "status": status,
                "pid": pid,
                "deployment_dir": str(deploy_dir),
            },
            json_mode=True,
        )
    elif status == "stopped":
        emit_result(f">> stopped pid {pid}.", json_mode=False)
    elif status == "idle":
        emit_result(">> no running tunnel to stop.", json_mode=False)
    else:  # "failed" — signalled but still alive; pidfile kept for a retry
        emit_diagnostic(
            f">> pid {pid} did not exit after SIGTERM/SIGKILL; the pidfile is kept.\n"
            ">> inspect it (ps) and retry: lobes tunnel --stop --apply"
        )
    return EXIT_ENV_ERROR if status == "failed" else EXIT_SUCCESS

def cmd_tunnel(args: argparse.Namespace) -> int:
    json_mode = bool(getattr(args, "json", False))
    deploy_dir = _runtime_ops.deployment_dir(args)

    if getattr(args, "stop", False):
        return _cmd_stop(args, deploy_dir, json_mode)

    env_path = deploy_dir / _compose.ENV_FILE
    port = _runtime_ops.resolve_port(args, env_path)
    hostname = _tunnel.resolve_hostname(getattr(args, "hostname", None), deploy_dir)
    mode, value = _tunnel.resolve_token(deploy_dir)
    command = _tunnel.build_command(mode, value)
    safe_command = _tunnel.redacted(command)
    url = _public_url(hostname)

    if not args.apply:
        if json_mode:
            emit_result(
                {
                    "dry_run": True,
                    "hostname": hostname,
                    "url": url,
                    "port": port,
                    "token_source": mode,
                    "command": safe_command,
                    "deployment_dir": str(deploy_dir),
                },
                json_mode=True,
            )
        else:
            emit_result(
                f"DRY RUN — would run: {' '.join(safe_command)}\n"
                f"(in {deploy_dir}), exposing the local :{port} API at {url}.\n"
                "Re-run with --apply to execute.",
                json_mode=False,
            )
        return EXIT_SUCCESS

    # --apply: refuse to orphan an already-running tunnel, then preflight
    # (cloudflared / shushu on PATH, local server up) and start.
    running = _tunnel.tunnel_pid(deploy_dir)
    if running:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"a tunnel is already running (pid {running})",
            remediation="stop it first: lobes tunnel --stop --apply",
        )
    if not _tunnel.cloudflared_present():
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message="cloudflared not found on PATH",
            remediation=_tunnel.INSTALL_HINT,
        )
    if mode == "shushu" and not _tunnel.shushu_present():
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message="shushu not found on PATH",
            remediation=(
                "install shushu, or set CULTURE_CF_TUNNEL_TOKEN (plaintext) in "
                + str(_tunnel.tunnel_env_path(deploy_dir))
            ),
        )
    if not _health.is_healthy(port):
        raise Mo

def _hosting_shapes_for(role: str) -> tuple[str, ...]:
    """Every built-in shape that actually hosts ``role``, sorted by name.

    Looked up from the shapes themselves rather than assumed from a naming
    convention: the opt-in core roles do NOT all live behind a
    ``thor-<role>`` shape (``associate``'s is ``orin-associate``, and
    ``innereye``'s is ``spark-innereye``), so a hardcoded ``f"thor-{role}"``
    would point an operator at a shape that does not exist for those two.
    """
    return tuple(
        name
        for name in builtin_shape_names()
        if (shape := load_builtin_shape(name)) is not None and shape.hosts_role(role)
    )

def _activation_extra(target: str) -> str:
    """The extra .env key an opt-in role needs beyond its compose profile."""
    if target == "innereye":
        return f" and set {_INNEREYE_URL_KEY}={_INNEREYE_URL}"
    return ""

def _chain(deploy_dir: Path, audio: bool, shape_present: bool) -> list[str]:
    return _compose_file_args(
        audio,
        shape_present,
        _compose.local_override_present(deploy_dir),
        _compose.gpu_overlay_present(deploy_dir),
        _compose.audio_he_overlay_present(deploy_dir),
    )

def _replace_requested(args: argparse.Namespace, target: str, action: str) -> bool:
    """``--replace``, refusing the combinations that cannot mean anything."""
    if not getattr(args, "replace", False):
        return False
    if action == "stop":
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message="--replace has no meaning with --down",
            remediation="to switch back, start the other role: 'lobes up <role> --replace --apply'",
        )
    if target not in ROLE_SERVICE:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"--replace applies to a role, not '{target}'",
            remediation="name the role to switch to, e.g. 'lobes up innereye --replace'",
        )
    return True

def _running_service(role: str) -> str | None:
    for service in _role_swap.role_services(role):
        if _compose.container_status(_role_swap.container_for(service)) in _PRESENT_STATES:
            return service
    return None

def _guard_rivals(target: str, swap: _Swap, replace: bool) -> None:
    swap.excl = _role_swap.exclusivity(swap.card, target)
    if replace and not swap.excl.rivals:
        why = f" ({swap.card.warning})" if swap.card.warning else ""
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=(
                f"--replace: the '{swap.card.name or 'unset'}' card profile declares "
                f"no role exclusive with '{target}', so there is nothing to replace{why}"
            ),
            remediation=f"drop --replace: 'lobes up {target} --apply'",
        )
    swap.running = []
    for rival in swap.excl.rivals:
        service = _running_service(rival)
        if service:
            swap.running.append((rival, service))
    if swap.running and not replace:
        raise _rival_error(target, swap)

def _warn_infeasible(target: str, swap: _Swap, replace: bool) -> None:
    """A role an earlier switch marked ``*_FEASIBLE=false`` stays unrouted after a
    plain ``up``: the gateway keeps sending it to the mesh. Say so."""
    if replace:
        return
    key = _role_swap.feasible_key(target)
    if (swap.env.get(key) or "").split("#")[0].strip().lower() in ("false", "0", "no"):
        fix = (
            f"'lobes up {target} --replace --apply' sets it back"
            if swap.excl.rivals
            else f"set {key}=true in .env, then 'lobes up gateway --apply'"
        )
        emit_diagnostic(
            f">> warning: .env has {key}=false, so the gateway won't route {target} "
            f"to this box even once it runs; {fix}"
        )

def _rival_error(target: str, swap: _Swap) -> ModelGearError:
    names = swap.rival_names()
    return ModelGearError(
        code=EXIT_USER_ERROR,
        message=(
            f"'{target}' can't run beside {names} on this card "
            f"({swap.card.name}: {swap.excl.reason})"
        ),
        remediation=(
            f"'lobes up {target} --replace --apply' stops {names}, hands it to the mesh "
            f"and starts {target}; run it without --apply first to see the plan"
        ),
    )

def _memory_error(
    target: str, verdict: _role_swap.MemoryVerdict, extra: str = ""
) -> ModelGearError:
    return ModelGearError(
        code=EXIT_USER_ERROR,
        message=f"not enough memory to start '{target}': {verdict.describe()}{extra}",
        remediation=(
            "free memory first (stop a lane with 'lobes up <role> --down --apply'), "
            "or pass --override-memory to start it anyway"
        ),
    )

def _swap_plan(
    deploy_dir: Path, target: str, argv: list[str], swap: _Swap, changes: dict[str, str]
) -> dict:
    stops = [_service_argv("stop", swap.compose_files, r, s) for r, s in swap.running]
    if swap.memory is None:
        memory_line = "memory: not checked (--override-memory, already running, or no requirement)"
    elif swap.running:
        memory_line = f"{swap.memory.describe()} now; re-checked after the stop"
    else:
        memory_line = swap.memory.describe()
    steps = [" ".join(a) for a in stops]
    steps.append(memory_line)
    steps += [f".env: {k}={v}" for k, v in changes.items()]
    steps.append(" ".join(argv))
    if changes:
        gateway = _compose.compose_service_argv("up", swap.gateway_files, [GATEWAY_SERVICE])
        steps.append(" ".join(gateway))
    return {
        "target": target,
        "replace": [role for role, _ in swap.running],
        "env_changes": changes,
        "memory": memory_line,
        "steps": steps,
        "deployment_dir": str(deploy_dir),
    }

def _restart_rivals(deploy_dir: Path, swap: _Swap) -> list[str]:
    """Start the stopped rivals again; return the ones that failed to start."""
    failed = []
    for rival, service in swap.running:
        restart = _service_argv("up", swap.compose_files, rival, service)
        emit_diagnostic(f">> restarting {rival} ({service})")
        if _compose.run_compose(deploy_dir, restart).returncode != 0:
            failed.append(rival)
    return failed

def _rollback_note(deploy_dir: Path, swap: _Swap) -> str:
    if not swap.running:
        return ""
    failed = _restart_rivals(deploy_dir, swap)
    if failed:
        return (
            f"; restarting {', '.join(failed)} FAILED, so it is down: "
            f"'lobes up {failed[0]} --apply' to retry"
        )
    return f"; restarted {swap.rival_names()}"

def _gate_after_stop(deploy_dir: Path, target: str, swap: _Swap) -> None:
    """The memory check that counts: after the rivals stopped. A shortfall
    puts them back, so a refused swap changes nothing."""
    if not (swap.check_memory and swap.running):
        return
    verdict = _role_swap.wait_for_memory(swap.env, swap.card, target)
    emit_diagnostic(f">> {verdict.describe()}")
    if not verdict.ok:
        raise _memory_error(target, verdict, _rollback_note(deploy_dir, swap))

def _stop_target(deploy_dir: Path, target: str, services: list[str], swap: _Swap) -> None:
    """A failed start may still have created the container: stop it, with its
    profile, before the rival comes back."""
    for service in services:
        stop = _service_argv("stop", swap.compose_files, target, service)
        _compose.run_compose(deploy_dir, stop)

def _await_gateway(port: int) -> None:
    """Give a just-recreated gateway a moment to answer before the mesh
    reannounce, which would otherwise hit it mid-restart. Best-effort."""
    deadline = time.monotonic() + GATEWAY_WAIT_S
    while not _health.is_healthy(port) and time.monotonic() < deadline:
        time.sleep(1.0)

def _emit_innereye_hints(
    deploy_dir: Path, target: str, action: str, env: dict[str, str] | None = None
) -> None:
    if target == "innereye" and action == "up":
        for hint in _innereye_hints(deploy_dir, env):
            emit_diagnostic(f">> innereye {hint}")

def _agent_nick() -> str:
    """Return the deployed agent's ``suffix`` from ``culture.yaml`` (or the default)."""
    cfg = _find_culture_yaml()
    if cfg is None:
        return _FALLBACK_AGENT
    try:
        text = cfg.read_text(encoding="utf-8")
    except OSError:
        return _FALLBACK_AGENT
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith(("- suffix:", "suffix:")):
            _, _, value = stripped.partition("suffix:")
            return value.strip().strip("'\"") or _FALLBACK_AGENT
    return _FALLBACK_AGENT

def _gpu_name() -> str:
    """First line of ``nvidia-smi -L`` (best-effort; ``unknown`` if unavailable)."""
    r = _compose._probe(["nvidia-smi", "-L"])
    if r is None or r.returncode != 0 or not r.stdout.strip():
        return "unknown"
    return r.stdout.splitlines()[0].strip() or "unknown"

def _deployment_facts() -> dict[str, object]:
    """Served model/port and active gear (purpose/machine), from the deployment ``.env``.

    Configuration (which can be stale), not a live query — mirrors the rest of
    ``whoami``. Falls back to the scaffold defaults when nothing is deployed.
    """
    try:
        deploy_dir = _compose.resolve_deployment_dir(None)
    except Exception:  # noqa: BLE001 - no deployment scaffolded yet
        return {"served": _DEFAULT_MODEL, "port": 8000, "purpose": "balanced", "machine": "spark"}
    env_path = deploy_dir / _compose.ENV_FILE
    return {
        "served": _env.read_env(env_path, "VLLM_SERVED_NAME", _DEFAULT_MODEL),
        "port": _env.parse_port(_env.read_env(env_path, "VLLM_PORT", "8000")),
        "purpose": _env.read_env(env_path, "VLLM_PURPOSE", "balanced"),
        "machine": _env.read_env(env_path, "VLLM_MACHINE", "spark"),
    }

def _container_health(port: int) -> str:
    state = _compose.inspect_state()
    if state == "not created":
        return "not created"
    return "ok" if _health.is_healthy(port) else "down"

def to_dict(self) -> dict[str, object]:
    return {
        "code": self.code,
        "message": self.message,
        "remediation": self.remediation,
    }

def _fmt(m: dict, field: str, *, thousands: bool = False) -> str:
    """One live-view number, or ``unknown`` when this backend cannot report it."""
    if field not in m or field in _metrics.unsupported_fields(m):
        return _UNKNOWN
    value = int(m[field] or 0)
    return f"{value:,}" if thousands else str(value)

def _agg_usage(backends: list[dict]) -> tuple[int, int, int, dict[str, int], set[str]]:
    """Sum tokens + finished requests across backends (the fleet's cumulative usage).

    The fifth element names the usage fields at least one backend could not
    report — the totals are then honest-but-partial rather than silently short.
    """
    prompt = gen = succeeded = 0
    reasons: dict[str, int] = {}
    incomplete: set[str] = set()
    for b in backends:
        m = b.get("metrics") or {}
        unknown = _metrics.unsupported_fields(m)
        incomplete |= {f for f in _USAGE_FIELDS if f in unknown}
        prompt += int(m.get("prompt_tokens", 0) or 0)
        gen += int(m.get("generation_tokens", 0) or 0)
        succeeded += int(m.get("requests_succeeded", 0) or 0)
        for reason, count in (m.get("by_finish_reason") or {}).items():
            reasons[reason] = reasons.get(reason, 0) + int(count)
    return prompt, gen, succeeded, reasons, incomplete

def _backend_line(b: dict) -> str:
    m = b.get("metrics") or {}
    parts = [f"{b.get('name', '?')} ({b.get('task', '?')}): {b.get('health', '?')}"]
    if m:
        parts.append(f"run {_fmt(m, 'running')} wait {_fmt(m, 'waiting')}")
    if b.get("served_name"):
        parts.append(str(b["served_name"]))
    return " · ".join(parts)

def fleet_sections(status: dict) -> list[dict]:
    """Live sections from a gateway ``/status`` payload (the fleet case)."""
    backends = status.get("backends") or []
    busy = status.get("busy") or {}
    tasks = sorted({b.get("task") for b in backends if b.get("task")})
    models = [b.get("served_name") for b in backends if b.get("served_name")]
    prompt, gen, succeeded, reasons, incomplete = _agg_usage(backends)
    return [
        {
            "title": "Online (live)",
            "items": [_backend_line(b) for b in backends] or ["(no backends)"],
        },
        {
            "title": "Offered",
            "items": [
                f"default model: {status.get('default_model', '?')}",
                f"task families: {', '.join(tasks) or '?'}",
                f"models: {', '.join(models) or '?'}",
                "full catalog: lobes overview --list",
            ],
        },
        {
            "title": "Busy",
            "items": [
                f"running: {int(busy.get('running', 0))}    "
                f"waiting: {int(busy.get('waiting', 0))}"
                + (
                    "    (partial — a backend does not report in-flight counts)"
                    if busy.get("partial")
                    else ""
                )
            ],
        },
        {
            "title": "Usage",
            "items": _usage_items(f"{prompt:,}", f"{gen:,}", str(succeeded), reasons, incomplete),
        },
        {"title": "Endpoints", "items": list(status.get("endpoints") or []) or ["(none)"]},
    ]

def single_sections(
    port: int, served_name: str | None, *, healthy: bool, metrics: dict | None
) -> list[dict]:
    """Live sections for a bare single-model vLLM server (``/metrics`` + ``/health``)."""
    served = served_name or "(model unknown — no .env)"
    online = f"{served} on :{port} — " + ("ok" if healthy else "not responding")
    if metrics:
        busy = [f"running: {_fmt(metrics, 'running')}    waiting: {_fmt(metrics, 'waiting')}"]
        usage = _usage_items(
            _fmt(metrics, "prompt_tokens", thousands=True),
            _fmt(metrics, "generation_tokens", thousands=True),
            _fmt(metrics, "requests_succeeded"),
            metrics.get("by_finish_reason") or {},
        )
    else:
        busy = ["(metrics unavailable)"]
        usage = ["(metrics unavailable)"]
    return [
        {"title": "Online (live)", "items": [online]},
        {
            "title": "Offered",
            "items": [f"served model: {served}", "full catalog: lobes overview --list"],
        },
        {"title": "Busy", "items": busy},
        {"title": "Usage", "items": usage},
        {
            "title": "Endpoints",
            "items": [
                "GET /health",
                "GET /metrics",
                "GET /v1/models",
                "POST /v1/chat/completions",
                "POST /v1/completions",
            ],
        },
    ]

def live_sections(port: int, served_name: str | None) -> list[dict]:
    """Probe :``port`` and return the live sections (fleet gateway or single model).

    The gateway exposes ``/status`` (a lobes fan-out); a bare vLLM does not, so
    its absence + a healthy ``/health`` means single-model. Everything is
    best-effort: an unreachable endpoint yields a single "nothing serving" section
    rather than an error.
    """
    base = f"http://localhost:{port}"
    status = _metrics.http_get_json(base + "/status")
    if isinstance(status, dict) and status.get("object") == _FLEET_STATUS_OBJECT:
        return fleet_sections(status)
    if _metrics.health_ok(base):
        raw = _metrics.http_get_text(base + "/metrics")
        return single_sections(
            port, served_name, healthy=True, metrics=_metrics.parse_metrics(raw) if raw else None
        )
    return [
        {
            "title": "Live",
            "items": [
                f"no lobes endpoint reachable on :{port}",
                ">> start one: lobes serve --apply  (or lobes fleet up --apply)",
            ],
        }
    ]

def _role_backend(role: str) -> str:
    # Imported late: lobes.roles imports the gateway package, which imports
    # lobes.roles back, so a module-level import here can start that cycle
    # from the wrong end.
    from lobes.roles import ROLE_BACKEND

    return ROLE_BACKEND.get(role, role)

@dataclass
class Card:
    """The deployment's card profile, resolved once per ``lobes up``."""

    name: str = ""
    profile: Profile | None = None
    warning: str = ""

def load_card(env: dict[str, str], deploy_dir: Path) -> Card:
    """Resolve ``LOBES_PROFILE``. A name that won't resolve is reported, not
    swallowed: it turns the exclusive-role guard off, and the operator should
    know that."""
    name = (env.get(PROFILE_KEY) or "").strip()
    if not name:
        return Card()
    try:
        return Card(name=name, profile=resolve_profile(name, deploy_dir))
    except Exception as exc:  # any load/validation error has the same consequence
        return Card(
            name=name,
            warning=(
                f"card profile {name!r} did not load ({exc}); exclusive-role and "
                "memory checks are off for this command"
            ),
        )

@dataclass
class Exclusivity:
    """The card's exclusive-role facts for one target role."""

    rivals: list[str] = field(default_factory=list)
    reason: str = ""

def exclusivity(card: Card, target: str) -> Exclusivity:
    """The roles ``card`` declares exclusive with ``target``."""
    found = Exclusivity()
    if card.profile is None:
        return found
    for group in card.profile.exclusive_roles:
        if target in group.roles:
            found.rivals += [r for r in group.roles if r != target and r not in found.rivals]
            found.reason = found.reason or group.reason
    return found

def declared_peak(card: Card, target: str) -> float | None:
    if card.profile is None:
        return None
    peak = getattr(card.profile.roles.get(target), "declared_peak_gib", None)
    return float(peak) if peak else None

def service_profile(role: str, service: str) -> str | None:
    """The compose profile gating ``service``, if any. Compose can't see a
    profile-gated service, even to stop it, unless that profile is active."""
    if service == LLAMA_CPP_ROLE_SERVICE.get(role):
        return LLAMA_CPP_COMPOSE_PROFILE
    return OPT_IN_CORE_COMPOSE_PROFILE.get(role)

def env_changes(env: dict[str, str], target: str, rivals: list[str]) -> dict[str, str]:
    """The ``.env`` keys a swap to ``target`` writes, only those that change.

    Rivals are marked infeasible (an explicit ``false`` is what lets the mesh
    serve them) and leave ``COMPOSE_PROFILES``. The target is marked feasible,
    joins ``COMPOSE_PROFILES`` when it is profile-gated, and gets its base-URL
    wiring when that is unset.
    """
    want: dict[str, str] = {}
    profiles = _profiles(env)
    for rival in rivals:
        want[FEASIBLE_ENV[_role_backend(rival)]] = "false"
        rival_profile = OPT_IN_CORE_COMPOSE_PROFILE.get(rival)
        if rival_profile in profiles:
            profiles.remove(rival_profile)
    want[FEASIBLE_ENV[_role_backend(target)]] = "true"
    target_profile = OPT_IN_CORE_COMPOSE_PROFILE.get(target)
    if target_profile:
        if target_profile not in profiles:
            profiles.append(target_profile)
        for key, value in OPT_IN_CORE_ACTIVATION_ENV.get(target, {}).items():
            if not (env.get(key) or "").strip():
                want[key] = value
    want[PROFILES_KEY] = ",".join(profiles)
    return {k: v for k, v in want.items() if (env.get(k) or "").strip() != v}

def meminfo_gib(field_name: str, meminfo: Path | None = None) -> float | None:
    """One ``/proc/meminfo`` field in GiB, or None where it can't be read."""
    try:
        for line in (meminfo or MEMINFO).read_text(encoding="utf-8").splitlines():
            if line.startswith(field_name + ":"):
                return int(line.split()[1]) / _GIB_KB
    except (OSError, ValueError, IndexError):
        return None
    return None

def required_gib(
    env: dict[str, str], card: Card, target: str, *, meminfo: Path | None = None
) -> tuple[float | None, str]:
    """``(GiB the role needs, where that figure came from)``; None when unknown."""
    peak = declared_peak(card, target)
    if peak:
        return peak, f"declared_peak_gib in the {card.name} card profile"
    prefix = ROLE_ENV_PREFIX.get(target)
    if not prefix:
        return None, ""
    util_key = prefix + "_GPU_MEM_UTIL"
    raw = (env.get(util_key) or "").split("#")[0].strip()
    total = meminfo_gib("MemTotal", meminfo)
    try:
        util = float(raw)
    except ValueError:
        return None, ""
    if total is None or not 0 < util <= 1:
        return None, ""
    return util * total, f"{util_key}={raw} x MemTotal {total:.1f} GiB"

def describe(self) -> str:
    if self.required is None:
        return "memory: no requirement declared for this role; not checked"
    if self.available is None:
        return "memory: /proc/meminfo unreadable; not checked"
    word = "ok" if self.ok else "SHORT"
    return (
        f"memory {word}: needs {self.required:.1f} GiB ({self.source}), "
        f"MemAvailable {self.available:.1f} GiB"
    )

def memory_verdict(
    env: dict[str, str], card: Card, target: str, *, meminfo: Path | None = None
) -> MemoryVerdict:
    required, source = required_gib(env, card, target, meminfo=meminfo)
    available = meminfo_gib("MemAvailable", meminfo)
    ok = required is None or available is None or available >= required
    return MemoryVerdict(ok, required, available, source)

def resolve_port(args: argparse.Namespace, env_path) -> int:
    """Port from ``--port`` if given, else ``VLLM_PORT`` in ``.env``, else 8000."""
    explicit = getattr(args, "port", None)
    if explicit is not None:
        return _env.parse_port(explicit, "--port")
    return _env.parse_port(_env.read_env(env_path, "VLLM_PORT", "8000"), "VLLM_PORT")

def deployment_env_soft(args: argparse.Namespace) -> dict[str, str]:
    """Best-effort ``.env`` contents as a plain dict (``{}`` when unscaffolded).

    Shared by every read-only role-registry consumer (``capabilities``,
    ``endpoint``, ``measure``, issue #81): a missing deployment must never turn
    a read-only introspection verb into a hard error — it just means every
    gateway-fronted role other than the always-present ``cortex`` resolves to
    its catalog default with ``loaded=False`` (see :mod:`lobes.roles`).
    """
    try:
        deploy_dir = _compose.resolve_deployment_dir(getattr(args, "compose_dir", None))
    except ModelGearError:
        return {}
    return _env.read_env_file(deploy_dir / _compose.ENV_FILE)

def format_tool_probe(tc: dict) -> str:
    """One-line PASS/FAIL summary of a :func:`probe_tool_calling` result."""
    if tc.get("ok"):
        return f"tool calling: PASS — called {', '.join(tc.get('tool_calls') or [])}"
    reason = tc.get("error") or f"no finish call (tool_calls={tc.get('tool_calls')})"
    return f"tool calling: FAIL — {reason}"

def compose_check(completed: subprocess.CompletedProcess, label: str) -> None:
    """Raise ModelGearError when a ``docker compose`` call exits non-zero."""
    if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "").strip()
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"{label} failed (exit {completed.returncode})",
            remediation=detail[-500:] if detail else "check docker and 'lobes status'",
        )

def _evict_if_needed(self, now: float) -> None:
    """Keep the tracking table bounded. Caller holds the lock."""
    if len(self._sources) <= self._max_sources:
        return
    # Expired windows first — they carry no unreported count by
    # construction (their next rejection reopens a window anyway).
    for key in [k for k, s in self._sources.items() if now - s.window_started >= self._window]:
        del self._sources[key]
        if len(self._sources) <= self._max_sources:
            return
    # Still over: drop the least-recently-seen. Costs that source one extra
    # line if it returns, which is the right way to be wrong here.
    while len(self._sources) > self._max_sources:
        oldest = min(self._sources, key=lambda k: self._sources[k].last_seen)
        del self._sources[oldest]

def _format(
    method: str, path: str, source: str, reason: str, suppressed: int, elapsed: float
) -> str:
    """The operator-facing line. ``suppressed`` is appended only when non-zero,
    so the common case (one stray request) reads as one plain sentence."""
    line = f"auth: rejected {method} {path} from {source} ({reason})"
    if suppressed:
        line += f" [+{suppressed} more from this source in the previous {elapsed:.0f}s]"
    return line

def _parse_aliases(raw: str | None) -> dict[str, str]:
    """Parse ``alias=served,other=served`` into a dict; skip blank/malformed pairs."""
    out: dict[str, str] = {}
    for pair in (raw or "").split(","):
        pair = pair.strip()
        if "=" not in pair:
            continue
        alias, _, target = pair.partition("=")
        alias, target = alias.strip(), target.strip()
        if alias and target:
            out[alias] = target
    return out

def _as_float(env: Mapping[str, str], key: str, default: float) -> float:
    try:
        return float(env.get(key) or default)
    except (TypeError, ValueError):
        return float(default)

def _as_int(env: Mapping[str, str], key: str, default: int) -> int:
    try:
        return int(env.get(key) or default)
    except (TypeError, ValueError):
        return int(default)

def _warn_on_served_name_collisions(backends: list[Backend]) -> None:
    """Emit a stderr warning for any model id claimed by more than one backend.

    Covers served names *and* LoRA adapter names — see
    :func:`_claimed_model_ids` for why the two are the same kind of claim. A
    backend claiming the same id twice (an adapter named after its own base) is
    also reported, since that too resolves by first match.
    """
    by_name: dict[str, list[Backend]] = {}
    for backend in backends:
        for claimed in _claimed_model_ids(backend):
            by_name.setdefault(claimed, []).append(backend)
    for served, owners in sorted(by_name.items()):
        if len(owners) < 2:
            continue
        names = ", ".join(sorted(b.name for b in owners))
        tasks = {b.task for b in owners}
        detail = (
            " Both serve task=embed, so requests may be answered from the WRONG "
            "VECTOR SPACE — embeddings from different models are not comparable."
            if tasks == {"embed"}
            else ""
        )
        # A LoRA adapter name is an ownership claim too, so a collision can be
        # adapter-vs-served-name or even a single backend claiming an id twice.
        # Name the remedy for whichever kind this is: *_SERVED_NAME is useless
        # advice when the duplicate came from HAND_LORA_MODULES.
        remedy = (
            "Give each backend a distinct *_SERVED_NAME."
            if all(served == b.served_name for b in owners)
            else "Rename the colliding LoRA adapter in HAND_LORA_MODULES, or give "
            "the backend a distinct *_SERVED_NAME."
        )
        sys.stderr.write(
            f"[gateway] WARNING: model id {served!r} is claimed by {len(owners)} "
            f"backend claim(s) ({names}); routing resolves it to the first match, "
            f"so ownership is order-dependent.{detail} {remedy}\n"
        )

def _parse_seeds(raw: str) -> tuple[str, ...]:
    """Parse ``LOBES_MESH_SEEDS`` as a comma-separated list.

    Each item is stripped of leading/trailing whitespace and has its
    trailing slash removed (mirroring the origin-trimming convention
    used everywhere else in :mod:`lobes.gateway._config`). Empty items
    (stray commas, leading/trailing commas) are dropped — there is no
    such thing as a seed at the empty-string origin.
    """
    if not raw:
        return ()
    return tuple(item.strip().rstrip("/") for item in raw.split(",") if item.strip())

def _parse_positive_int(env: Mapping[str, str], key: str, *, label: str) -> int:
    """Parse ``env[key]`` as a positive integer.

    Raises :class:`MeshHeartbeatError` or :class:`MeshMissedMaxError`
    (chosen by ``label``) when the value is ``0``, negative, or
    non-numeric.
    """
    raw = (env.get(key) or "").strip()
    if not raw:
        return _DEFAULT_HEARTBEAT_S if "HEARTBEAT" in label else _DEFAULT_MISSED_MAX
    try:
        value = int(raw)
    except ValueError as exc:
        if "HEARTBEAT" in label:
            raise MeshHeartbeatError(
                f"{key}={raw!r} is not a valid positive integer — "
                "the heartbeat interval must be a whole number of seconds."
            ) from exc
        else:
            raise MeshMissedMaxError(
                f"{key}={raw!r} is not a valid positive integer — "
                "missed-max must be a whole number of ticks."
            ) from exc
    if value <= 0:
        if "HEARTBEAT" in label:
            raise MeshHeartbeatError(f"{key}={value} must be a positive integer (greater than 0).")
        else:
            raise MeshMissedMaxError(f"{key}={value} must be a positive integer (greater than 0).")
    return value

@dataclass(frozen=True)
class _LedgerEntry:
    approved_by: str
    expiry: float
    updated_at: float

def approve(
    self, name: str, approved_by: str, expiry: float, *, now: float | None = None
) -> None:
    now = now if now is not None else self._clock()
    with self._lock:
        self.entries[name] = _LedgerEntry(
            approved_by=approved_by,
            expiry=expiry,
            updated_at=now,
        )

def merge(self, peer: "Ledger") -> None:
    """Gossip-merge *peer*'s entries.  The entry with the greater
    ``updated_at`` wins (ties: keep local)."""
    with self._lock:
        for name, entry in peer.entries.items():
            existing = self.entries.get(name)
            if existing is None or entry.updated_at > existing.updated_at:
                self.entries[name] = entry

def save(self) -> None:
    """Persist to *path* via temp-file + rename (atomic)."""
    if self.path is None:
        return
    with self._lock:
        data = {
            n: {
                "approved_by": e.approved_by,
                "expiry": e.expiry,
                "updated_at": e.updated_at,
            }
            for n, e in self.entries.items()
        }
    dirn = os.path.dirname(self.path) or "."
    fd, tmp = tempfile.mkstemp(dir=dirn, suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f)
        os.replace(tmp, self.path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise

def load(self) -> None:
    """Restore entries from *path* (no-op if path is ``None``)."""
    if self.path is None:
        return
    if not os.path.isfile(self.path):
        return
    with open(self.path, "r", encoding="utf-8") as f:
        data = json.load(f)
    with self._lock:
        for name, info in data.items():
            self.entries[name] = _LedgerEntry(
                approved_by=info["approved_by"],
                expiry=info["expiry"],
                updated_at=info.get("updated_at", 0.0),
            )

def now(self) -> float:
    """Return the roster's current clock value.

    Used to convert duration-based expiry to the roster's clock domain.
    """
    return self._clock()

def tick(self, now: float | None = None) -> TickResult:
    """Check staleness; drop expired members.  Returns drop count."""
    now = now if now is not None else self._clock()
    with self._lock:
        local_missed_max = (
            self._missed_max_override if self._missed_max_override is not None else _MISSED_MAX
        )
        dropped: int = 0
        to_remove: list[str] = []

        for name, member in self._roster.items():
            member.missed += 1
            if member.missed >= local_missed_max:
                to_remove.append(name)

        dropped_origins: list[str] = []
        for name in list(self._hold_down):
            self._hold_down[name] -= 1
            if self._hold_down[name] <= 0:
                del self._hold_down[name]
        for name in to_remove:
            dropped_origins.append(self._roster[name].origin)
            del self._roster[name]
            dropped += 1
            self._hold_down[name] = local_missed_max

        # Clear each name's flapping count once its own hold-out window
        # has elapsed (item A: per-name, not the old single roster-wide
        # counter). No list() copy needed here (S7504): this loop only
        # rewrites an existing key's value, never adds/removes a key, so
        # the dict is safe to iterate directly — unlike the hold-down
        # loop above, which does delete keys mid-iteration.
        for name in self._flap_counts:
            if (
                self._flap_counts[name] > 0
                and now >= self._flap_times.get(name, 0.0) + _FLAPPING_HOLD_TICKS
            ):
                self._flap_counts[name] = 0

    return TickResult(dropped=dropped, dropped_origins=tuple(dropped_origins))

def members(self) -> list[str]:
    """List all member names."""
    with self._lock:
        return list(self._roster.keys())

def approve(
    self, name: str, approved_by: str, expiry: float, *, now: float | None = None
) -> None:
    self._approved_here.add(name)
    self._ledger.approve(name, approved_by, expiry, now=now)

def leave(self, name: str) -> None:
    with self._lock:
        if name in self._roster:
            del self._roster[name]

def _read_request_body(handler: object) -> bytes:
    """Read the raw request body via Content-Length, defensively."""
    rfile = getattr(handler, "rfile", None)
    hdrs = getattr(handler, "headers", {})
    cl = hdrs.get("Content-Length")
    if cl is None:
        return b""
    try:
        length = int(cl)
        if rfile is not None and length > 0:
            return rfile.read(length)
    except (ValueError, AttributeError):
        pass
    return b""

def _parse_json_object(body: bytes) -> dict:
    """Best-effort JSON parse; a malformed body silently yields ``{}``.

    Mirrors the original inline ``try: json.loads(...) except (ValueError,
    TypeError): pass`` pattern exactly — a well-formed-but-non-dict payload
    (e.g. a JSON list) still passes through unchanged, matching prior
    behaviour of every caller.
    """
    try:
        return json.loads(body)
    except (ValueError, TypeError):
        return {}

def _source_from_handler(handler: object) -> str:
    """Derive the request source from the socket peer (finding 11).

    Never trusts a client-supplied field.
    """
    address = getattr(handler, "client_address", None)
    if isinstance(address, tuple) and address:
        return str(address[0])
    return "<unknown>"

def _flat_error_response(
    status: int, message: str, *, close: bool = False
) -> tuple[int, list[tuple[str, str]], bytes]:
    """Build a ``{"error": "<message>"}`` response (the flat error shape)."""
    headers: list[tuple[str, str]] = [("Content-Type", _JSON)]
    if close:
        headers.append(("Connection", "close"))
    return status, headers, json.dumps({"error": message}).encode()

def _invalid_key_response() -> tuple[int, list[tuple[str, str]], bytes]:
    """The 401 shared by every Bearer-guarded mesh route (finding 12)."""
    return _error_response(
        401,
        _INVALID_KEY_MSG,
        "invalid_api_key",
        www_authenticate=True,
        code="invalid_api_key",
    )

def _check_key(self, headers: dict[str, str]) -> bool:
    """Return True when *headers* carries a valid Bearer join key."""
    # Finding 18: handle None key cleanly.
    if self.config.key is None:
        return False
    auth = headers.get("Authorization", "")
    if not auth:
        return False
    scheme, _, token = auth.partition(" ")
    if scheme.lower() != "bearer":
        return False
    import hmac

    return hmac.compare_digest(token.strip().encode("utf-8"), self.config.key.encode("utf-8"))

def detect(self, handler: object) -> tuple[int, list[tuple[str, str]], bytes]:
    """GET /mesh/detect  – keyless presence check.

    Returns only name, schema version and ``mesh: true`` — never a
    member list (security h7).
    """
    body = {
        "mesh": True,
        "name": self.config.name,
        "schema_version": SCHEMA_MAJOR,
    }
    return 200, [("Content-Type", _JSON)], json.dumps(body).encode()

def _register_pending_join(
    self, name: str, origin: str, capacity: object, now: float, ttl: float
) -> tuple[int, list[tuple[str, str]], bytes] | None:
    """Enforce the pending-join queue cap + per-origin dedup, then enqueue.

    Returns an error response tuple, or ``None`` on success. Runs
    entirely under ``self._lock``, matching the original inline block.
    """
    with self._lock:
        pending = [p for p in self._pending if p.joined_at + ttl > now]
        self._pending = pending

        # Capacity cap: 8 pending entries total.
        if len(pending) >= 8:
            return _flat_error_response(400, "pending join queue is full (8)")

        # Finding 11: one entry per ORIGIN (not per name).
        for p in pending:
            if p.origin == origin:
                return _flat_error_response(400, "same origin already pending")
            # Drop entries with different name but same origin won't happen
            # now that we key on origin above.

        pending.append(_PendingJoin(name=name, origin=origin, capacity=capacity, joined_at=now))
    return None

def _decode_announcement_or_response(
    self, body: bytes
) -> tuple[Announcement | None, tuple[int, list[tuple[str, str]], bytes] | None]:
    """Decode the wire *body*; returns ``(public_announcement, None)`` or
    ``(None, error_response)`` (finding 15: MeshSchemaIncompatible caught
    distinctly from every other malformed-body failure).
    """
    from lobes.gateway._mesh_wire import decode

    try:
        return decode(body).public(), None
    except MeshSchemaIncompatible:
        # Wrong schema major – reject before touching roster.
        return None, _error_response(
            400,
            "Schema version mismatch",
            "schema_incompatible",
            expected_major=SCHEMA_MAJOR,
        )
    except (ValueError, TypeError, KeyError, AttributeError):
        # S5713: json.JSONDecodeError is a ValueError subclass, already
        # covered — listing it too was a redundant Exception class.
        # Finding 15 (review #252): KeyError/AttributeError added as a
        # boundary safeguard — decode() now validates structure and
        # raises ValueError consistently, but a malformed body must
        # never escape this route as an unhandled 500 either way.
        return None, _flat_error_response(400, "invalid JSON body", close=True)

def _admit_announcement(
    self, name: str, origin: str, roster_now: float
) -> tuple[int, list[tuple[str, str]], bytes] | None:
    """Admit *name*/*origin* into the roster.

    Returns an error response, or ``None`` on success.

    Finding 5: ledger only RESTRICTS — an absent entry is "no
    restriction", key-holders are admitted permanently.  Only when an
    entry exists AND is not in force (expired/revoked) do we refuse.
    Finding 4 (review #252): the ledger check and the roster admission
    used to be two separate, unsynchronized steps here — a concurrent
    /mesh/revoke could commit in the gap and this request would still
    admit the just-revoked name. announce_gated() does both under one
    lock shared with approve/revoke, so a revoke can never interleave.
    """
    from lobes.gateway._mesh_roster import MeshApprovalExpired, MeshFlapping

    try:
        if name == self.config.name:
            # A peer relaying OUR name (or a misconfigured twin) never
            # enters our own roster — the live Spark listed itself.
            return _error_response(
                409,
                "a member cannot announce this box's own name",
                "mesh_name_conflict",
                name=name,
            )
        self.roster.announce_gated(name, origin, None, now=roster_now)
    except MeshApprovalExpired:
        return _error_response(403, "Approval has expired", "approval_expired", name=name)
    except MeshFlapping as exc:
        return _error_response(429, str(exc), "mesh_flapping", name=name)
    except Exception as exc:
        if "conflict" in str(exc).lower() or "already held" in str(exc).lower():
            self._drop_stale_announcements_for(name)
            return _error_response(409, "Name conflict", "name_conflict", name=name)
        raise
    return None

def announce(self, handler: object) -> tuple[int, list[tuple[str, str]], bytes]:
    """POST /mesh/announce – authenticated membership heartbeat."""
    if not self._check_key(getattr(handler, "headers", {})):
        return _invalid_key_response()

    body = _read_request_body(handler)

    public, error = self._decode_announcement_or_response(body)
    if error is not None:
        return error
    name = public.name

    if not name:
        return _name_required_response()

    error = self._ingest_public_announcement(public)
    if error is not None:
        return error

    reply: dict = {"status": "announced", "name": name, "schema_version": SCHEMA_MAJOR}
    # d1: answer with OUR OWN public announcement. A box that has just been
    # recreated holds no peer announcements at all — the seed rosters it
    # fetches list members and roles but carry no announcement — so its
    # first pass had nothing to verify and its mesh-provided roles 404'd
    # until every peer's next heartbeat (57 s measured live, 2026-09-12).
    # Carrying the responder's announcement in the reply lets the
    # announcer learn and verify us on the very pass that reached us.
    # Additive: a pre-d1 announcer ignores the field.
    own = self._own_announcement_object()
    if own is not None:
        reply["announcement"] = own
    return (200, [("Content-Type", _JSON)], json.dumps(reply).encode())

def _own_announcement_object(self) -> dict | None:
    """This box's stored public announcement as a JSON object, or ``None``."""
    raw = self._announcement_bytes
    if raw is None:
        return None
    try:
        obj = json.loads(raw)
    except (ValueError, TypeError):
        return None
    return obj if isinstance(obj, dict) else None

def ingest_reply_announcement(self, body: bytes | None) -> bool:
    """Learn a peer from the ``announcement`` its announce reply carried (d1).

    Returns ``True`` when a well-formed announcement was admitted and
    stored. Anything else — no body, no field, bad JSON, an incompatible
    schema, our own name, a lapsed approval — is ``False`` and leaves the
    roster untouched: the reply is a courtesy, never a requirement.
    """
    if not body:
        return False
    try:
        obj = json.loads(body)
    except (ValueError, TypeError):
        return False
    if not isinstance(obj, dict) or not isinstance(obj.get("announcement"), dict):
        return False
    try:
        ann = decode(json.dumps(obj["announcement"]).encode()).public()
    except Exception:  # nosec B110 — a malformed courtesy field is ignored
        return False
    if not ann.name or not ann.origin:
        return False
    with self._lock:
        return self._ingest_public_announcement(ann) is None

@staticmethod
def _announcement_fingerprints(ann: "Announcement | None") -> dict:
    """What a probe of *ann* is valid against (:func:`_probe_identity`)."""
    if ann is None:
        return {}
    return _probe_identity(ann)

def _needs_immediate_verify(
    self, origin: str, previous: "Announcement | None", current: "Announcement"
) -> bool:
    """Should this announcement wake the loop for an immediate pass?"""
    if not self._member_probed(origin):
        return True
    return self._announcement_fingerprints(previous) != self._announcement_fingerprints(current)

def roster_list(self, handler: object) -> tuple[int, list[tuple[str, str]], bytes]:
    """GET /mesh/roster – authenticated member listing."""
    if not self._check_key(getattr(handler, "headers", {})):
        return _invalid_key_response()

    # Finding 13: take a snapshot under the route lock.
    with self._lock:
        now = self.roster.now()
        snapshot = None
        if self._holder is not None:
            view = self._holder.current()
            if view is not None:
                snapshot = view.snapshot
        member_records = {}
        for mname in self.roster.members():
            record = self._build_member_record(mname, now, snapshot)
            if record is not None:
                member_records[mname] = record

    # Finding 9 (review #252): include the ledger's own entries in the
    # authenticated roster exchange. Without this, a revocation made on
    # one node was purely local — /mesh/roster only ever serialized
    # membership records, so a peer that already accepted and verified
    # the member never learned it was revoked, and kept forwarding to it
    # forever. `_fetch_seed_roster` merges these into its own Ledger via
    # `Ledger.merge()` (updated_at wins), matching the announce/approve/
    # revoke gossip contract.
    with self.roster.ledger._lock:  # noqa: SLF001 — snapshot for serialization
        ledger_entries = {
            n: {
                "approved_by": e.approved_by,
                "expiry": e.expiry,
                "updated_at": e.updated_at,
            }
            for n, e in self.roster.ledger.entries.items()
        }

    # Finding 3: return per-member objects with name AND origin.
    return (
        200,
        [("Content-Type", _JSON)],
        json.dumps(
            {"members": list(member_records.values()), "ledger": ledger_entries}
        ).encode(),
    )

def revoke(self, handler: object) -> tuple[int, list[tuple[str, str]], bytes]:
    """POST /mesh/revoke – authenticated revocation."""
    if not self._check_key(getattr(handler, "headers", {})):
        return _invalid_key_response()

    data = _parse_json_object(_read_request_body(handler))

    name: object = data.get("name")
    approved_by: str = data.get("approved_by", "requester")

    if not isinstance(name, str) or not name:
        return _name_required_response()

    roster_now = self.roster.now()
    # Finding 3 (review #252): revoke + persist as one transaction under
    # the ledger's own lock — see the matching approve_and_save note above.
    self.roster.revoke_and_save(str(name), now=roster_now, approved_by=approved_by)
    # Remove the revoked member's announcement and rebuild the snapshot
    # so revoked members get zero forwards immediately.
    with self._lock:
        self._announcements.pop(name, None)
        snap = build_snapshot(
            self.roster,
            announcements=self._announcements,
            discovered_roles=self._discovered_roles,
        )
        if self._holder is not None:
            from lobes.gateway._mesh_routing import MeshRoutingView

            self._holder.replace(MeshRoutingView(snapshot=snap, peer_states={}))
    return (
        200,
        [("Content-Type", _JSON)],
        json.dumps({"status": "revoked", "name": name}).encode(),
    )

def is_mesh_route(path: str) -> bool:
    """True when *path* is a known mesh endpoint path."""
    route_path = path.split("?", 1)[0]
    return route_path.startswith("/mesh/")

def _fingerprint_to_wire(
    fp: object,
) -> Fingerprint:
    """Convert a Fingerprint-like mapping to a wire Fingerprint."""
    if fp is None:
        return Fingerprint(
            served_id="",
            quantization="",
            max_model_len=0,
            runtime="",
        )
    if isinstance(fp, Fingerprint):
        return fp
    return Fingerprint(
        served_id=str(fp.get("served_id", "")),
        quantization=str(fp.get("quantization", "")),
        max_model_len=int(fp.get("max_model_len", 0)),
        runtime=str(fp.get("runtime", "")),
    )

def announcement_from_capabilities(
    config: MeshConfig,
    payload: Mapping[str, Mapping[str, object]],
    *,
    self_origin: str,
    local_capacities: Mapping[str, float] | None = None,
) -> Announcement:
    """Build this box's announcement from its OWN ``/capabilities`` payload.

    A member announces exactly what it advertises — the roles it hosts here
    (``feasible`` and carrying a ``fingerprint``, never a proxied one), with
    the very fingerprint a peer will read back when it verifies. Building the
    announcement from any other source is how the first live cutover ended up
    announcing all six roles with empty served ids (2026-09-12).
    """
    roles: dict[str, RoleInfo] = {}
    for role, entry in payload.items():
        if not isinstance(entry, Mapping):
            continue
        info = _role_info_from_capability_entry(role, entry, local_capacities)
        if info is not None:
            roles[str(role)] = info
    return Announcement(
        name=config.name or "", origin=self_origin, schema_version=str(SCHEMA_MAJOR), roles=roles
    )

def _resolve_ready_roles(readiness_cache: object | None) -> dict[str, bool | None]:
    """Return the readiness cache's flat ``backend -> ready`` map, or ``{}``.

    Finding 1/6: ``ReadinessCache.current()`` returns a flat
    ``dict[str, bool | None]`` keyed by BACKEND name ("primary",
    "multimodal", …), never nested and never keyed by role name.
    """
    if readiness_cache is None:
        return {}
    try:
        return readiness_cache.current()  # type: ignore[return-value]
    except (AttributeError, TypeError):
        return {}

def _live_fingerprint_from_cache(
    replica_caches: dict[str, object] | None, backend_name: str
) -> object | None:
    """Look up the LOCAL replica's live fingerprint for *backend_name*.

    ``replica_caches`` (`build_replica_caches`) is keyed by BACKEND name,
    never role name — look it up the same way the pool itself does.
    """
    if not replica_caches or backend_name not in replica_caches:
        return None
    cache = replica_caches[backend_name]
    try:
        # cache.current() returns tuple[ReplicaState]; find local=True.
        states = cache.current()
        if isinstance(states, (list, tuple)):
            for st in states:
                if getattr(st, "local", False):
                    return getattr(st, "fingerprint", None)
    except (AttributeError, TypeError):
        pass
    return None

def _seed_connection(
    seed: str, timeout: float
) -> tuple[http.client.HTTPConnection, str, dict[str, str]]:
    """Build the connection, path and headers for one seed's GET /mesh/roster."""
    parsed = urllib.parse.urlsplit(seed)
    host = parsed.hostname or "localhost"
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    path = parsed.path or "/mesh/roster"
    if parsed.query:
        path = path + "?" + parsed.query

    if parsed.scheme == "https":
        conn = http.client.HTTPSConnection(  # type: ignore[call-overload]
            host, port, timeout=timeout
        )
    else:
        conn = http.client.HTTPConnection(host, port, timeout=timeout)

    return conn, path, {"Content-Type": _JSON}

def _merge_seed_members(roster: "Roster", routes: "MeshRoutes | None", members: object) -> None:
    """Discovery-merge a seed's ``members`` list into *roster* (finding 3)."""
    if not isinstance(members, list):
        return
    for member in members:
        _merge_one_seed_member(roster, routes, member)

def _process_seed_roster_response(
    roster: "Roster", routes: "MeshRoutes | None", raw: bytes
) -> None:
    """Parse and merge one seed's /mesh/roster 200 response body."""
    try:
        data = json.loads(raw)
        _merge_seed_members(roster, routes, data.get("members", []))
        _merge_seed_ledger(roster, routes, data.get("ledger", {}))
    except (json.JSONDecodeError, TypeError, KeyError):
        pass

def _probe_result_still_current(
    origin: str,
    prev_anns: Mapping[str, "Announcement"],
    current_anns: Mapping[str, "Announcement"],
) -> bool:
    """Does a probe result taken against ``prev_anns[origin]`` still describe
    ``current_anns[origin]``?  False when the probe identity changed (the
    refresh-path twin of :func:`_drop_results_for_changed_announcements`)."""
    before = prev_anns.get(origin)
    now = current_anns.get(origin)
    if before is not None and now is not None:
        return _probe_identity(before) == _probe_identity(now)
    return before is now

def _carry_forward_probe_results(
    prev: "RoutingSnapshot | None",
    current_anns: Mapping[str, "Announcement"],
) -> tuple[
    dict[str, frozenset[str]],
    dict[str, str],
    dict[str, frozenset[str]],
    dict[str, dict[str, int]],
    dict[str, dict[str, str]],
]:
    """The per-origin probe maps to hand ``build_snapshot`` on a refresh.

    Every PROBED member of *prev* whose announcement is unchanged carries its
    verified / reason / ready / context data forward; ``ready`` is recorded
    even when empty because it is the "probed" trace (t1).  A member whose
    announcement's probe identity changed since its probe is left out on
    purpose — it returns to pending until the verify-now pass the change
    already scheduled re-probes it.
    """
    verified: dict[str, frozenset[str]] = {}
    reasons: dict[str, str] = {}
    ready: dict[str, frozenset[str]] = {}
    contexts: dict[str, dict[str, int]] = {}
    models: dict[str, dict[str, str]] = {}
    if prev is None:
        return verified, reasons, ready, contexts, models
    prev_anns = dict(prev.announcements)
    for m in prev.members:
        if not m.probed or not _probe_result_still_current(m.origin, prev_anns, current_anns):
            continue
        ready[m.origin] = frozenset(m.ready_roles)
        if m.verified_roles:
            verified[m.origin] = frozenset(m.verified_roles)
        if m.unverified_reason is not None:
            reasons[m.origin] = m.unverified_reason
        if m.role_context:
            contexts[m.origin] = dict(m.role_context)
        if m.role_model:
            models[m.origin] = dict(m.role_model)
    return verified, reasons, ready, contexts, models

def context_for(self, role: str) -> int | None:
    """The context this member's probe advertised for *role*, or ``None``."""
    for name, context in self.role_context:
        if name == role:
            return context
    return None

def model_for(self, role: str) -> str | None:
    """The model id this member's probe advertised for *role*, or ``None``."""
    for name, model in self.role_model:
        if name == role:
            return model
    return None

def has_member(self, origin: str) -> bool:
    """True when *origin* is known."""
    for m in self.members:
        if m.origin == origin:
            return True
    return False

def announced_roles(self, origin: str) -> tuple[str, ...]:
    """Roles the member *origin* announced (may include non-verified)."""
    for m in self.members:
        if m.origin == origin:
            return m.announced_roles
    return ()

def is_verified(self, origin: str, role: str) -> bool:
    """True when *origin* is verified for *role*."""
    for m in self.members:
        if m.origin == origin and role in m.verified_roles:
            return True
    return False

def as_routing_snapshot(obj: "object | None") -> "RoutingSnapshot | None":
    """Unwrap a :class:`MeshRoutingView` to its :class:`RoutingSnapshot`.

    The snapshot holder publishes a view (snapshot + per-peer replica states);
    every routing/advert consumer wants the snapshot. Accepting both here is
    what keeps a holder-returned view from reaching ``compute_role_placement``
    — the live 2026-09-12 ``/capabilities`` crash on the Thor (Qodo #12).
    """
    if obj is None:
        return None
    if isinstance(obj, MeshRoutingView):
        return obj.snapshot
    return obj  # already a RoutingSnapshot (or a test double)

def fingerprints_identical(a: object, b: object) -> bool:
    """Field-by-field identity of two replica fingerprints (verification rule).

    ``None`` / ``""`` / ``"unknown"`` / ``0`` all normalise to unknown, so an
    unknown on both sides is a match; any other difference is not.
    """
    if a is None or b is None:
        return False

    def norm(v: object) -> str:
        if v is None or v == "" or v == 0 or str(v).lower() == "unknown":
            return "unknown"
        return str(v)

    return all(
        norm(getattr(a, f, None)) == norm(getattr(b, f, None))
        for f in ("served_id", "quantization", "max_model_len", "runtime")
    )

def _resolve_member_roles(
    ann: "Announcement | None",
    verified_set: "frozenset[str] | None",
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """(announced, verified) role tuples for one member (Sonar S3776).

    Extracted from :func:`build_snapshot`'s per-member loop — identical
    return semantics: verification is PER ROLE (the subset of *announced*
    roles the probe verified), a member with no announcement but existing
    probe data is treated as fully verified from that probe, and a member
    with neither is unverified (empty tuple).
    """
    announced = tuple(ann.roles.keys()) if ann is not None else ()
    if verified_set is not None and announced:
        return announced, tuple(r for r in announced if r in verified_set)
    if verified_set is not None and not announced:
        # No announcement but probe data exists → fully verified from probe.
        return announced, tuple(sorted(verified_set))
    # No probe data → unverified.
    return announced, ()

def origins_for_role(
    snapshot: RoutingSnapshot | None,
    role: str,
) -> tuple[str, ...]:
    """Origins that verified support *role*, from *snapshot*.

    Returns an empty tuple when *snapshot* is ``None`` or no member verified
    for the role.  This is the single-point lookup that replaces
    ``table.replica_origins`` and ``table.peer_origins`` in mesh-driven routing.
    """
    if snapshot is None:
        return ()
    return snapshot.member_origins(role)

def member_exists(
    snapshot: RoutingSnapshot | None,
    origin: str,
) -> bool:
    """True when *origin* is in the snapshot."""
    if snapshot is None:
        return False
    return snapshot.has_member(origin)

def roster_member_count(
    snapshot: RoutingSnapshot | None,
) -> int:
    """Number of members in the snapshot."""
    if snapshot is None:
        return 0
    return snapshot.member_count()

def snapshot_member_roles(
    snapshot: RoutingSnapshot | None,
    origin: str,
) -> tuple[str, ...]:
    """Announced roles for *origin*, or empty tuple."""
    if snapshot is None:
        return ()
    return snapshot.announced_roles(origin)

def origin_for_suffixed(self, name: str) -> str | None:
    for lane in self.suffixed:
        if lane.name == name:
            return lane.origin
    return None

def _role_fingerprint(
    ann: "Announcement",
    role: str,
) -> "ReplicaFingerprint | None":
    """The replica-shaped Fingerprint a member announced for *role*, if any."""
    info = ann.roles.get(role)
    if info is None:
        return None
    return _wire_fingerprint_to_replica(info.fingerprint)

def find_suffixed_lane(
    snapshot: RoutingSnapshot | None,
    requested: str,
    roles: "tuple[str, ...] | list[str]",
    *,
    local_fingerprints: "Mapping[str, ReplicaFingerprint | None] | None" = None,
) -> SuffixedLane | None:
    """Resolve a raw requested name (e.g. ``"cortex-thor"``) to a suffixed lane.

    Tries every role the requested name could plausibly be suffixing (a
    ``"{role}-"`` prefix match), computing that role's placement and checking
    whether *requested* is one of its suffixed names. Returns ``None`` when
    *snapshot* is ``None`` or no role's placement contains *requested*.
    """
    if snapshot is None:
        return None
    local_fingerprints = local_fingerprints or {}
    for role in roles:
        prefix = role + "-"
        if not requested.startswith(prefix):
            continue
        placement = compute_role_placement(
            snapshot, role, local_fingerprint=local_fingerprints.get(role)
        )
        for lane in placement.suffixed:
            if lane.name == requested:
                return lane
    return None

def _peer_member_lanes(snapshot: RoutingSnapshot, role: str, skip_member: str) -> list[MemberLane]:
    """Verified and pending peer lanes of *role*, sorted by member name."""
    lanes = []
    for m in snapshot.members:
        if m.name == skip_member:
            continue
        if role in m.verified_roles:
            pending = False
        elif not m.probed and role in m.announced_roles:
            pending = True
        else:
            continue
        lanes.append(
            MemberLane(
                name=suffixed_lane_name(role, m.name),
                role=role,
                member=m.name,
                origin=m.origin,
                pending=pending,
            )
        )
    lanes.sort(key=lambda lane: lane.member)
    return lanes

def find_member_lane(
    snapshot: RoutingSnapshot | None,
    requested: str,
    roles: "tuple[str, ...] | list[str]",
    *,
    self_name: str = "",
    hosted_roles: "Collection[str]" = (),
) -> MemberLane | None:
    """Resolve ``"{role}-{member}"`` to a :class:`MemberLane`, else ``None``."""
    for role in roles:
        if not requested.startswith(role + "-"):
            continue
        for lane in member_lanes(
            snapshot, role, self_name=self_name, self_hosts=role in hosted_roles
        ):
            if lane.name == requested:
                return lane
    return None

def exposed_role_names(
    snapshot: RoutingSnapshot | None,
    origin: str,
) -> tuple[str, ...]:
    """Role names *origin* currently exposes — plain or suffixed (t8 follow-up).

    For every role *origin* is verified for, this names it as the PLAIN role
    (e.g. ``"cortex"``) when it agrees with that role's placement reference,
    or as its own suffixed lane (e.g. ``"cortex-thor"``) when it disagrees.
    A role announced ``private`` never appears here in the first place: it
    was already stripped from the stored :class:`~lobes.gateway._mesh_wire.Announcement`
    at the wire boundary (``Announcement.public()``, applied on receipt), so
    it is never in ``verified_roles`` to begin with — this function excludes
    nothing extra.

    No ``local_fingerprint`` is passed to :func:`compute_role_placement` here
    deliberately: this is a roster-wide listing (``GET /mesh/roster``), not a
    per-request dispatch with one box's own hosting fingerprint in hand — the
    peers-agree-with-each-other reference is the only one this view has.
    """
    if snapshot is None:
        return ()
    member = next((m for m in snapshot.members if m.origin == origin), None)
    if member is None:
        return ()
    names: list[str] = []
    for role in member.verified_roles:
        placement = compute_role_placement(snapshot, role)
        if origin in placement.plain_origins:
            names.append(role)
        else:
            lane = placement_origin_lane(placement, origin)
            if lane is not None:
                names.append(lane.name)
    return tuple(names)

def placement_origin_lane(placement: RolePlacement, origin: str) -> SuffixedLane | None:
    """The :class:`SuffixedLane` in *placement* served by *origin*, if any."""
    for lane in placement.suffixed:
        if lane.origin == origin:
            return lane
    return None

def encode(a: Announcement) -> bytes:
    """Serialise *a* to JSON bytes."""
    obj: dict[str, Any] = {
        "name": a.name,
        "origin": a.origin,
        "schema_version": a.schema_version,
        "roles": {name: dataclasses.asdict(info) for name, info in a.roles.items()},
    }
    return json.dumps(obj).encode("utf-8")

def _check_schema_major(obj: dict[str, Any]) -> None:
    """Raise :exc:`MeshSchemaIncompatible` unless *obj* declares our major."""
    try:
        major = int(obj["schema_version"].split(".")[0])
    except (KeyError, ValueError, AttributeError) as exc:
        raise MeshSchemaIncompatible(
            f"expected major {SCHEMA_MAJOR}, cannot parse schema version"
        ) from exc
    if major != SCHEMA_MAJOR:
        raise MeshSchemaIncompatible(
            f"schema version {SCHEMA_MAJOR} expected, got {obj.get('schema_version', '<?>')}"
        )

def _decode_role_info(role_name: str, role_obj: Any) -> RoleInfo:
    """Decode one ``roles`` entry into a :class:`RoleInfo`.

    Every failure — a missing field, a non-dict ``fingerprint``, a bad type —
    is normalized to :exc:`ValueError` naming the offending role.
    """
    if not isinstance(role_obj, dict):
        raise ValueError(f"malformed role {role_name!r}: not a JSON object")
    try:
        fp_obj = role_obj["fingerprint"]
        if not isinstance(fp_obj, dict):
            raise ValueError(f"malformed role {role_name!r}: 'fingerprint' not a JSON object")
        capacity = role_obj.get("capacity")
        return RoleInfo(
            model=role_obj["model"],
            runtime=role_obj["runtime"],
            context=role_obj["context"],
            quant=role_obj["quant"],
            responsibilities=tuple(role_obj["responsibilities"]),
            forbidden_responsibilities=tuple(role_obj["forbidden_responsibilities"]),
            fingerprint=Fingerprint(
                served_id=fp_obj["served_id"],
                quantization=fp_obj["quantization"],
                max_model_len=fp_obj["max_model_len"],
                runtime=fp_obj["runtime"],
            ),
            capacity=float(capacity) if capacity is not None else None,
            private=bool(role_obj.get("private", False)),
        )
    except (KeyError, ValueError, TypeError) as exc:
        raise ValueError(f"malformed role {role_name!r}: {exc}") from exc

def _env_float(key: str, default: float) -> float:
    """Read a float from *key* in ``os.environ``; fall back to *default*.

    Non-finite values (``nan``, ``inf``, ``-inf``) are treated as parse
    failures and return *default* — a non-finite threshold silently breaks
    every ``>`` comparison (``nan > x`` is always ``False``).
    """
    try:
        raw = os.environ.get(key)
        value = float(raw) if raw is not None else float(default)
        return value if math.isfinite(value) else float(default)
    except (TypeError, ValueError):
        return float(default)

def _positive_int(value: object) -> int | None:
    """``value`` as a positive int, else ``None`` (a 0/negative/garbage context
    is not a fact about the peer — it is an absent one)."""
    if isinstance(value, bool) or not isinstance(value, (int, str)):
        return None
    try:
        number = int(value)
    except (TypeError, ValueError):
        return None
    return number if number > 0 else None

@classmethod
def from_backends(cls, backends: Iterable[object], **kwargs) -> "ReadinessCache":
    """Build a cache from an iterable of backends (``.name`` + ``.base_url``).

    Convenience for the later wiring task: pass ``table.backends`` directly.
    Duck-typed (reads only ``.name`` / ``.base_url``) so this module needs no
    import of :class:`lobes.gateway._routing.Backend` and stays decoupled.
    """
    targets = {b.name: b.base_url for b in backends}  # type: ignore[attr-defined]
    return cls(targets, **kwargs)

def _default_adapter_probe(self, base_url: str, declared: tuple[str, ...]) -> frozenset[str]:
    """The default adapter probe: :func:`probe_backend_adapters` bound to
    our LOCAL ``timeout`` — these are co-resident fleet backends on the
    internal compose network, so they share the local probe's budget, never
    the peer thread's cross-box one."""
    return probe_backend_adapters(base_url, declared, timeout=self._timeout)

@staticmethod
def _as_advert(result: "PeerAdvert | bool") -> PeerAdvert:
    """Normalise a probe result to a :class:`PeerAdvert`.

    An injected probe from before #220 returns a plain ``bool``; it keeps
    working and simply says nothing about context (``None`` = unknown).
    """
    if isinstance(result, PeerAdvert):
        return result
    return PeerAdvert(ready=bool(result), context=None)

@dataclass(frozen=True)
class TunnelTarget:
    """Where an accepted handshake goes: the local realtime bridge."""

    host: str
    port: int
    path: str  # the request target, query string included, verbatim

def plan_realtime_upgrade(
    table, cfg, path: str, headers: Iterable[tuple[str, str]], *, mesh_stt_origin: str | None = None
):
    """Decide what to do with a ``/v1/realtime`` request. Pure.

    Returns a :class:`TunnelTarget` to tunnel, or a :class:`RealtimeRefusal`.
    Precedence deliberately mirrors :func:`lobes.gateway.server.
    handle_audio_request` so the realtime lane refuses for the same reasons,
    in the same order, as the batch lane it sits beside — with the one
    documented divergence that an armed peer proxy does NOT forward here.
    """
    headers = list(headers)
    if not is_websocket_upgrade(headers):
        # A plain GET to a WebSocket-only route. 426 says what to do about it;
        # a 404 would wrongly suggest the route does not exist.
        return RealtimeRefusal(kind="not_an_upgrade", status=426)
    if REALTIME_ROLE in getattr(table, "infeasible", frozenset()):
        return RealtimeRefusal(
            kind="role_infeasible",
            status=404,
            role=REALTIME_ROLE,
            peer_origin=getattr(table, "peer_origins", {}).get(REALTIME_ROLE) or mesh_stt_origin,
        )
    if not cfg.audio_url:
        return RealtimeRefusal(kind="audio_not_configured", status=404)
    parts = urlsplit(cfg.audio_url)
    return TunnelTarget(
        host=parts.hostname or "",
        port=parts.port or (443 if parts.scheme == "https" else 80),
        path=path,
    )

def status_of(head: bytes) -> int:
    """The status code from a raw response head (``0`` if unparseable)."""
    try:
        return int(head.split(b"\r\n", 1)[0].split(b" ")[1])
    except (IndexError, ValueError):
        return 0

def pump(src, dst) -> None:
    """Relay ``src`` → ``dst`` until EOF, then half-close ``dst``.

    Never raises: a reset peer mid-session is an ordinary end of session, not
    a gateway error. The half-close is what makes the *other* direction's pump
    see EOF and unwind — without it a dropped client would strand a thread
    (spec claim c26).
    """
    try:
        while True:
            data = src.recv(_CHUNK)
            if not data:
                break
            dst.sendall(data)
    except OSError:
        pass
    finally:
        try:
            dst.shutdown(socket.SHUT_WR)
        except OSError:
            pass

def _shutdown_both(sock) -> None:
    """Shut a socket down in both directions, ignoring an already-dead peer.

    This is what unblocks a pump parked in ``recv``; ``pump``'s own
    ``SHUT_WR`` is the graceful half-close that lets a live peer flush first.
    """
    try:
        sock.shutdown(socket.SHUT_RDWR)
    except OSError:
        pass

def _default_opener(
    url: str, timeout: float, api_key: str | None
) -> tuple[int, bytes]:  # pragma: no cover - opens a socket
    """GET *url* scheme-aware, attach ``Authorization`` iff *api_key* is set.

    Mirrors :func:`lobes.gateway._readiness._default_peer_opener` exactly: a
    peer origin is an operator-typed cross-box URL that may legitimately be
    ``https://`` (a tunnel or TLS-terminating proxy), so the scheme is
    honoured rather than assumed. The key is used once to build the header
    and never logged or persisted.
    """
    parts = urlsplit(url)
    if parts.scheme == "https":
        conn: http.client.HTTPConnection = http.client.HTTPSConnection(
            parts.hostname, parts.port or 443, timeout=timeout
        )
    else:
        conn = http.client.HTTPConnection(parts.hostname, parts.port or 80, timeout=timeout)
    try:
        headers = {"Authorization": f"Bearer {api_key}"} if api_key else {}
        target = parts.path or "/"
        if parts.query:
            target = f"{target}?{parts.query}"
        conn.request("GET", target, headers=headers)
        response = conn.getresponse()
        return response.status, response.read()
    finally:
        conn.close()

def _as_int(value: object) -> int | None:
    """Best-effort positive int, else ``None`` (unknown — never a silent 0)."""
    try:
        number = int(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None
    return number if number > 0 else None

def _as_capacity(raw: object) -> float | None:
    """The raw published capacity as a float, or ``None`` when it is absent or
    not a positive finite number (the values :func:`resolve_capacity` refuses).

    Stored on :attr:`ReplicaState.capacity` PRE-clamp, so an operator can see
    what the peer claimed next to what this box used — and so the fingerprint
    keying below can tell "the same measurement again" from "a new one".
    """
    if raw is None:
        return None
    try:
        value = float(raw)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return None
    if not (value > 0.0) or value == float("inf"):
        return None
    return value

def _resolve(self, raw: object) -> tuple[float, str]:
    """This cache's ingest gate — :func:`resolve_capacity` bound to its
    configured clamp and kill switch."""
    return resolve_capacity(
        raw,
        capacity_max=self._capacity_max,
        kill_switch=self._capacity_kill_switch,
    )

def _raw_states(self) -> tuple[ReplicaState, ...]:
    """The snapshot exactly as probed — no in-flight fold. The lock is held
    only for the dict reads; every state is frozen."""
    with self._lock:
        states: list[ReplicaState] = []
        if self._local_state is not None:
            states.append(self._local_state)
        states.extend(self._peer_states[peer.origin] for peer in self._peers)
        return tuple(states)

def _get_json(self, url: str, timeout: float, api_key: str | None) -> tuple[dict | None, str]:
    """GET *url* → ``(payload | None, health)``. Never raises."""
    try:
        status, body = self._urlopen(url, timeout, api_key or None)
    except BaseException as exc:  # noqa: BLE001
        # Every failure degrades, never crashes.
        if isinstance(exc, (KeyboardInterrupt, SystemExit)):
            raise
        return None, _classify(exc)
    if status != 200:
        return None, "error"
    try:
        payload = json.loads(body)
    except (ValueError, TypeError):
        return None, "error"
    if not isinstance(payload, dict):
        return None, "error"
    return payload, "ok"

def _probe_local(self, lane: LocalLane, previous: ReplicaState) -> ReplicaState:
    payload, health = self._get_json(
        lane.base_url.rstrip("/") + _MODELS_PATH, self._timeout, None
    )
    if payload is None:
        return previous.evolve(
            ready=False, health=health, fingerprint=None, running=0, waiting=0
        )
    fingerprint = self._local_fingerprint(payload, lane)
    if fingerprint is None:
        return previous.evolve(ready=False, health="error", fingerprint=None)
    running, waiting = self._local_load(lane)
    raw = lane.weight
    resolved, capacity, calibrated, pin, note = self._keyed_capacity(previous, raw, fingerprint)
    return previous.evolve(
        ready=True,
        busy=False,  # local pressure is the caller's own signal, not a probe
        health="ok",
        running=running,
        waiting=waiting,
        fingerprint=fingerprint,
        compatible=True,
        reason=note,
        last_seen=self._now(),
        weight=resolved,
        capacity=capacity,
        calibrated=calibrated,
        capacity_fingerprint=pin,
    )

def _peer_backend_entry(
    self, payload: Mapping[str, object], served_id: str | None
) -> Mapping[str, object] | None:
    backends = payload.get("backends")
    if not isinstance(backends, list):
        return None
    for entry in backends:
        if not isinstance(entry, Mapping):
            continue
        if served_id and entry.get("served_name") == served_id:
            return entry
        if entry.get("name") in (self._backend_name, self._role):
            return entry
    return None

def start(self) -> None:
    """Start the background refresh thread(s) (idempotent).

    The peer thread is spawned only when peers are declared — a box with
    no replica set spawns exactly one thread, and a box with no local lane
    and no peers spawns none.
    """
    if self._local_lane is not None:
        self._thread = self._start_thread(
            self._thread, self._stop, self._loop, "lobes-replica-cache"
        )
    if self._peers:
        self._peer_thread = self._start_thread(
            self._peer_thread, self._peer_stop, self._peer_loop, "lobes-replica-peer-cache"
        )

def _loop(self) -> None:
    self._refresh_local()
    while not self._stop.wait(self._interval):
        self._refresh_local()

def _peer_loop(self) -> None:
    self._refresh_peers()
    while not self._peer_stop.wait(self._interval):
        self._refresh_peers()

@staticmethod
def _join(thread: threading.Thread | None, bound: float) -> threading.Thread | None:
    if thread is None:
        return None
    thread.join(timeout=bound)
    return None if not thread.is_alive() else thread

def audio_role_for_path(path: str) -> str | None:
    """The first-class audio role (``stt``/``tts``) an audio path addresses.

    ``None`` for any other ``/v1/audio/*`` path — those stay on the legacy
    whole-namespace ``AUDIO_URL`` route, exactly as before #129.
    """
    return _AUDIO_ROLE_BY_PATH.get(path.split("?", 1)[0])

@dataclass(frozen=True)
class RenderRoute:
    """One resolved facade route: what to do, and for which job/artifact."""

    kind: str  # submit | status | artifacts | artifact | cancel | upload
    job_id: str = ""
    artifact: str = ""

def _parse_render_post(parts: list[str]) -> RenderRoute | None:
    if not parts:
        return RenderRoute(kind="submit")
    if parts == ["uploads", "image"]:
        return RenderRoute(kind="upload")
    if len(parts) == 3 and parts[0] == "jobs" and parts[2] == "cancel":
        return RenderRoute(kind="cancel", job_id=parts[1]) if _valid_job_id(parts[1]) else None
    return None

def _parse_render_get(parts: list[str]) -> RenderRoute | None:
    if len(parts) < 2 or parts[0] != "jobs" or not _valid_job_id(parts[1]):
        return None
    job_id = parts[1]
    if len(parts) == 2:
        return RenderRoute(kind="status", job_id=job_id)
    if parts[2] != "artifacts":
        return None
    if len(parts) == 3:
        return RenderRoute(kind="artifacts", job_id=job_id)
    if len(parts) == 4 and parts[3]:
        return RenderRoute(kind="artifact", job_id=job_id, artifact=parts[3])
    return None

def _backend_for(table: RoutingTable, served_name: str) -> Backend | None:
    for backend in model_routed_backends(table):
        if served_name == backend.served_name or served_name in backend.adapters:
            return backend
    return None

def selection_capacity(replica: ReplicaLike, candidates: Sequence[ReplicaLike]) -> float:
    """The capacity used to RANK *replica* within *candidates* — its own when
    calibrated, the neutral fallback otherwise."""

    if is_calibrated(replica):
        return replica.weight
    return neutral_capacity(candidates)

def selection_wait(replica: ReplicaLike, candidates: Sequence[ReplicaLike]) -> float:
    """The capacity-relative wait (utilisation) selection actually ranks by.

    Exposed so a caller can report the utilisation behind a routing decision
    (c24/h17) without re-deriving the neutral fallback.
    """

    return estimated_wait(replica, selection_capacity(replica, candidates))

def _is_selectable(replica: ReplicaLike, *, local_busy: bool) -> bool:
    if not (replica.compatible and replica.ready):
        return False
    if is_full(replica):
        return False
    if replica.local and (local_busy or replica.busy):
        # First-party shed verdict about THIS box. A peer's identical flag is
        # ignored — see the module docstring, step 1.
        return False
    return True

def _rank_key(replica: ReplicaLike, neutral: float) -> tuple:
    # Ascending capacity-relative wait; local (True) sorts before peer
    # (False) on a tie, so invert the boolean; then origin ascending for full
    # determinism when both wait and locality tie.
    capacity = replica.weight if is_calibrated(replica) else neutral
    return (estimated_wait(replica, capacity), not replica.local, replica.origin)

def _preferred_by_affinity(
    selectable: Sequence[ReplicaLike], affinity: str
) -> Optional[ReplicaLike]:
    if not selectable:
        return None
    best = None
    best_hash = None
    for replica in selectable:
        digest = zlib.crc32(f"{affinity}|{replica.origin}".encode("utf-8"))
        if (
            best_hash is None
            or digest < best_hash
            or (digest == best_hash and (best is None or replica.origin < best.origin))
        ):
            best_hash = digest
            best = replica
    return best

def _sole_reason(
    only: ReplicaLike,
    candidates: Sequence[ReplicaLike],
    *,
    local_busy: bool,
    has_local_input: bool,
) -> str:
    """The reason for the exactly-one-selectable case (step 3)."""
    if only.local:
        if len(candidates) == 1 and _active(only) == 0:
            return REASON_LOCAL_IDLE
        return REASON_SOLE_READY
    if local_busy and has_local_input:
        return REASON_LOCAL_BUSY_FORWARDED
    if any(c.local and is_full(c) for c in candidates):
        # The local replica was dropped on capacity, not on absence: this is
        # a load decision, so report it as one.
        return REASON_PEER_LESS_LOADED
    return REASON_SOLE_READY

def _reason_for(best: ReplicaLike, *, local_busy: bool) -> str:
    """The availability-ranking reason for *best* (step 4, pre-affinity)."""
    if not best.local and local_busy:
        return REASON_LOCAL_BUSY_FORWARDED
    if best.local and _active(best) == 0:
        return REASON_LOCAL_IDLE
    if not best.local:
        return REASON_PEER_LESS_LOADED
    return REASON_SOLE_READY

def _affinity_pick(
    selectable: Sequence[ReplicaLike],
    best: ReplicaLike,
    best_reason: str,
    *,
    affinity: Optional[str],
    affinity_margin: float,
    neutral: float,
) -> Selection:
    """Apply step 5's affinity override on top of the availability winner."""
    if affinity:
        preferred = _preferred_by_affinity(selectable, affinity)
        if preferred is not None:
            preferred_wait = estimated_wait(
                preferred, preferred.weight if is_calibrated(preferred) else neutral
            )
            best_wait = estimated_wait(best, best.weight if is_calibrated(best) else neutral)
            if preferred_wait - best_wait <= affinity_margin:
                return Selection(preferred.origin, preferred.local, REASON_AFFINITY)
    return Selection(best.origin, best.local, best_reason)

def select_replica(
    candidates: Sequence[ReplicaLike],
    *,
    affinity: Optional[str] = None,
    local_busy: bool = False,
    affinity_margin: float = 1.0,
) -> Selection:
    """Deterministically choose which replica (if any) should serve a
    pooled request. See the module docstring for the full policy."""

    selectable = _selectable(candidates, local_busy=local_busy)

    if not selectable:
        return Selection(None, False, REASON_NONE)

    has_local_input = any(c.local for c in candidates)
    neutral = neutral_capacity(candidates)
    ranked = _rank(selectable, neutral)
    best = ranked[0]

    if len(selectable) == 1:
        reason = _sole_reason(
            best, candidates, local_busy=local_busy, has_local_input=has_local_input
        )
        return Selection(best.origin, best.local, reason)

    best_reason = _reason_for(best, local_busy=local_busy)
    return _affinity_pick(
        selectable,
        best,
        best_reason,
        affinity=affinity,
        affinity_margin=affinity_margin,
        neutral=neutral,
    )

def _read(self) -> dict[str, float]:
    """Sample once, degrading to the zero baseline if the sampler raises."""
    try:
        sampled = self._sampler()
        return {
            "swap_used_percent": float(sampled.get("swap_used_percent", 0.0)),
            "iowait_percent": float(sampled.get("iowait_percent", 0.0)),
        }
    except Exception:  # nosec B110 — pressure is best-effort; never crash the gateway
        return dict(_ZERO_PRESSURE)

def current(self) -> dict[str, float]:
    """Return a copy of the cached pressure dict. Never samples, never blocks."""
    with self._lock:
        return dict(self._value)

def start(self) -> None:
    """Start the background refresh thread (idempotent)."""
    if self._thread is not None:
        return
    self._thread = threading.Thread(target=self._loop, name="lobes-pressure-cache", daemon=True)
    self._thread.start()

def _first_stt_origin(snapshot: "RoutingSnapshot | None") -> str | None:
    """Return the first verified stt origin, or first announced-only stt origin."""
    if snapshot is None:
        return None
    origins = snapshot.member_origins("stt")
    if origins:
        return origins[0]
    for m in snapshot.members:
        if "stt" in m.announced_roles:
            return m.origin
    return None

def _parse_body(body: bytes) -> dict | None:
    try:
        data = json.loads(body)
    except (ValueError, TypeError):
        return None
    return data if isinstance(data, dict) else None

def is_streaming(body: bytes) -> bool:
    """True when the request asked for an SSE stream (``"stream": true``)."""
    data = _parse_body(body)
    return bool(data and data.get("stream") is True)

def _invalid_api_key_body() -> bytes:
    """OpenAI-shaped 401 body for a missing / malformed / wrong inbound key.

    Mirrors the ``invalid_api_key`` error the OpenAI API emits, so a caller's
    existing error handling (e.g. openai-python raising ``AuthenticationError``
    on 401) works unchanged against the gateway. DELIBERATELY STATIC: the
    message names the fix (send ``Authorization: Bearer <key>``) but never
    distinguishes missing from malformed from wrong-key, and never echoes what
    the caller sent nor any part of the expected key — a 401 must not become a
    key-material oracle.
    """
    return json.dumps(
        {
            "error": {
                "message": (
                    "Invalid API key. Pass this gateway's configured key as "
                    "'Authorization: Bearer <key>'."
                ),
                "type": "invalid_api_key",
                "code": "invalid_api_key",
            }
        }
    ).encode("utf-8")

def sse_error_frame(message: str) -> bytes:
    """One OpenAI-shaped SSE error event (``data: {"error": {...}}``).

    Shaped like the error body a non-streamed request would have received, so a
    caller can parse a mid-stream failure with the code it already has. The
    ``type``/``code`` are the gateway's own ``upstream_error`` — this is never
    the upstream's own error payload (by the time it fires the upstream has
    stopped producing bytes), and mislabelling it as one would be a lie.
    """
    payload = json.dumps(
        {
            "error": {
                "message": message,
                "type": "upstream_error",
                "code": "upstream_error",
            }
        }
    )
    return b"data: " + payload.encode("utf-8") + b"\n\n"

def read(self, n: int) -> bytes:
    # read1, not read: read(n) blocks until n bytes or EOF, so a whole
    # SSE turn (a few KB) only returns at EOF. read1 returns as soon as
    # any bytes are available (b"" only at EOF), letting the relay loop
    # forward frames as they arrive instead of in one terminal burst.
    return self._resp.read1(n)

def close(self) -> None:
    try:
        self._conn.close()
    except OSError:
        pass

def _model_not_found_body(model: str) -> bytes:
    """OpenAI/vLLM-shaped 404 body for an id that was NEVER advertised (honesty h23).

    Mirrors the ``model_not_found`` error an OpenAI/vLLM backend emits for an
    unknown model, so a client sees a consistent 404 shape whether it hit the
    gateway or a backend directly. This is NOT a contradiction of "advertised
    implies reachable" (issue #92): the invariant is that a model *listed in
    ``/v1/models``* never 404s — an id that was never listed *should* 404. It is
    the deliberate converse of the never-404 race guarantee (see
    :func:`handle_post`).
    """
    return json.dumps(
        {
            "error": {
                "message": f"The model `{model}` does not exist.",
                "type": "model_not_found",
                "code": "model_not_found",
            }
        }
    ).encode("utf-8")

def _member_lane_roles() -> tuple[str, ...]:
    from lobes.roles import ROLES

    return tuple(r for r in ROLES if r not in _MEMBER_LANE_EXCLUDED_ROLES)

def _mesh_self_name() -> str:
    """This box's declared ``LOBES_MESH_NAME``, or ``""`` when mesh is off."""
    try:
        mesh_cfg = _build_mesh_config()
    except MeshConfigError:
        return ""
    return (mesh_cfg.enabled and mesh_cfg.name) or ""

def _hosted_roles(table: RoutingTable) -> frozenset[str]:
    """Roles whose backend is wired AND feasible on this box."""
    from lobes.roles import BACKEND_ROLE

    return frozenset(
        BACKEND_ROLE.get(b.name, b.name) for b in table.backends if b.name not in table.infeasible
    )

def member_lane_ids(
    table: RoutingTable,
    mesh_snapshot: "RoutingSnapshot | None",
    *,
    ready: "Mapping[str, bool | None] | None" = None,
) -> tuple[str, ...]:
    """Every ROUTABLE ``{role}-{member}`` id, for ``GET /v1/models``.

    A listed id must reach a live engine (#92), so a pending (not-yet-probed)
    member is left out (it answers 503 ``role_unverified`` until probed), and
    when *ready* — this box's readiness snapshot, as ``/v1/models`` holds it —
    is given, this box's own lane is listed only if its backend is ready and a
    peer's only if its probe reported the role ready. Live 2026-10-06: the
    Spark listed ``reranker-spark`` with no reranker container running. With
    *ready* ``None`` (no readiness evidence wired, the offline path) nothing is
    filtered, matching how the plain listing treats that case. With the mesh
    disabled this is ``()`` so the listing stays byte-identical.
    """
    if mesh_snapshot is None:
        return ()
    from lobes.gateway._mesh_routing import member_lanes
    from lobes.roles import ROLE_BACKEND

    self_name = _mesh_self_name()
    hosted = _hosted_roles(table)
    peer_ready = {m.name: set(m.ready_roles) for m in mesh_snapshot.members}

    def live(lane: "MemberLane") -> bool:
        if lane.pending:
            return False
        if ready is None:
            return True
        if lane.is_self:
            return bool(ready.get(ROLE_BACKEND.get(lane.role, lane.role)))
        return lane.role in peer_ready.get(lane.member, set())

    return tuple(
        lane.name
        for role in _member_lane_roles()
        for lane in member_lanes(
            mesh_snapshot, role, self_name=self_name, self_hosts=role in hosted
        )
        if live(lane)
    )

def _unhosted_self_lane(
    requested: str, self_name: str, roles: Collection[str]
) -> GatewayResponse | None:
    """404 ``role_infeasible`` for this box's own name on a role it does not
    host — never a forward to some OTHER member, and never a misleading
    ``model_not_found`` for a name that is part of the mesh contract."""
    from lobes.roles import ROLE_BACKEND

    if not self_name:
        return None
    for role in roles:
        if requested == f"{role}-{self_name}":
            return GatewayResponse(
                status=404,
                headers=[("Content-Type", _CONTENT_TYPE_JSON)],
                body=_role_infeasible_body(requested, ROLE_BACKEND.get(role, role)),
            )
    return None

def _busy_body(requested_tier: str) -> bytes:
    """Return the JSON body for a 429 busy (shed) response."""
    _LANE_LABELS = {"main": "cortex", "multimodal": "senses", "muse": "muse"}
    label = _LANE_LABELS.get(requested_tier, requested_tier)
    return json.dumps(
        {
            "error": {
                "message": f"{label} is under pressure; retry shortly",
                "type": "server_busy",
                "code": "busy",
            }
        }
    ).encode("utf-8")

def _mesh_member_marker(
    mesh_snapshot: RoutingSnapshot | None, origin: str
) -> list[tuple[str, str]]:
    """``X-Lobes-Mesh-Member`` header for the mesh member serving ``origin``.

    Extracted from :func:`_peer_only_forward` (S3776) — same behaviour, just
    named: an origin the mesh snapshot does not recognise (or no snapshot at
    all) yields no marker, exactly as the inline loop did.
    """
    if mesh_snapshot is None:
        return []
    for m in mesh_snapshot.members:
        if m.origin == origin:
            return [(MESH_MEMBER_HEADER, m.name)]
    return []

def _request_header(req_headers: Iterable[tuple[str, str]], name: str) -> str | None:
    """The first inbound header value matching ``name``, case-insensitively."""
    wanted = name.lower()
    for key, value in req_headers:
        if key.lower() == wanted:
            return value
    return None

@classmethod
def from_spec(cls, spec: PeerSpec) -> "_ForwardTarget":
    return cls(
        name=spec.name,
        origin=spec.origin,
        served_name=spec.served_name,
        api_key=spec.api_key or "",
    )

def _proxy_loop_body(arriving: str, spec: _ForwardTarget) -> bytes:
    """The 508 ``proxy_loop`` refusal body — names BOTH hops: the one already
    taken (the arriving marker value, stamped by the gateway that forwarded
    this request) and the one refused (this box's declared peer origin for the
    role). Never any key material."""
    return json.dumps(
        {
            "error": {
                "message": (
                    "refusing to proxy: this request already crossed one lobes "
                    f"proxy hop (X-Lobes-Proxied: {arriving}); forwarding it again "
                    f"to `{spec.origin}` for role `{spec.name}` could loop — peer "
                    "proxying is single-hop only (issues #115/#127)."
                ),
                "type": "proxy_loop",
                "code": "proxy_loop",
                "hops": [arriving, spec.origin],
            }
        }
    ).encode("utf-8")

def _peer_declined_body(spec: _ForwardTarget, raw: bytes) -> bytes | None:
    """The terminal body for a peer that answered 404 ``role_infeasible``.

    That verdict means the PEER also dropped the role — the operator's
    referral/proxy origin is misdeclared — so the error is TERMINAL (never
    another hop; there is no third box to ask). The peer's own body is kept,
    with its message rewritten to make unmistakable that the DECLARED PEER
    declined, not this gateway. Returns ``None`` when ``raw`` is not a
    ``role_infeasible`` error (any other 404 is the peer's authoritative
    client-error verdict and relays verbatim)."""
    try:
        data = json.loads(raw)
    except (ValueError, TypeError):
        return None
    error = data.get("error") if isinstance(data, dict) else None
    if not isinstance(error, dict):
        return None
    if "role_infeasible" not in (error.get("code"), error.get("type")):
        return None
    original = error.get("message")
    prefix = (
        f"the declared peer for this role (`{spec.origin}`) declined it as "
        "role_infeasible — the peer does not host this role either (a "
        "misdeclared referral/proxy origin); no further hop is attempted."
    )
    if isinstance(original, str) and original:
        error["message"] = f"{prefix} Peer said: {original}"
    else:
        error["message"] = prefix
    data["error"] = error
    return json.dumps(data).encode("utf-8")

def _peer_5xx_response(
    up: "_Upstream",
    spec: _ForwardTarget,
    peer_backend: Backend,
    proxied_by: tuple[str, str],
) -> GatewayResponse:
    """Map a ``>= 500`` peer response, special-casing a 508 proxy_loop.

    Extracted from :func:`_relay_to_target` (Sonar S3776). This also retires
    a second, later ``if up.status == 508`` branch in that function: because
    508 satisfies ``>= 500`` and this branch always returns, that later
    branch could never execute — dead code from the moment both were added,
    not a behaviour change to remove it.
    """
    if up.status == 508:
        # Special-case 508: if the peer returned proxy_loop, relay it
        # verbatim rather than laundering it into a retryable 503.
        raw = up.read_all()
        up.close()
        try:
            err_data = json.loads(raw)
            if isinstance(err_data, dict) and err_data.get("error", {}).get("type") == "proxy_loop":
                return GatewayResponse(
                    status=508,
                    headers=[("Content-Type", _CONTENT_TYPE_JSON), proxied_by],
                    body=raw,
                )
        except (json.JSONDecodeError, TypeError):
            pass
        # Not a proxy_loop error — treat as generic 503.
        return _peer_unavailable_response(spec, [f"{peer_backend.name}: HTTP {up.status}"])
    attempts = [f"{peer_backend.name}: HTTP {up.status}"]
    up.close()
    return _peer_unavailable_response(spec, attempts)

def prompt_id(self, job_id: str) -> str | None:
    """The upstream id for ``job_id``, or ``None`` if this process never
    issued it (an unknown, a forgotten, or another box's id — all three are
    the same answer here, which is the point)."""
    with self._lock:
        return self._issued.get(job_id)

def _render_error_body(message: str, error_type: str) -> bytes:
    """OpenAI-shaped error body for the render facade.

    Note what the ``render_job_not_found`` message deliberately does NOT say:
    whether the id was never issued, was evicted, or belongs to someone else.
    Distinguishing them would make the refusal an existence oracle over the
    box's render history — the very thing the job scoping exists to close.
    """
    return json.dumps(
        {"error": {"message": message, "type": error_type, "code": error_type}}
    ).encode()

def _render_json(status: int, payload: dict) -> GatewayResponse:
    return GatewayResponse(
        status=status,
        headers=[("Content-Type", _CONTENT_TYPE_JSON)],
        body=json.dumps(payload).encode(),
    )

def _render_error(status: int, error_type: str, message: str) -> GatewayResponse:
    return GatewayResponse(
        status=status,
        headers=[("Content-Type", _CONTENT_TYPE_JSON)],
        body=_render_error_body(message, error_type),
    )

def _render_relay_headers(headers: Iterable[tuple[str, str]]) -> list[tuple[str, str]]:
    """Upstream headers safe to pass back on a relayed artifact.

    Drops ``Content-Length``/``Transfer-Encoding`` on top of the usual
    hop-by-hop filter: the streaming relay re-chunks the body and sets its own
    framing, so an upstream length header would contradict the wire.
    """
    return [
        (k, v)
        for k, v in filter_headers(headers)
        if k.lower() not in ("content-length", "transfer-encoding")
    ]

def _json_or_none(raw: bytes) -> object:
    try:
        return json.loads(raw)
    except (ValueError, UnicodeDecodeError):
        return None

def _render_backend(self) -> Backend | None:
    """This box's wired-and-feasible render tenant, else ``None``."""
    if _RENDER_BACKEND in self.table.infeasible:
        return None
    return next((b for b in self.table.backends if b.name == _RENDER_BACKEND), None)

@staticmethod
def _render_job_not_found(route: RenderRoute) -> GatewayResponse:
    return _render_error(
        404,
        "render_job_not_found",
        f"no render job `{route.job_id}` was issued by this gateway. Only jobs "
        "submitted through POST /v1/render are addressable here, and a gateway "
        "restart forgets the ids it issued.",
    )

def _render_submit(self, backend: Backend, route: RenderRoute, body: bytes) -> GatewayResponse:
    """``POST /v1/render`` → ComfyUI ``POST /prompt``, and mint the job id."""
    status, raw, headers = self._render_fetch(
        backend,
        _COMFY_SUBMIT_PATH,
        method="POST",
        body=body,
        ctype=self.headers.get("Content-Type"),
    )
    if status != 200:
        # A rejected graph (ComfyUI's submit-time `node_errors`) is the
        # caller's OWN submission coming back — safe to relay verbatim, and
        # the only way a client learns which node it got wrong. No job id is
        # issued for it.
        return GatewayResponse(status=status, headers=_render_relay_headers(headers), body=raw)
    payload = _json_or_none(raw)
    prompt_id = ""
    if isinstance(payload, dict):
        prompt_id = str(payload.get("prompt_id") or "")
    if not prompt_id:
        return _render_error(
            502,
            "render_submit_failed",
            "the render backend accepted the submission but returned no prompt_id.",
        )
    job_id = self.render_jobs.issue(prompt_id)
    # The response names the GATEWAY's id and nothing of the upstream's —
    # leaking prompt_id would re-open exactly the id space job scoping shuts.
    out: dict = {"job_id": job_id, "status": "queued"}
    if isinstance(payload, dict) and payload.get("node_errors"):
        out["node_errors"] = payload["node_errors"]
    return _render_json(200, out)

def _render_job_payload(self, backend: Backend, prompt_id: str) -> tuple[int, object]:
    status, raw, _headers = self._render_fetch(
        backend, _COMFY_JOB_PATH.format(quote(prompt_id, safe="")), method="GET"
    )
    return status, _json_or_none(raw)

def _render_status(self, backend: Backend, route: RenderRoute, body: bytes) -> GatewayResponse:
    """``GET /v1/render/jobs/<job_id>`` → ComfyUI ``GET /api/jobs/<prompt_id>``."""
    prompt_id = self._render_prompt_id(route)
    if prompt_id is None:
        return self._render_job_not_found(route)
    status, payload = self._render_job_payload(backend, prompt_id)
    if status != 200:
        return _render_error(
            502,
            "render_upstream_error",
            f"the render backend answered {status} for this job.",
        )
    artifacts = extract_job_artifacts(payload)
    return _render_json(
        200,
        {
            "job_id": route.job_id,
            "state": _render_job_state(payload, artifacts),
            "artifacts": [dict(a) for a in artifacts],
        },
    )

def _render_artifact_index(
    self, backend: Backend, route: RenderRoute, body: bytes
) -> GatewayResponse:
    """``GET /v1/render/jobs/<job_id>/artifacts`` — this job's outputs only."""
    resp = self._render_status(backend, route, body)
    if resp.status != 200 or resp.body is None:
        return resp
    payload = json.loads(resp.body)
    return _render_json(200, {"job_id": payload["job_id"], "artifacts": payload["artifacts"]})

def _render_artifact(
    self, backend: Backend, route: RenderRoute, body: bytes
) -> GatewayResponse:
    """``GET /v1/render/jobs/<job_id>/artifacts/<name>`` → ``GET /view`` bytes.

    The name is matched against THIS job's own outputs, read back from the
    upstream on every fetch, before ``/view`` is dialed at all. That extra
    round trip is the enforcement: it is what makes the counter-named
    neighbour of a legitimate artifact unreachable rather than merely
    undocumented.
    """
    prompt_id = self._render_prompt_id(route)
    if prompt_id is None:
        return self._render_job_not_found(route)
    status, payload = self._render_job_payload(backend, prompt_id)
    if status != 200:
        return _render_error(
            502,
            "render_upstream_error",
            f"the render backend answered {status} for this job.",
        )
    match = next(
        (a for a in extract_job_artifacts(payload) if a["filename"] == route.artifact),
        None,
    )
    if match is None:
        return _render_error(
            404,
            "render_artifact_not_found",
            "this render job produced no such artifact.",
        )
    query = urlencode(
        {
            "filename": match["filename"],
            "subfolder": match["subfolder"],
            "type": match["type"],
        }
    )
    up = self._render_open(backend, f"{_COMFY_VIEW_PATH}?{query}", method="GET")
    if up.status != 200:
        try:
            raw = _render_read_all(up, backend)
        finally:
            up.close()
        return GatewayResponse(
            status=502,
            headers=[("Content-Type", _CONTENT_TYPE_JSON)],
            body=_render_error_body(
                f"the render backend answered {up.status} for this artifact "
                f"({len(raw)} bytes discarded).",
                "render_upstream_error",
            ),
        )
    # Streamed, never buffered: a render can be tens of megabytes, and
    # `_relay_streaming` re-chunks arbitrary binary verbatim (t8).
    return GatewayResponse(
        status=up.status,
        headers=_render_relay_headers(up.headers),
        upstream=up,

def _render_cancel(self, backend: Backend, route: RenderRoute, body: bytes) -> GatewayResponse:
    """``POST /v1/render/jobs/<job_id>/cancel`` — that job, never the queue.

    Scoped for the same reason innereye's own client refuses to fall back
    to ``POST /interrupt``: interrupting kills whatever is running, which
    is not necessarily the job the caller asked about.
    """
    prompt_id = self._render_prompt_id(route)
    if prompt_id is None:
        return self._render_job_not_found(route)
    status, raw, headers = self._render_fetch(
        backend,
        _COMFY_CANCEL_PATH.format(quote(prompt_id, safe="")),
        method="POST",
        body=b"",
    )
    if status != 200:
        return _render_error(
            502,
            "render_upstream_error",
            f"the render backend answered {status} cancelling this job.",
        )
    return GatewayResponse(status=200, headers=_render_relay_headers(headers), body=raw)

def _dispatch_mesh_post(self, route: str) -> bool:
    """Handle ``route`` as a ``POST /mesh/*`` route; ``True`` if it answered.

    Extracted from :meth:`do_POST` (Sonar S3776) — identical behaviour,
    mirroring :meth:`_dispatch_mesh_get` except an unknown mesh route
    answers 405 here (this handler only ever sees POSTs), not 404.
    """
    if not (_is_mesh_route(route) and self.mesh_routes is not None):
        return False
    result = dispatch_mesh(self, self.mesh_routes)
    if result is not None:
        status, headers, body = result
        self._send_simple(status, headers, body)
        return True
    # Finding 20: mesh enabled but unknown mesh route → 405, not fall-through.
    self._send_simple(
        405,
        [("Content-Type", _CONTENT_TYPE_JSON)],
        json.dumps(
            {
                "error": {
                    "message": f"method not allowed: {self.command} {route}",
                    "type": "method_not_allowed",
                }
            }
        ).encode(),
    )
    return True

def _deliver(self, resp: GatewayResponse) -> None:
    """Send a built :class:`GatewayResponse`: a gateway body, or a relay.

    Shared by :meth:`do_POST` and :meth:`do_GET` so BOTH verbs get the same
    delivery contract — the same buffered/streaming choice, the same
    upstream close, and the same `release` in a `finally`. Method-agnostic
    by construction: nothing here reads `self.command`.
    """
    try:
        if resp.upstream is None:
            self._send_simple(resp.status, resp.headers, resp.body or b"")
            return
        try:
            if resp.streaming:
                self._relay_streaming(resp)
            else:
                self._relay_buffered(resp)
        finally:
            resp.upstream.close()
    finally:
        resp.release()

def _read_body(self, limit: int | None = None) -> bytes:
    """Read the request body, refusing one over ``limit`` before buffering it.

    ``limit=None`` (the default, and what every non-render route passes) is
    the pre-limit behaviour verbatim. With a limit:

    * a ``Content-Length`` over it is refused WITHOUT reading a single byte
      off the socket — the declared size is enough to know;
    * a chunked body is refused incrementally, on the first chunk header
      that would take the total past the cap (see :func:`read_chunked_body`
      with ``strict=True``), since nothing declares its size up front.

    Both raise :class:`RequestBodyTooLarge`, which leaves an unread body on
    the socket — :meth:`_reject_payload_too_large` must therefore close the
    connection rather than keep it alive.
    """
    cl = self.headers.get("Content-Length")
    if cl is not None:
        try:
            length = int(cl)
        except ValueError:
            length = 0
        if limit is not None and length > limit:
            raise RequestBodyTooLarge(length, limit, self._post_body_limit_knob())
        return self.rfile.read(length) if length > 0 else b""
    if "chunked" in (self.headers.get("Transfer-Encoding") or "").lower():
        if limit is None:
            return read_chunked_body(self.rfile)
        try:
            return read_chunked_body(self.rfile, limit, strict=True)
        except RequestBodyTooLarge as exc:
            # read_chunked_body knows the cap but not whose knob set it.
            raise RequestBodyTooLarge(None, exc.limit, self._post_body_limit_knob()) from exc
    return b""

def _relay_buffered(self, resp: GatewayResponse) -> None:
    data = resp.upstream.read_all()
    self.send_response(resp.status)
    for key, value in resp.headers:
        self.send_header(key, value)
    self.send_header("Content-Length", str(len(data)))
    self.end_headers()
    if data:
        self.wfile.write(data)

def _end_stream(self, resp: GatewayResponse, upstream_failure: str | None) -> None:
    """Write the terminal frames. Never raises — the response is over either way."""
    tail = CHUNK_TERMINATOR
    if upstream_failure is not None:
        self._abort_stream(resp, f"upstream read failed: {upstream_failure}")
        tail = (
            frame_chunk(
                sse_error_frame(
                    "the upstream backend stopped sending mid-stream "
                    f"({upstream_failure}); this response is incomplete"
                )
            )
            + frame_chunk(SSE_DONE)
            + CHUNK_TERMINATOR
        )
    try:
        self.wfile.write(tail)
        self.wfile.flush()
    except OSError as exc:
        # The client hung up between the last chunk and the terminator.
        # There is nothing left to deliver and nothing left to do.
        self._abort_stream(resp, f"client gone before terminator: {type(exc).__name__}: {exc}")

def _send_simple(self, status: int, headers: list[tuple[str, str]], body: bytes) -> None:
    self.send_response(status)
    for key, value in headers:
        self.send_header(key, value)
    self.send_header("Content-Length", str(len(body)))
    self.end_headers()
    if body:
        self.wfile.write(body)

def declared_lane_config(lane: Mapping[str, str], *, runtime: str = "") -> dict[str, str]:
    """Adapt one backend's :attr:`RoutingTable.lane_fingerprints` entry to the
    key vocabulary :class:`~lobes.gateway._replicas.LocalLane` expects.

    Any key absent here reads back as ``unknown`` in the published
    fingerprint — never a catalog guess (c33/h25)."""
    declared = {
        _DECLARED_KEY_FOR_SUFFIX.get(suffix, suffix.lower()): value
        for suffix, value in lane.items()
    }
    # A lane's engine is known from the role registry even when nothing ever
    # live-probes it (no declared pool); a declared <PREFIX>_RUNTIME still wins.
    if runtime and not declared.get("runtime"):
        declared["runtime"] = runtime
    return declared

def replica_snapshot_provider(
    caches: Mapping[str, ReplicaCache] | None,
) -> ReplicaSnapshot | None:
    """The dispatch seam: backend name → that role's replicas, or ``()``.

    ``None`` for an empty/absent cache map, which is what keeps the pool path
    provably inert on a no-pool deployment (:func:`handle_post` short-circuits
    on a ``None`` provider before touching the routing table)."""
    if not caches:
        return None

    def snapshot(backend_name: str) -> tuple[ReplicaState, ...]:
        cache = caches.get(backend_name)
        return cache.current() if cache is not None else ()

    return snapshot

def replica_role_snapshot(
    caches: Mapping[str, ReplicaCache] | None,
) -> dict[str, tuple[ReplicaState, ...]] | None:
    """The /capabilities seam: ROLE name → that role's replicas (c9).

    ``None`` for an empty/absent cache map, so ``annotate_replicas`` stays a
    no-op and the payload keeps its pre-pool bytes."""
    if not caches:
        return None
    # Deferred import — see the module-level NOTE on the lobes.roles cycle.
    from lobes.roles import ROLE_BACKEND

    return {
        role: caches[backend].current()
        for role, backend in ROLE_BACKEND.items()
        if backend in caches
    }

def __getattr__(name: str) -> object:
    """Serve ``MACHINE_PROFILES`` from the live registry (PEP 562).

    Kept as a module attribute (not a static tuple) so a chip registered after
    import — a plugin or a test — is reflected without editing this module.
    """
    if name == "MACHINE_PROFILES":
        return machine_profiles()
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

def workload_profile(name: str) -> WorkloadProfile:
    """Resolve a purpose by canonical name or alias; raise on an unknown value."""
    key = (name or "").strip().lower()
    for profile in WORKLOAD_PROFILES:
        if key in profile.aliases:
            return profile
    known = ", ".join(p.name for p in WORKLOAD_PROFILES)
    raise ModelGearError(
        code=EXIT_USER_ERROR,
        message=f"unknown purpose {name!r}",
        remediation=f"choose one of: {known}",
    )

def machine_profile(name: str) -> MachineProfile:
    """Resolve a machine by canonical name; raise on an unknown value."""
    strategy = machines.get(name)
    if strategy is not None:
        return _machine_profile_from_strategy(strategy)
    known = ", ".join(machines.names())
    raise ModelGearError(
        code=EXIT_USER_ERROR,
        message=f"unknown machine {name!r}",
        remediation=f"choose one of: {known}, or 'auto' to detect",
    )

def resolve_machine(name: str, *, gpu_name: str | None = None, hostname: str | None = None) -> str:
    """Resolve ``--machine`` to a concrete profile name (``auto`` → detect)."""
    if (name or "").strip().lower() in ("", "auto"):
        return detect_machine(gpu_name, hostname)
    return machine_profile(name).name

def _parse(text: str, *, source: str) -> dict:
    try:
        return tomllib.loads(text)
    except tomllib.TOMLDecodeError as exc:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"malformed profile TOML in {source}: {exc}",
            remediation="fix the TOML syntax (tomllib is the parser — stdlib, no YAML)",
        ) from exc

def builtin_names() -> tuple[str, ...]:
    """The names of every packaged built-in profile, sorted."""
    root = files(BUILTIN_PACKAGE)
    names = [
        entry.name[: -len(PROFILE_SUFFIX)]
        for entry in root.iterdir()
        if entry.name.endswith(PROFILE_SUFFIX)
    ]
    return tuple(sorted(names))

def available_profiles(deploy_dir: Path | str | None = None) -> dict[str, Profile]:
    """Every resolvable profile: built-ins, then operator profiles override by name."""
    merged: dict[str, Profile] = {name: load_builtin(name) for name in builtin_names()}
    if deploy_dir is not None:
        merged.update(discover_operator_profiles(deploy_dir))
    return merged

def resolve_profile(name: str, deploy_dir: Path | str | None = None) -> Profile:
    """Resolve ``name`` to a :class:`Profile` — operator profiles win over built-ins.

    Raises :class:`ModelGearError` (``EXIT_USER_ERROR``) for an unknown name;
    never falls back to a default profile silently.
    """
    key = (name or "").strip().lower()
    if deploy_dir is not None:
        operator = discover_operator_profiles(deploy_dir)
        if key in operator:
            return operator[key]
    builtin = load_builtin(key)
    if builtin is not None:
        return builtin
    known = ", ".join(builtin_names())
    raise ModelGearError(
        code=EXIT_USER_ERROR,
        message=f"unknown profile {name!r}",
        remediation=f"choose one of: {known}, or add <deploy-dir>/profiles/{name}.toml",
    )

def _role_env(role: str, rp: RoleProfile) -> dict[str, str]:
    prefix = ROLE_ENV_PREFIX[role]
    env: dict[str, str] = {}
    if not rp.feasible:
        # An infeasible role has nothing to serve — no model/knob opinions are
        # rendered for it, just the marker a later task (t6) will honor.
        env[f"{prefix}_FEASIBLE"] = "false"
        return env
    if rp.model is not None:
        env[f"{prefix}_MODEL"] = rp.model
        env[f"{prefix}_SERVED_NAME"] = rp.model
    for field_name, suffix in _KNOB_ENV_SUFFIX.items():
        value = getattr(rp, field_name)
        if value is None:
            continue
        env_name = f"{prefix}_{suffix}"
        if field_name in _BOOL_KNOB_TOKENS:
            env[env_name] = _BOOL_KNOB_TOKENS[field_name][bool(value)]
        elif isinstance(value, bool):
            env[env_name] = "true" if value else "false"
        else:
            env[env_name] = str(value)
    return env

def to_dict(self) -> dict[str, Any]:
    """Plain-dict view — the exact shape :func:`_exclusive_group` accepts back."""
    return {
        "roles": list(self.roles),
        "shapes": list(self.shapes),
        "reason": self.reason,
    }

def _str_tuple(name: str, key: str, raw: Any, *, minimum: int) -> tuple[str, ...]:
    """A validated tuple of plain strings for one ``exclusive_roles`` key."""
    if not isinstance(raw, (list, tuple)) or not all(isinstance(item, str) for item in raw):
        raise _profile_error(
            message=f"profile {name!r}: exclusive_roles {key!r} must be a list of strings, "
            f"got {raw!r}",
            remediation=f'declare it as {key} = ["…", "…"]',
        )
    values = tuple(raw)
    if len(values) < minimum:
        raise _profile_error(
            message=(
                f"profile {name!r}: exclusive_roles {key!r} needs at least {minimum} "
                f"entr{'y' if minimum == 1 else 'ies'}, got {list(values)!r}"
            ),
            remediation=(
                "a mutual-exclusion group is a statement about a PAIR — one role "
                "cannot conflict with itself"
                if key == "roles"
                else f"name the shape(s) that resolve the group in {key}"
            ),
        )
    if len(set(values)) != len(values):
        raise _profile_error(
            message=f"profile {name!r}: exclusive_roles {key!r} repeats an entry: {list(values)!r}",
            remediation=f"list each name once in {key}",
        )
    return values

def _exclusive_group(name: str, raw: Any) -> ExclusiveRoles:
    """Validate and build ONE ``[[exclusive_roles]]`` entry."""
    if not isinstance(raw, Mapping):
        raise _profile_error(
            message=f"profile {name!r}: each exclusive_roles entry must be a table/mapping",
            remediation="declare each group as a [[exclusive_roles]] table with "
            f"keys: {', '.join(_EXCLUSIVE_KEYS)}",
        )
    unknown = set(raw.keys()) - set(_EXCLUSIVE_KEYS)
    if unknown:
        raise _profile_error(
            message=(f"profile {name!r}: unknown exclusive_roles key(s) {sorted(unknown)!r}"),
            remediation=f"known keys: {', '.join(_EXCLUSIVE_KEYS)}",
        )
    roles = _str_tuple(name, "roles", raw.get("roles", []), minimum=2)
    unknown_roles = set(roles) - set(ROLES)
    if unknown_roles:
        raise _profile_error(
            message=(
                f"profile {name!r}: unknown role(s) {sorted(unknown_roles)!r} "
                "in an exclusive_roles group"
            ),
            remediation=f"known roles: {', '.join(ROLES)}",
        )
    shapes = _str_tuple(name, "shapes", raw.get("shapes", []), minimum=1)
    reason = raw.get("reason", "")
    if not isinstance(reason, str):
        raise _profile_error(
            message=f"profile {name!r}: exclusive_roles 'reason' must be str, "
            f"got {type(reason).__name__} ({reason!r})",
            remediation='quote it — reason = "…the measured arithmetic…"',
        )
    return ExclusiveRoles(roles=roles, shapes=shapes, reason=reason)

def _exclusive_roles_from_value(name: str, raw: Any) -> tuple[ExclusiveRoles, ...]:
    """Validate and build a profile's ``exclusive_roles`` declaration."""
    if not isinstance(raw, (list, tuple)):
        raise _profile_error(
            message=f"profile {name!r}: 'exclusive_roles' must be a list of tables",
            remediation="declare each group as a [[exclusive_roles]] table",
        )
    return tuple(_exclusive_group(name, entry) for entry in raw)

def _gpu_access_from_value(name: str, raw: Any) -> str:
    """Validate a profile's ``gpu_access`` declaration (loud, never silent)."""
    if not isinstance(raw, str) or raw not in GPU_ACCESS_MODES:
        raise _profile_error(
            message=f"profile {name!r}: gpu_access must be one of {list(GPU_ACCESS_MODES)}, "
            f"got {raw!r}",
            remediation=(
                f'declare gpu_access = "{GPU_ACCESS_DEVICES}" (the default: '
                f'deploy.resources GPU request) or "{GPU_ACCESS_RUNTIME}" '
                "(csv-mode boards: runtime: nvidia)"
            ),
        )
    return raw

def _is_optional_number(value: Any) -> bool:
    # bool is a subclass of int in Python — reject it explicitly BEFORE the
    # isinstance(value, (int, float)) check, or `feasible = "false"`-style
    # TOML mistakes (here, a stray `true`/`false` on a numeric knob) would
    # silently pass as a number.
    if isinstance(value, bool):
        return False
    return value is None or isinstance(value, (int, float))

def _is_optional_int(value: Any) -> bool:
    if isinstance(value, bool):
        return False
    return value is None or isinstance(value, int)

@staticmethod
def from_dict(role: str, data: Mapping[str, Any]) -> "RoleProfile":
    """Build one role's declaration, rejecting any unrecognised key.

    An unknown knob name is a LOAD ERROR, never a silently dropped key —
    a typo'd knob in an operator-authored profile must fail loudly rather
    than pretend the operator's intended override was applied.
    """
    known = {f.name for f in fields(RoleProfile)}
    unknown = set(data.keys()) - known
    if unknown:
        raise _profile_error(
            message=f"unknown knob(s) {sorted(unknown)!r} for role {role!r}",
            remediation=f"known knobs: feasible, model, {', '.join(KNOB_NAMES)}",
        )
    for key, value in data.items():
        validator, expected = _FIELD_VALIDATORS[key]
        if not validator(value):
            got = type(value).__name__
            raise _profile_error(
                message=(
                    f"role {role!r}: knob {key!r} must be {expected}, got {got} ({value!r})"
                ),
                remediation=(
                    f"fix the value's type for {key!r} in role {role!r} "
                    f"(expected {expected})"
                ),
            )
    _check_lane_gates(role, data)
    return RoleProfile(**dict(data))

def to_dict(self) -> dict[str, Any]:
    """Plain-dict view of every declared field (round-trips through ``from_dict``)."""
    return {
        "name": self.name,
        "summary": self.summary,
        "roles": {role: rp.to_dict() for role, rp in self.roles.items()},
        "host_env": dict(self.host_env),
        "gpu_access": self.gpu_access,
        "exclusive_roles": [group.to_dict() for group in self.exclusive_roles],
    }

def shape_services(shape: Shape, profile: Profile) -> tuple[str, ...]:
    """The compose services a (shape, card) pair actually brings up, sorted.

    A core role the shape drops -- or one the card marks infeasible -- has no
    service here (the "dropped role -> no running service" contract). The
    gateway always fronts the fleet; the realtime bridge comes up with the audio
    overlay. The opt-in `minor` gear (:data:`OPT_IN_ROLES`) has no card-level
    feasibility of its own -- unlike the four core roles, it is never
    conditioned on ``profile.role(...).feasible`` -- so it is added whenever
    the shape hosts it, exactly like the audio roles.
    """
    services = {GATEWAY_SERVICE}
    composed = compose_profile(shape, profile)
    for role in ROLES:
        role_profile = composed.role(role)
        if shape.hosts_role(role) and role_profile.feasible:
            # Engine-aware: a role whose composed model is a non-vLLM gear runs
            # its own lane, never ROLE_SERVICE's vLLM one (see role_service).
            services.add(role_service(role, role_profile))
    audio_hosted = False
    for role in AUDIO_ROLES:
        if shape.hosts_role(role):
            services.add(ROLE_SERVICE[role])
            audio_hosted = True
    if audio_hosted:
        services.add(REALTIME_SERVICE)
    for role in OPT_IN_ROLES:
        if shape.hosts_role(role):
            services.add(ROLE_SERVICE[role])
    return tuple(sorted(services))

def _parse(text: str, *, source: str) -> dict:
    try:
        return tomllib.loads(text)
    except tomllib.TOMLDecodeError as exc:
        raise ModelGearError(
            code=EXIT_USER_ERROR,
            message=f"malformed shape TOML in {source}: {exc}",
            remediation="fix the TOML syntax (tomllib is the parser -- stdlib, no YAML)",
        ) from exc

def to_dict(self) -> dict[str, Any]:
    """Plain-dict view, ``{"name", "summary", "hosts", "overrides"}``."""
    return {
        "name": self.name,
        "summary": self.summary,
        "hosts": list(self.hosts),
        "overrides": {role: rp.to_dict() for role, rp in self.overrides.items()},
    }

def builtin_shape_names() -> tuple[str, ...]:
    """The names of every packaged built-in shape, sorted."""
    root = files(BUILTIN_SHAPES_PACKAGE)
    names = [
        entry.name[: -len(SHAPE_SUFFIX)]
        for entry in root.iterdir()
        if entry.name.endswith(SHAPE_SUFFIX)
    ]
    return tuple(sorted(names))

def load_builtin_shape(name: str) -> Shape | None:
    """Load one packaged built-in shape by name, or ``None`` if it doesn't exist."""
    root = files(BUILTIN_SHAPES_PACKAGE)
    node = root / f"{name}{SHAPE_SUFFIX}"
    if not node.is_file():
        return None
    data = _parse(node.read_text(encoding="utf-8"), source=f"builtin-shape:{name}")
    return Shape.from_dict(name, data)

def retry_after_from_headers(headers: Mapping[str, str] | None) -> str | None:
    """The response's ``Retry-After`` value, matched case-insensitively.

    ``None`` when there is no such header (or no headers at all) — the route
    may or may not have them, and an absent hint is a fact worth reporting,
    not a reason to fail.
    """
    if not headers:
        return None
    for key, value in headers.items():
        if key.lower() == "retry-after":
            text = str(value).strip()
            return text or None
    return None

def _response_timings(self) -> StageTimings | None:
    """This response's measured stages, or ``None`` when nobody measured."""
    if self._timings_provider is None:
        return None
    return self._timings_provider() or None

@property
def pending_payloads(self) -> int:
    """How many payloads are waiting to be drained (observation/tests)."""
    return len(self._outbox)

@property
def outstanding_tool_call(self) -> OutstandingToolCall | None:
    """The one call this session is waiting on, answered or not."""
    return self._tool_call

def _remember_pending(self, text: str, item_id: str | None) -> None:
    if text.strip():
        self._pending_transcript = text
        self._pending_item_id = item_id

def _open_turn_for(self, text: str, item_id: str | None) -> None:
    """Answer an already-transcribed turn (the ``response.create``-after-
    transcript flow): open a floor turn and hand it the transcript at once."""
    if not self.floor.on_turn_committed():
        return
    self._item_id = item_id
    self.floor.on_transcript(text, turn_id=self.floor.turn_id)
    if self.floor.state is FloorState.RESPONDING:
        self.session.append_history("user", text)

def on_generate_response(
    self,
    status_code: int,
    body: bytes,
    *,
    turn_id: int,
    headers: Mapping[str, str] | None = None,
) -> bool:
    """Hand the raw generate response back. ``True`` if the turn advanced.

    Every failure shape :mod:`._turn` names — a ``role_infeasible`` 404
    (with its ``hosted_by`` hint preserved), any other non-2xx, a
    malformed body — becomes a named error event, never a placeholder
    reply and never a second attempt against a different lane. *headers*
    is optional and used for exactly one thing: a retryable status's
    ``Retry-After``, which has nowhere else to travel (see
    :func:`describe_generate_http_failure`).

    A reply carrying ``tool_calls`` is NOT text: it becomes one
    ``response.function_call_arguments.done``, the floor waits, and
    nothing is synthesized.
    """
    try:
        result = parse_turn_response(status_code, body)
    except RoleInfeasibleError as exc:
        message = describe_generate_http_failure(
            describe_role_infeasible(exc),
            status_code=status_code,
            retry_after=retry_after_from_headers(headers),
        )
        return self.fail_generate(message, turn_id=turn_id)
    except TurnRequestError as exc:
        message = describe_generate_http_failure(
            str(exc),
            status_code=status_code,
            retry_after=retry_after_from_headers(headers),
            hosted_by=getattr(exc, "hosted_by", None),
        )
        return self.fail_generate(message, turn_id=turn_id)
    if isinstance(result, ToolCallResult):
        return self._request_tool_call(result, turn_id=turn_id)
    return self.floor.on_reply_text(result, turn_id=turn_id)

def fail_generate(self, message: str, *, turn_id: int, timed_out: bool = False) -> bool:
    """The generate call failed by name (unreachable, non-2xx, timed out)."""
    reason = FailureReason.GENERATE_TIMEOUT if timed_out else FailureReason.GENERATE_FAILED
    return self.floor.fail_stage(reason, message, turn_id=turn_id)

def on_generate_stream_end(self, result: str | ToolCallResult, *, turn_id: int) -> bool:
    """The stream finished. ``True`` if the turn advanced.

    A TEXT result flushes the chunker's remainder as the FINAL segment,
    emits the single ``response.text.done`` with the full reply, and
    records that full text as what history will carry once the reply is
    delivered.

    A TOOL CALL discards every segment already queued from a text prefix
    — the model abandoned that text, so it must not be spoken — and then
    takes exactly the non-streaming tool path.
    """
    if turn_id != self._stream_turn_id or turn_id != self.floor.turn_id:
        return False
    if isinstance(result, ToolCallResult):
        return self._abandon_stream_for_tool_call(result, turn_id=turn_id)
    tail = self._chunker.flush()
    for sentence in tail[:-1]:
        self.floor.on_reply_segment(sentence, final=False, turn_id=turn_id)
    self._reply_text = result
    if result.strip():
        self._push(self.session.complete_response_text(result))
    return self.floor.on_reply_segment(tail[-1] if tail else "", final=True, turn_id=turn_id)

def _abandon_stream_for_tool_call(self, result: ToolCallResult, *, turn_id: int) -> bool:
    """Drop a spoken-text prefix and surface the tool call instead."""
    self._pending_segments.clear()
    self._reply_text = ""
    self.floor.discard_reply_segments(turn_id=turn_id)
    return self._request_tool_call(result, turn_id=turn_id)

@property
def pending_segments(self) -> int:
    """How many segments are waiting to be synthesized (observation/tests)."""
    return len(self._pending_segments)

def fail_tts(self, message: str, *, turn_id: int, timed_out: bool = False) -> bool:
    """The TTS call failed by name."""
    reason = FailureReason.TTS_TIMEOUT if timed_out else FailureReason.TTS_FAILED
    return self.floor.fail_stage(reason, message, turn_id=turn_id)

def _failure_event(self, event: ResponseFailed) -> ErrorEvent:
    message = describe_failure(event)
    if event.reason is FailureReason.TRANSCRIBE_FAILED:
        # The SAME emitter the ears-only path uses, so an STT forward
        # failure looks identical to a client whether or not the session
        # went on to answer the turn (it also keeps the item_id on the
        # event, which fail_response has no way to set).
        return self.session.fail_transcription(message)
    return self.session.fail_response(FAILURE_ERROR_CODES[event.reason], message)

@dataclass(frozen=True)
class ResponseStarted:
    """The machine took the floor to answer: generate is in flight."""

    at_ms: int
    turn_id: int

@dataclass(frozen=True)
class ReplyText:
    """The generated reply text, before a single byte of it has been spoken."""

    at_ms: int
    turn_id: int
    text: str

@property
def turn_id(self) -> int:
    """Advances on every turn — pair it with the completion inputs to
    keep a stale answer off a later turn."""
    return self._turn_id

@property
def synthesizing(self) -> bool:
    """Speaking, but the CURRENT segment's synthesis has not returned yet."""
    return self._state is FloorState.SPEAKING and not self._deliverable

@property
def delivering(self) -> bool:
    """Speaking, with the current segment's audio in hand and chunks going out."""
    return self._state is FloorState.SPEAKING and self._deliverable

@property
def segment_count(self) -> int:
    """How many reply segments this turn has queued (observation/tests)."""
    return len(self._segments)

@property
def _deliverable(self) -> bool:
    """Is there audio ready to send right now, in segment order?"""
    return any(
        segment.audio and not segment.drained
        for segment in self._segments[self._current : self._current + 1]
    )

@property
def armed_stage(self) -> Stage | None:
    """The stage whose deadline is currently armed, if any."""
    return self._armed_stage

@property
def deadline_ms(self) -> int | None:
    """When :meth:`tick` will abandon the current stage (``None`` = unarmed)."""
    return self._deadline_ms

@property
def delivered_bytes(self) -> int:
    """Bytes actually sent, across every segment of this reply."""
    return sum(segment.offset for segment in self._segments)

@property
def pending_audio_bytes(self) -> int:
    """Bytes synthesized but not yet sent, across every segment."""
    return sum(segment.total - segment.offset for segment in self._segments)

def _segment(self, index: int) -> _Segment | None:
    if 0 <= index < len(self._segments):
        return self._segments[index]
    return None

def _accepts_failure(self, stage: Stage) -> bool:
    if self._armed_stage is stage:
        return True
    # See fail_stage's docstring: a streamed reply speaks and generates at
    # the same time, and only one stage can hold the deadline.
    return stage is Stage.TTS and self._state is FloorState.SPEAKING

def _accepts(self, expected: FloorState, turn_id: int | None) -> bool:
    if self._state is not expected:
        return False
    return turn_id is None or turn_id == self._turn_id

def resampled_frame_count(
    num_samples: int, input_rate: int, target_rate: int = VAD_SAMPLE_RATE
) -> int:
    """The output sample count ``scipy.signal.resample`` would produce.

    Mirrors scipy's own sizing convention for ``resample(x, num)``:
    ``num = round(len(x) * target_rate / input_rate)``. Pure arithmetic —
    lets app.py size its call site (and lets tests assert the math) without
    importing scipy.
    """
    if input_rate <= 0:
        raise ValueError(f"input_rate must be positive, got {input_rate}")
    return round(num_samples * target_rate / input_rate)

def chunk_peak_pct(chunk: bytes) -> float:
    """The largest absolute PCM16 sample in *chunk*, as a % of full scale."""
    samples = array("h")
    samples.frombytes(chunk[: len(chunk) - (len(chunk) % BYTES_PER_SAMPLE)])
    if not samples:
        return 0.0
    return min(100.0, max(max(samples), -min(samples)) / 32768 * 100)

@property
def speaking(self) -> bool:
    """Whether a turn is currently in progress (for callers/tests)."""
    return self._speaking

def flush(self, reason: str = "closed") -> Event | None:
    """Force-commit an in-progress turn (e.g., on session teardown).

    Returns the resulting :class:`SpeechStopped` (carrying ``reason``)
    if a turn was in progress, else ``None`` when idle. Any buffered
    partial-chunk bytes (fewer than :data:`CHUNK_BYTES`) are discarded —
    they were never handed to ``vad_probability`` and never will be.
    """
    if not self._speaking:
        return None
    return self._commit(reason)

def _process_chunk(self, chunk: bytes) -> Event | None:
    self._stream_ms += VAD_CHUNK_MS
    probability = self._vad_probability(chunk)
    is_speech = probability >= self.vad_threshold
    if self.min_level_pct:
        self._recent_peaks.append(chunk_peak_pct(chunk))
        is_speech = is_speech and max(self._recent_peaks) >= self.min_level_pct

    if not self._speaking:
        if is_speech:
            turn_chunks = list(self._preroll) + [chunk]
            self._preroll.clear()
            self._turn_chunks = turn_chunks
            self._turn_ms = len(turn_chunks) * VAD_CHUNK_MS
            self._speaking = True
            self._silence_run_ms = 0
            return SpeechStarted(at_ms=self._stream_ms, audio=b"".join(turn_chunks))
        self._preroll.append(chunk)
        return None

    self._turn_chunks.append(chunk)
    self._turn_ms += VAD_CHUNK_MS
    resumed = False
    if is_speech:
        self._silence_run_ms = 0
        resumed, self._paused = self._paused, False
    else:
        self._silence_run_ms += VAD_CHUNK_MS

    if self._silence_run_ms >= self.vad_silence_ms:
        return self._commit("silence")
    if self._turn_ms >= self.max_turn_ms:
        return self._commit("max_turn")
    if resumed:
        return SpeechResumed(at_ms=self._stream_ms)
    if (
        self.eager_silence_ms is not None
        and not self._paused
        and self._silence_run_ms >= self.eager_silence_ms
    ):
        self._paused = True
        return SpeechPaused(at_ms=self._stream_ms, audio=b"".join(self._turn_chunks))
    return None

@property
def released(self) -> int:
    """How many sentences this reply has released so far."""
    return self._released

@property
def pending(self) -> str:
    """The text buffered but not yet released (observation/tests)."""
    return self._buf

def feed(self, text_delta: str) -> list[str]:
    """Consume one generate delta; return the sentences it COMPLETED."""
    if text_delta:
        self._buf += text_delta
    return self._drain()

def _boundary_end(self, buf: str, index: int, char: str, eager: bool) -> int | None:
    """The cut index just past a boundary at *index*, or ``None``.

    A newline is a boundary on its own (and is consumed rather than
    spoken). Every other terminator needs a following whitespace
    character to be CONFIRMED — the next delta could still extend it.
    """
    if char == "\n":
        return index  # the newline itself is dropped by the caller's lstrip
    if char not in _TERMINATORS and not (eager and char in _EAGER_TERMINATORS):
        return None
    if index + 1 >= len(buf) or not buf[index + 1].isspace():
        return None
    if index and buf[index - 1] in _ABBREVIATION_MARKS:
        return None  # an abbreviation's own mark, not the end of a thought
    if eager and char in _EAGER_TERMINATORS:
        if _base_char_length(buf[: index + 1]) < self.eager_first_min_chars:
            return None
    return index + 1

def _split_long(self, text: str) -> list[str]:
    """Size one released piece to the cap, using the TTS splitter."""
    if _base_char_length(text) <= self.max_sentence_chars:
        return [text]
    return [piece for piece in _split_for_tts(text, self.max_sentence_chars) if piece]

def redact_for_log(data: Mapping[str, object]) -> dict[str, object]:
    """Shallow-copy *data*, masking any value whose key name looks credential-shaped.

    Session config payloads originate with an untrusted client and may carry
    unrelated junk fields; this is the one approved way to log one (or any
    client-supplied mapping) so an API key/token/secret-shaped field can never
    reach a log line verbatim.
    """
    return {
        key: (REDACTED_MARKER if _CREDENTIAL_KEY_RE.search(str(key)) else value)
        for key, value in data.items()
    }

def as_dict(self) -> dict[str, int]:
    """The JSON-able mapping, in pipeline order, omitting absent stages."""
    values = vars(self)
    return {key: values[key] for key in STAGE_TIMING_KEYS if values[key] is not None}

def __bool__(self) -> bool:
    """False when no stage was measured — so an all-absent timings object
    serializes away entirely rather than as an empty mapping."""
    return bool(self.as_dict())

def event_to_dict(event: Event) -> dict[str, object]:
    """Flatten any schema event into a plain JSON-able dict.

    Enum fields (``type``, ``code``, and any inside a nested ``config``) are
    ``str``-subclassed, so :func:`json.dumps` serializes them by their
    ``.value`` without further help.

    Two fields are conditional rather than always-emitted, and for the same
    reason: an unset additive field must not change the wire. ``config``'s
    additive keys are handled by :func:`_config_to_dict`, and an absent or
    all-absent ``timings`` drops out of ``response.done`` entirely.
    """
    out: dict[str, object] = {}
    for key, value in vars(event).items():
        if key == "config" and isinstance(value, SessionConfig):
            out[key] = _config_to_dict(value)
        elif key == "timings":
            if isinstance(value, StageTimings):
                if value:
                    out[key] = value.as_dict()
            elif value:
                out[key] = dict(value)
        else:
            out[key] = value
    out["type"] = event.type
    return out

def to_error_event(self, session_id: str) -> ErrorEvent:
    return ErrorEvent(
        session_id=session_id,
        event_id=gen_event_id(),
        timestamp_ms=timestamp_ms(),
        code=self.code,
        message=str(self),
    )

def _validate_tool(index: int, raw: object, seen: set[str]) -> dict[str, object]:
    """One entry of :func:`parse_tools`, validated and copied.

    *seen* is the running set of names already declared, added to here — a
    duplicate makes a returned ``call_id`` ambiguous about which tool was
    meant, so it is rejected rather than deduplicated.
    """
    if not isinstance(raw, Mapping):
        _reject(f"tools[{index}] must be an object, got {raw!r}")
    tool_type = raw.get("type", _FUNCTION_TOOL_TYPE)
    if tool_type != _FUNCTION_TOOL_TYPE:
        _reject(f"tools[{index}] has unsupported type {tool_type!r}; only 'function' is")
    name = raw.get("name")
    if not isinstance(name, str) or not name:
        _reject(f"tools[{index}] requires a non-empty string 'name', got {name!r}")
    if name in seen:
        _reject(f"tools[{index}] repeats the tool name {name!r}")
    seen.add(name)
    description = raw.get("description")
    if description is not None and not isinstance(description, str):
        _reject(f"tools[{index}] 'description' must be a string, got {description!r}")
    parameters = raw.get("parameters")
    if parameters is not None and not isinstance(parameters, Mapping):
        _reject(f"tools[{index}] 'parameters' must be a JSON Schema object, got {parameters!r}")
    return dict(raw)

def parse_tool_choice(value: object) -> str | dict[str, object]:
    """Validate a ``tool_choice``, returning it in Realtime's own shape.

    Either one of :data:`_TOOL_CHOICE_KEYWORDS` (``"auto"``/``"none"``/
    ``"required"``) or the FLAT forced-tool object ``{"type": "function",
    "name": ...}``. Translation to chat-completions' nested form is
    :func:`realtime_tool_choice_to_chat_completions`'s job, not this one's —
    parsing keeps the client's vocabulary, so the ``session.updated`` echo
    can quote it back unchanged.
    """
    if not isinstance(value, (str, Mapping)):
        _reject(f"tool_choice must be a keyword or a function object, got {value!r}")
    if isinstance(value, str):
        if value not in _TOOL_CHOICE_KEYWORDS:
            _reject(
                f"unsupported tool_choice {value!r}; accepted keywords are "
                f"{_TOOL_CHOICE_KEYWORDS}, or a "
                "{'type': 'function', 'name': ...} object"
            )
        return value
    if value.get("type") != _FUNCTION_TOOL_TYPE:
        _reject(f"tool_choice object must have type 'function', got {value.get('type')!r}")
    name = value.get("name")
    if not isinstance(name, str) or not name:
        _reject(f"tool_choice object requires a non-empty string 'name', got {name!r}")
    return dict(value)

def get_history(self) -> list[dict[str, str]]:
    """A defensive copy of this session's conversation history so far.

    Lives only on this :class:`Session` object — no disk, no module-level
    state — and is empty again after :meth:`teardown`."""
    return list(self._history)

def _as_int(env: Mapping[str, str], key: str, default: int) -> int:
    try:
        return int(env.get(key) or default)
    except (TypeError, ValueError):
        return int(default)

def _as_float(env: Mapping[str, str], key: str, default: float) -> float:
    try:
        return float(env.get(key) or default)
    except (TypeError, ValueError):
        return float(default)

def can_adopt(speculative: TurnRequest | None, real: TurnRequest | None) -> bool:
    """Whether the real turn may reuse the speculative generate stream."""
    if speculative is None or real is None:
        return False
    return speculative.url == real.url and speculative.body == real.body

async def __aiter__(self) -> AsyncIterator[str]:
    index = 0
    while True:
        while index < len(self._lines):
            yield self._lines[index]
            index += 1
        if self._closed:
            if self._error is not None:
                raise self._error
            return
        self._changed.clear()
        if index < len(self._lines) or self._closed:
            continue
        await self._changed.wait()

def cancel_pending(self) -> None:
    for slot in self._slots.values():
        if not slot.done():
            slot.cancel()

def __init__(self, clock: Callable[[], int] = timestamp_ms) -> None:
    self._clock = clock
    self._totals: dict[str, int] = {}
    self._running: dict[str, int] = {}
    self._first_delta_marked = False

def mark_first_delta(self) -> None:
    """Stop ``first_delta`` at the FIRST audio chunk; later calls do nothing."""
    if self._first_delta_marked:
        return
    self._first_delta_marked = True
    self.stop(FIRST_DELTA_STAGE)

@staticmethod
def _check(stage: str) -> None:
    if stage not in STAGE_TIMING_KEYS:
        raise ValueError(f"unknown timing stage {stage!r}; expected one of {STAGE_TIMING_KEYS}")

def _base_char_length(text: str) -> int:
    """Character count excluding Hebrew niqqud/cantillation combining marks.

    Equals ``len(text)`` whenever *text* has no such marks — which is every
    English string, so this never changes ``language="en"`` behavior.
    """
    return sum(1 for ch in text if not _is_niqqud_mark(ch))

def _raw_index_for_base_chars(text: str, max_base_chars: int) -> int:
    """The raw index ``i`` such that ``text[:i]`` holds at most
    *max_base_chars* base (non-niqqud) characters — the base-char-aware
    counterpart of ``text[:max_base_chars]``.

    Returns ``len(text)`` when the whole string fits within the budget.
    """
    if max_base_chars <= 0:
        return 0
    count = 0
    for idx, ch in enumerate(text):
        if not _is_niqqud_mark(ch):
            count += 1
            if count > max_base_chars:
                return idx
    return len(text)

def trailing_pause_ms(original_text: str) -> int:
    """Return inter-sentence silence duration (ms) based on ending punctuation.

    Examines the *original* sentence text (before TTS cleaning) so that
    trailing emoji and raw punctuation are still visible.
    """
    s = original_text.rstrip()
    if not s:
        return 200

    # Check multi-char patterns first (longest match wins).
    # Count the trailing run of "!" by string ops rather than a `!{3,}$` regex:
    # on a long run that is not at the end, that pattern backtracks per start
    # position (quadratic — Sonar S8786). rstrip is linear and says the same thing.
    if len(s) - len(s.rstrip("!")) >= 3:
        return 400
    if s.endswith(("?!", "!?")):
        return 350
    if s.endswith("!!"):
        return 350
    if s.endswith(("...", "…")):
        return 400
    if s.endswith("."):
        return 350
    if s.endswith("?"):
        return 350
    if s.endswith("!"):
        return 300

    # Trailing emoji
    if _EMOJI_RE.search(s[-2:]):
        return 250

    return 200

def _min_plausible_duration(clean: str) -> float:
    """Shortest audio duration that is plausible for *clean*.

    Ratio-based: expect at least 15 ms per character (normal speech at 125 %
    runs 60–80 ms/char, so 15 ms is very conservative).
    """
    return max(0.5, len(clean) * 0.015)

def turn_request_headers(api_key: str | None) -> dict[str, str]:
    """Request headers for the turn call. ``api_key`` falsy omits ``Authorization``
    entirely (mirrors ``scripts/realtime-voice-loop.py``'s ``_post_json`` helper).
    """
    headers = {"Content-Type": "application/json"}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    return headers

def __init__(
    self, message: str, *, status_code: int | None = None, hosted_by: str | None = None
) -> None:
    super().__init__(message)
    self.status_code = status_code
    self.hosted_by = hosted_by

def assistant_tool_call_message(result: ToolCallResult) -> dict:
    """The ``{"role": "assistant", ...}`` history entry for a surfaced tool call.

    Chat-completions shape: ``content`` is ``None`` (an assistant turn that
    calls a tool carries no spoken text) and ``tool_calls`` holds exactly the
    one call :class:`ToolCallResult` surfaced, with ``arguments`` passed
    through as the same JSON string — never re-serialized, never
    re-interpreted.
    """
    return {
        "role": "assistant",
        "content": None,
        "tool_calls": [
            {
                "id": result.call_id,
                "type": "function",
                "function": {"name": result.name, "arguments": result.arguments},
            }
        ],
    }

def _load_json_object(body: bytes) -> dict | None:
    try:
        parsed = json.loads(body)
    except (ValueError, TypeError):
        return None
    return parsed if isinstance(parsed, dict) else None

def _extract_reply(data: dict) -> str | ToolCallResult:
    choices = data.get("choices")
    if not isinstance(choices, list) or not choices:
        raise TurnResponseError("generate response missing 'choices'")
    first = choices[0]
    message = first.get("message") if isinstance(first, dict) else None
    if not isinstance(message, dict):
        raise TurnResponseError("generate response missing choices[0].message")
    tool_calls = message.get("tool_calls")
    if tool_calls:
        return _extract_tool_call(tool_calls)
    content = message.get("content")
    if content is None:
        return ""
    if not isinstance(content, str):
        raise TurnResponseError("generate response 'content' is not a string")
    return content.strip()

def _extract_tool_call(tool_calls: object) -> ToolCallResult:
    """The FIRST call of ``message.tool_calls``, as a :class:`ToolCallResult`.

    Raises :class:`TurnResponseError` on any shape defect — a tool call this
    module cannot name (missing ``id``/``function.name``, or a
    non-string ``arguments``) is a malformed backend response, exactly like a
    missing ``choices[0].message`` is; it is never silently dropped in favor
    of falling through to the text path.
    """
    if not isinstance(tool_calls, list) or not tool_calls:
        raise TurnResponseError("generate response 'tool_calls' is not a non-empty list")
    first = tool_calls[0]
    if not isinstance(first, dict):
        raise TurnResponseError("generate response tool_calls[0] is not an object")
    call_id = first.get("id")
    if not isinstance(call_id, str) or not call_id:
        raise TurnResponseError("generate response tool_calls[0] missing 'id'")
    function = first.get("function")
    if not isinstance(function, dict):
        raise TurnResponseError("generate response tool_calls[0] missing 'function'")
    name = function.get("name")
    if not isinstance(name, str) or not name:
        raise TurnResponseError("generate response tool_calls[0].function missing 'name'")
    arguments = function.get("arguments")
    if not isinstance(arguments, str):
        raise TurnResponseError(
            "generate response tool_calls[0].function.arguments is not a string"
        )
    return ToolCallResult(
        call_id=call_id,
        name=name,
        arguments=arguments,
        tool_call_count=len(tool_calls),
        dropped_names=_dropped_call_names(tool_calls[1:]),
    )

def __init__(self) -> None:
    self._text: list[str] = []
    self._calls: dict[int, dict[str, str]] = {}
    self._saw_tool_call = False
    self._done = False

@property
def saw_tool_call(self) -> bool:
    """Has any ``tool_calls`` fragment arrived? Then text stops flowing."""
    return self._saw_tool_call

@property
def done(self) -> bool:
    """Did the backend send its ``[DONE]`` sentinel?"""
    return self._done

@property
def text(self) -> str:
    """Every text delta seen so far, concatenated and unstripped."""
    return "".join(self._text)

def result(self) -> str | ToolCallResult:
    """The finished reply: a tool call if one was seen, else the text."""
    if self._saw_tool_call:
        return self._tool_call_result()
    return self.text.strip()

def _consume_chunk(self, data: dict) -> list[StreamItem]:
    choices = data.get("choices")
    if not isinstance(choices, list) or not choices:
        return []  # a usage-only final chunk carries no choices at all
    first = choices[0]
    delta = first.get("delta") if isinstance(first, dict) else None
    if not isinstance(delta, dict):
        return []
    tool_calls = delta.get("tool_calls")
    if isinstance(tool_calls, list) and tool_calls:
        self._saw_tool_call = True
        for fragment in tool_calls:
            self._merge_tool_fragment(fragment)
    content = delta.get("content")
    if not isinstance(content, str) or not content or self._saw_tool_call:
        return []
    self._text.append(content)
    return [StreamItem(text=content)]

def _tool_call_result(self) -> ToolCallResult:
    """The FIRST call by index, validated exactly like the non-streamed one."""
    if not self._calls:
        raise TurnResponseError("generate stream announced a tool call it never described")
    index, *dropped = sorted(self._calls)
    call = self._calls[index]
    if not call["id"]:
        raise TurnResponseError("generate stream tool call missing 'id'")
    if not call["name"]:
        raise TurnResponseError("generate stream tool call missing 'function.name'")
    return ToolCallResult(
        call_id=call["id"],
        name=call["name"],
        arguments=call["arguments"],
        tool_call_count=len(self._calls),
        dropped_names=tuple(self._calls[i]["name"] or _UNNAMED_CALL for i in dropped),
    )

def get(self) -> T | None:
    if self._built:
        return self._value
    with self._lock:
        if not self._built:
            self._value = self._builder()
            self._built = True
    return self._value

def _is_hebrew_related(ch: str) -> bool:
    """True for any character allowed inside a Hebrew span: a Hebrew letter,
    a niqqud/cantillation mark, geresh/gershayim, or whitespace (so a space
    between two Hebrew words stays attached to its span instead of splitting
    it in two).
    """
    return (
        _is_hebrew_letter(ch) or _is_hebrew_mark(ch) or ch in (_GERESH, _GERSHAYIM) or ch.isspace()
    )

@app.post("/v1/audio/speech")  # pragma: no cover
async def speech(request: Request) -> Response:
    """OpenAI text-to-speech → Chatterbox. Returns a wav/pcm audio body."""
    try:
        body = await request.json()
    except ValueError:
        return _error(400, "request body must be valid JSON")
    try:
        params = parse_speech_request(body)
    except SpeechRequestError as exc:
        return _error(400, str(exc))

    pcm = await synthesize(
        params.input,
        voice=params.voice or settings.default_voice,
        speed=params.speed,
        tts_url=settings.tts_url,
    )
    if not pcm:
        return _error(502, "TTS backend returned no audio")
    data, media_type = pcm_to_container(pcm, params.response_format)
    return Response(content=data, media_type=media_type)

@app.post("/v1/audio/transcriptions")  # pragma: no cover
async def transcriptions(
    file: Annotated[UploadFile, File()],
    language: Annotated[str | None, Form()] = None,
    model: Annotated[str | None, Form()] = None,
) -> Response:
    """OpenAI speech-to-text → forwards the upload to Parakeet (already OpenAI-shaped).

    ``language`` is resolved by the same two-level rule the WebSocket lane
    uses (:func:`~lobes.realtime.audio_facade.build_stt_forward_fields`): the
    caller's own value, else ``REALTIME_LANGUAGE``, else ``en`` — so a Hebrew
    deployment transcribes batch uploads in Hebrew too, and an unconfigured
    one posts byte-for-byte what it always did.
    """
    content = await file.read()
    url = settings.stt_url.rstrip("/") + "/v1/audio/transcriptions"
    try:
        async with httpx.AsyncClient(timeout=60.0) as client:
            resp = await client.post(
                url,
                data=build_stt_forward_fields(language, settings.language),
                files=build_stt_forward_files(
                    content,
                    file.filename or "audio.wav",
                    file.content_type or "audio/wav",
                ),
            )
    except httpx.HTTPError as exc:
        return _error(502, f"STT backend unreachable: {exc}")
    try:
        return JSONResponse(status_code=resp.status_code, content=resp.json())
    except ValueError:
        return _error(502, "STT backend returned a non-JSON response")

def cancel_generate(self) -> None:
    self.cancelled = True
    if self.speculation is not None:
        self.speculation.cancel()
    if self.generate_task is not None:
        self.generate_task.cancel()

def cancel_tts(self) -> None:
    self.cancelled = True
    self.tts_cancel.set()
    if self.tts_task is not None:
        self.tts_task.cancel()

def drop_speculation(self) -> None:
    """Throw the hidden speculation away, without trace."""
    if self.speculation is not None:
        self.speculation.cancel()
        self.speculation = None

def cancel(self) -> None:
    self.tts_cancel.set()
    for task in (self.task, self.synth_task):
        if task is not None and not task.done():
            task.cancel()
    self.audio.cancel_pending()
    if not self.lines.closed:
        self.lines.close(error=asyncio.CancelledError())

async def _drain_segments(  # pragma: no cover
    bridge: ConversationBridge, queue: asyncio.Queue
) -> None:
    """Move every ready segment onto the synth worker's queue, in order."""
    while True:
        pending = bridge.take_pending_segment()
        if pending is None:
            return
        await queue.put(pending)

async def _transcribe_turn(  # pragma: no cover
    bridge: ConversationBridge,
    sender: _Sender,
    audio: bytes,
    clock: StageClock,
    tasks: _SessionTasks,
) -> None:
    spec = tasks.speculation
    if spec is not None:
        # The committed audio is the speculation's snapshot plus trailing
        # non-speech only, so its transcript IS this turn's transcript.
        await spec.transcript_ready.wait()
        if spec.transcript is None:
            tasks.drop_speculation()  # its STT failed: the ordinary path names it
            spec = None
    try:
        if spec is not None:
            text = spec.transcript
        else:
            text = await _forward_turn_to_stt(audio, bridge.session.config.language)
    except _STTForwardError as exc:
        bridge.on_transcription_failed(str(exc))
    else:
        bridge.on_transcript(text)
    clock.stop("stt")
    await sender.flush()

def parse_speech_request(body: object) -> SpeechParams:
    """Validate an OpenAI ``/v1/audio/speech`` JSON body. Raises on bad input.

    ``input`` is required. ``response_format`` defaults to ``wav`` (OpenAI's
    default is mp3, which we cannot encode yet — defaulting to wav keeps naive
    callers working instead of 400ing them). OpenAI ``speed`` is a 0.25–4.0
    multiplier (clamped to that range here); converted to a percentage so
    ``1.0 → 100`` (accepted for API compatibility; Chatterbox ignores it).
    """
    if not isinstance(body, dict):
        raise SpeechRequestError("request body must be a JSON object")
    text = body.get("input")
    if not isinstance(text, str) or not text.strip():
        raise SpeechRequestError("'input' is required and must be a non-empty string")
    voice = body.get("voice")
    if voice is not None and not isinstance(voice, str):
        raise SpeechRequestError("'voice' must be a string")
    fmt = body.get("response_format") or "wav"
    if not isinstance(fmt, str):
        raise SpeechRequestError("'response_format' must be a string")
    fmt = fmt.lower()
    if fmt not in SUPPORTED_FORMATS:
        raise SpeechRequestError(
            f"unsupported response_format {fmt!r}; supported: {', '.join(SUPPORTED_FORMATS)} "
            "(mp3/opus/aac/flac need an encoder — not yet available)"
        )
    raw_speed = body.get("speed")
    speed: int | None = None
    if raw_speed is not None:
        try:
            multiplier = float(raw_speed)
        except (TypeError, ValueError):
            raise SpeechRequestError("'speed' must be a number") from None
        # Clamp to OpenAI's 0.25–4.0 range before converting to a percentage.
        multiplier = max(_OPENAI_SPEED_MIN, min(_OPENAI_SPEED_MAX, multiplier))
        speed = int(round(multiplier * 100))
    return SpeechParams(input=text, voice=voice, response_format=fmt, speed=speed)

def build_stt_forward_fields(
    language: str | None, default: str = DEFAULT_LANGUAGE
) -> dict[str, str]:
    """The multipart FORM fields of one Parakeet ``/v1/audio/transcriptions`` POST.

    Exactly one field, ``language`` — so an unconfigured deployment sends
    ``{"language": "en"}``, byte-for-byte what this route sent before the
    Hebrew work landed. Pure and stdlib-only precisely so that byte-identity
    is a test, not a claim about a route CI cannot import.
    """
    return {"language": resolve_stt_language(language, default)}

def build_stt_forward_files(
    content: bytes,
    filename: str = STT_TURN_FILENAME,
    content_type: str = STT_WAV_CONTENT_TYPE,
) -> dict[str, tuple[str, bytes, str]]:
    """The multipart FILE part of the same POST, in httpx's ``files=`` shape."""
    return {"file": (filename or STT_TURN_FILENAME, content, content_type or STT_WAV_CONTENT_TYPE)}

def aggregate_audio_ready(tts_ready: bool, stt_ready: bool) -> tuple[int, dict]:
    """Aggregate Chatterbox (TTS) + Parakeet (STT) readiness into one
    ``(http_status, body)`` for the realtime bridge's ``/v1/health/ready`` (#89).

    Returns ``(200, {"status": "ready"})`` only when BOTH backends are ready;
    otherwise ``(503, {"status": "not_ready", "not_ready": [...]})`` naming the
    side(s) that are not ready. The gateway probes this aggregate so it advertises
    stt/tts as consumable only when an audio round-trip would actually succeed.
    """
    not_ready = [name for name, ok in (("tts", tts_ready), ("stt", stt_ready)) if not ok]
    if not_ready:
        return 503, {"status": "not_ready", "not_ready": not_ready}
    return 200, {"status": "ready"}

def _as_int(env: Mapping[str, str], key: str, default: int) -> int:
    try:
        return int(env.get(key, "").strip() or default)
    except ValueError:
        return default

def _as_float(env: Mapping[str, str], key: str, default: float) -> float:
    try:
        value = float(env.get(key, "").strip() or default)
    except ValueError:
        return default
    return value if math.isfinite(value) else default

def strip_niqqud(text: str) -> str:
    """Remove vocalization marks so RenikudPlus is the only G2P authority."""
    return "".join(
        ch
        for ch in text
        if ch != _PHONIKUD_BAR
        and not (0x0591 <= ord(ch) <= 0x05C7 and ord(ch) not in _HEBREW_PUNCTUATION)
    )

def resample_ratio(src_rate: int, dst_rate: int) -> tuple[int, int]:
    """``(up, down)`` for a polyphase resample — (80, 147) for 44100 → 24000."""
    if src_rate <= 0 or dst_rate <= 0:
        raise ValueError(f"sample rates must be positive, got {src_rate} -> {dst_rate}")
    g = math.gcd(src_rate, dst_rate)
    return dst_rate // g, src_rate // g

def floats_to_pcm16(samples: Iterable[float]) -> bytes:
    """Clip to [-1, 1] and pack as PCM16 little-endian (symmetric ±32767)."""
    ints = [int(max(-1.0, min(1.0, float(s))) * 32767) for s in samples]
    return struct.pack(f"<{len(ints)}h", *ints)

def readiness_status(model_loaded: bool, warmup_ok: bool) -> tuple[int, dict]:
    if not model_loaded:
        return 503, {"status": "loading"}
    if not warmup_ok:
        return 503, {"status": "warming"}
    return 200, {"status": "ready"}

def has_niqqud(text: str) -> bool:
    """True iff *text* contains at least one Hebrew niqqud/vocalization mark.

    Deliberately excludes the punctuation-like code points inside the
    U+05B0-U+05C7 range (see :data:`_NIQQUD_PUNCTUATION_LIKE`) — a maqaf or
    sof-pasuq alone does not mean the text has been vocalized.
    """
    return any(
        _NIQQUD_LO <= ord(ch) <= _NIQQUD_HI and ord(ch) not in _NIQQUD_PUNCTUATION_LIKE
        for ch in text
    )

def is_runaway(
    text: str,
    duration_s: float,
    seconds_per_base_char: float = _DEFAULT_MAX_SECONDS_PER_BASE_CHAR,
    slack_s: float = _DEFAULT_MAX_DURATION_SLACK_S,
) -> bool:
    """True when *duration_s* exceeds what is plausible for *text*."""
    return duration_s > max_plausible_duration_s(text, seconds_per_base_char, slack_s)

def pcm16_duration_s(pcm: bytes, sample_rate: int) -> float:
    """Duration, in seconds, of raw PCM16 mono *pcm* at *sample_rate*."""
    if sample_rate <= 0:
        return 0.0
    return (len(pcm) // 2) / sample_rate

def _window_rms(pcm: bytes, start_sample: int, end_sample: int) -> float:
    """RMS amplitude of ``pcm``'s samples in ``[start_sample, end_sample)``."""
    n = end_sample - start_sample
    if n <= 0:
        return 0.0
    samples = struct.unpack(f"<{n}h", pcm[start_sample * 2 : end_sample * 2])
    return math.sqrt(sum(s * s for s in samples) / n)

def _as_int(env: Mapping[str, str], key: str, default: int) -> int:
    try:
        return int(env.get(key) or default)
    except (TypeError, ValueError):
        return int(default)

def _as_float(env: Mapping[str, str], key: str, default: float) -> float:
    try:
        return float(env.get(key) or default)
    except (TypeError, ValueError):
        return float(default)

def readiness_status(model_loaded: bool, warmup_ok: bool, cuda_poisoned: bool) -> tuple[int, dict]:
    """Return an ``(http_status, body)`` pair reflecting real TTS readiness.

    Pure function — no torch/fastapi/chatterbox imports — unit-testable
    offline. Unlike ``chatterbox_server.readiness_status``, this ALSO gates
    on a successful warm-up synthesis (criterion 4: "readiness must be
    non-200 until the model is loaded AND one short warm-up synthesis has
    succeeded" — cold model load is ~120s, and a loaded-but-never-synthesized
    model has not actually proven it can serve a request).
    """
    if not model_loaded:
        return 503, {"status": "loading"}
    if cuda_poisoned:
        return 503, {"status": "unavailable", "reason": "cuda_context_poisoned"}
    if not warmup_ok:
        return 503, {"status": "loading", "reason": "warmup_pending"}
    return 200, {"status": "ready"}

def _prepare_text_for_synthesis(text: str) -> str:  # pragma: no cover
    """Apply the diacritization decision table to *text*. See module docstring."""
    stripped = strip_phonikud_invented_marks(text)
    if _ml_settings.language.lower() != "he" or _ml_settings.diacritize == "off":
        return stripped
    if has_niqqud(stripped):
        return stripped
    diacritizer = _get_diacritizer()
    if diacritizer is None:
        log.debug("[Chatterbox-ML] synthesizing WITHOUT niqqud (no diacritizer available)")
        return stripped
    return vocalize_hebrew(stripped, diacritizer)

def _generate_once(mdl, text: str, voice: str) -> bytes:  # pragma: no cover
    kwargs: dict = {
        "exaggeration": 0.5,
        "cfg_weight": 0.5,
        "temperature": _ml_settings.temperature,
    }
    if voice.lower().endswith(".wav"):
        kwargs["audio_prompt_path"] = voice
    wav_tensor = mdl.generate(text, language_id=_ml_settings.language, **kwargs)
    return float_tensor_to_pcm16(wav_tensor)

def readiness_status(model_loaded: bool, cuda_poisoned: bool) -> tuple[int, dict]:
    """Return an ``(http_status, body)`` pair reflecting real TTS readiness.

    Pure function — no torch / fastapi imports — so it is unit-testable in the
    offline CI environment (no GPU, no container deps).
    """
    if not model_loaded:
        return 503, {"status": "loading"}
    if cuda_poisoned:
        return 503, {"status": "unavailable", "reason": "cuda_context_poisoned"}
    return 200, {"status": "ready"}

def _get_semaphore(lane: str) -> asyncio.Semaphore:
    global _tts_semaphores
    if _tts_semaphores is None:
        _tts_semaphores = new_tts_lane_semaphores(settings)
        log.info(
            "[TTS] concurrency gates: batch=%d voice=%d parallel requests",
            settings.tts_concurrency,
            settings.tts_voice_concurrency,
        )
    return _tts_semaphores[normalize_tts_lane(lane)]

def check_lock_buildability(
    lock: DeploymentLock,
    *,
    package: str = PYPI_PACKAGE,
    index_query: IndexQuery | None = None,
) -> BuildabilityResult:
    """:func:`check_buildability` over a captured :class:`~lobes.runtime._lock.DeploymentLock`.

    Convenience wrapper for the natural call site — a ``--from-lock`` restore
    or a dedicated buildability check reads ``lock.lobes_version`` (the
    version :mod:`lobes.runtime._lock` records at capture time) rather than
    threading the raw string through by hand.
    """
    return check_buildability(lock.lobes_version, package=package, index_query=index_query)

def plugin_plan(target: os.PathLike | str) -> tuple[str, bool]:
    """``(dest_name, already_exists)`` for the plugin file — same shape as one
    entry of :func:`scaffold_plan`, so ``lobes init``'s dry-run listing can
    just append it to that function's return value."""
    return (PLUGIN_DEST_NAME, (Path(target) / PLUGIN_DEST_NAME).exists())

def _read_template(template_root, name: str) -> str:
    """Read a packaged template by its (possibly ``fleet/``-prefixed) name.

    ``importlib.resources`` traversables join one path segment per ``/`` call,
    so split the name and chain rather than passing ``"fleet/foo"`` in one go.
    """
    node = template_root
    for part in name.split("/"):
        node = node / part
    return node.read_text(encoding="utf-8")

def scaffold_plan(
    target: Path, templates: dict[str, str] = SINGLE_TEMPLATES
) -> list[tuple[str, bool]]:
    """Return ``(dest_name, already_exists)`` for each file ``init`` would write."""
    return [(dest, (target / dest).exists()) for dest in templates.values()]

def _harden_env_perms(dest: Path, dest_name: str) -> None:
    """Keep ``.env`` owner-only — it may hold ``HF_TOKEN`` / ``GATEWAY_API_KEY``.

    Applied on the MERGE path too, not just on a fresh write: overwriting used
    to re-tighten permissions as a side effect, and merge-only must not quietly
    drop that. Best-effort — chmod can fail on some filesystems (e.g. Windows).
    """
    if dest_name != ENV_FILE:
        return
    try:
        dest.chmod(0o600)
    except OSError:
        pass

def _split_env_blocks(text: str) -> list[list[str]]:
    """Split a template body into blank-line-separated line groups.

    Each group is a "block": a run of consecutive non-blank lines — typically
    a comment paragraph documenting one (or a few) ``KEY=VALUE`` lines that
    immediately follow it. Blank lines are the separators and are dropped;
    they are re-inserted by the caller when re-joining kept blocks.
    """
    blocks: list[list[str]] = []
    current: list[str] = []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            blocks.append(current)
            current = []
    if current:
        blocks.append(current)
    return blocks

def audio_he_overlay_present(deploy_dir: os.PathLike | str) -> bool:
    """True when the Hebrew overlay (``docker-compose.audio-he.yml``) is scaffolded.

    Mirrors :func:`audio_overlay_present`. Present only for an
    ``--audio-lang he`` deployment; an English one never carries the file.
    """
    return (Path(deploy_dir) / AUDIO_HE_OVERLAY).is_file()

def local_override_present(deploy_dir: os.PathLike | str) -> bool:
    """True when an operator-authored ``docker-compose.override.yml`` sits in the deploy dir.

    Never scaffolded by lobes — it is purely the operator's file, honoured because
    ``docker compose`` honours it. See :data:`LOCAL_OVERRIDE`.
    """
    return (Path(deploy_dir) / LOCAL_OVERRIDE).is_file()

def gpu_overlay_present(deploy_dir: os.PathLike | str) -> bool:
    """True when the GPU-access override (``docker-compose.gpu.yml``) is scaffolded.

    Present only for a deployment whose resolved card profile declares
    ``gpu_access = "runtime"`` (a csv-mode board — see :data:`GPU_OVERLAY`);
    every other card writes none. Mirrors :func:`shape_overlay_present`. The
    audio half (:data:`GPU_AUDIO_OVERLAY`) is written and removed in the same
    breath by ``lobes init``, so this one file answers for both.
    """
    return (Path(deploy_dir) / GPU_OVERLAY).is_file()

def shape_dropped_containers(deploy_dir: os.PathLike | str) -> tuple[str, ...]:
    """Container names the shape override disables, read from ``docker-compose.shape.yml``.

    The override file itself is the single source of truth: ``lobes init`` GENERATES
    it listing exactly the core services it parks in the inert ``shape-dropped``
    compose profile. Only the PARKED blocks count — see
    :func:`shape_parked_service_keys` for why the file's other blocks (start-order
    reversals, a pre-#222 ``gateway`` reset, a published ComfyUI UI port) must not
    be read as drops. Empty tuple when no override is scaffolded.
    """
    path = Path(deploy_dir) / SHAPE_OVERLAY
    if not path.is_file():
        return ()
    keys = shape_parked_service_keys(path.read_text(encoding="utf-8"))
    return tuple(
        container for service, container in _CORE_SERVICE_CONTAINER.items() if service in keys
    )

def _run(argv: list[str], *, cwd: str | None = None, timeout: int | None = None):
    """Run a command that MUST exist (docker); raise ENV_ERROR if it doesn't."""
    try:
        return subprocess.run(  # fixed argv, no shell
            argv, cwd=cwd, capture_output=True, text=True, check=False, timeout=timeout
        )
    except OSError as exc:
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"could not run {argv[0]}: {exc}",
            remediation="ensure docker + the NVIDIA Container Toolkit are installed and on PATH",
        ) from exc

def _probe(argv: list[str], *, timeout: int = 10):
    """Run a best-effort command; return the result or ``None`` if it can't run."""
    try:
        return subprocess.run(  # fixed argv, no shell
            argv, capture_output=True, text=True, check=False, timeout=timeout
        )
    except (OSError, subprocess.TimeoutExpired):
        return None

def compose_up_build(deploy_dir: os.PathLike | str):
    """``docker compose up -d --build`` — used by the fleet, whose gateway service
    is built from a local ``Dockerfile.gateway`` (``--build`` picks up a new image
    on a re-run; first run builds either way). When the ``--audio`` overlay is
    scaffolded, the audio services (built from ``Dockerfile.realtime`` /
    ``Dockerfile.parakeet``) are layered in via ``-f docker-compose.audio.yml``."""
    return _run(
        ["docker", "compose"] + _compose_files(deploy_dir) + ["up", "-d", "--build"],
        cwd=str(deploy_dir),
    )

def container_status(container: str = CONTAINER) -> str:
    """Bare container lifecycle status (``running`` / ``exited`` / ``missing``)."""
    r = _probe(["docker", "inspect", "-f", "{{.State.Status}}", container])
    if r is None or r.returncode != 0:
        return "missing"
    return r.stdout.strip() or "missing"

def inspect_state(container: str = CONTAINER) -> str:
    """Status with health, e.g. ``running (healthy)`` — or ``not created``."""
    r = _probe(
        ["docker", "inspect", "-f", "{{.State.Status}} ({{.State.Health.Status}})", container]
    )
    if r is None or r.returncode != 0:
        return "not created"
    return r.stdout.strip() or "not created"

def container_image(container: str = CONTAINER) -> str:
    r = _probe(["docker", "inspect", container, "--format", "{{.Config.Image}}"])
    if r is None or r.returncode != 0:
        return "?"
    return r.stdout.strip() or "?"

def container_logs(container: str = CONTAINER, tail: int = 30) -> str:
    r = _probe(["docker", "logs", "--tail", str(tail), container])
    if r is None:
        return ""
    return (r.stdout or "") + (r.stderr or "")

def gpu_engine_mem() -> str:
    """Best-effort GPU memory used by the vLLM EngineCore process (via nvidia-smi)."""
    r = _probe(
        ["nvidia-smi", "--query-compute-apps=process_name,used_memory", "--format=csv,noheader"]
    )
    if r is None or r.returncode != 0:
        return "?"
    for line in r.stdout.splitlines():
        low = line.lower()
        if "enginecore" in low or "vllm" in low:
            parts = line.split(",")
            if len(parts) >= 2:
                return parts[1].strip()
    return "?"

def _read_total_memory_gb(path: Path = _MEMINFO_PATH) -> float | None:
    """Total system memory in GB from ``/proc/meminfo`` ``MemTotal`` — never nvidia-smi.

    Unified-memory boards report ``[N/A]`` for GPU memory.used/memory.total, so
    ``/proc/meminfo`` is the only honest total on this hardware class.
    """
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return None
    for line in text.splitlines():
        parts = line.split()
        if parts and parts[0] == "MemTotal:" and len(parts) >= 2:
            try:
                total_kb = float(parts[1])
            except ValueError:
                return None
            return round(total_kb / (1024 * 1024), 1)
    return None

def _read_device_tree_model(path: Path = _DEVICE_TREE_MODEL_PATH) -> str | None:
    """``/proc/device-tree/model`` (Jetson boards only; absent elsewhere, NUL-terminated)."""
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return None
    model = text.strip("\x00").strip()
    return model or None

def _read_hostname() -> str | None:
    try:
        return socket.gethostname()
    except OSError:
        return None

def read_env(env_path: os.PathLike | str, key: str, default: str | None = None) -> str | None:
    """Return the value of ``key`` in the ``.env`` file.

    Falls back to ``default`` when the file is unreadable, the key is absent, or
    the value is empty (``KEY=``) — matching the shell's ``${v:-default}``.
    """
    try:
        text = Path(env_path).read_text(encoding="utf-8")
    except OSError:
        return default
    prefix = key + "="
    for line in text.splitlines():
        if line.startswith(prefix):
            value = line[len(prefix) :]
            return value if value else default
    return default

def read_env_file(env_path: os.PathLike | str) -> dict[str, str]:
    """Parse a whole ``.env`` file into a plain ``dict`` (``{}`` if unreadable).

    Same ``KEY=VALUE`` line format as :func:`read_env`/:func:`set_env` — no
    quoting, no variable expansion; blank lines and ``#`` comments are skipped.
    Lets a host-side, read-only caller (``lobes capabilities`` / ``lobes
    endpoint``, issue #81 t5) build an env ``Mapping`` for
    :func:`lobes.roles.role_registry_from_env` from a deployment's ``.env``
    without hand-listing every key the registry might read — the CLI process
    never has the deployment's env vars in its own ``os.environ`` (those are
    injected into the *containers* by ``docker compose``, not the host shell).
    """
    try:
        text = Path(env_path).read_text(encoding="utf-8")
    except OSError:
        return {}
    out: dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.split("#", 1)[0].strip()
        if not stripped or "=" not in stripped:
            continue
        key, _, value = stripped.partition("=")
        key = key.strip()
        if key:
            out[key] = value.strip()
    return out

def parse_port(value: object, source: str = "VLLM_PORT") -> int:
    """Parse a port to ``int``, turning a bad value into a structured error.

    Without this a non-numeric ``VLLM_PORT`` in ``.env`` (or a stray ``--port``)
    surfaces as the dispatcher's generic ``unexpected: ValueError``.
    """
    try:
        return int(value)
    except (TypeError, ValueError) as exc:
        raise ModelGearError(
            code=EXIT_ENV_ERROR,
            message=f"invalid port {value!r} from {source}",
            remediation="set a numeric VLLM_PORT in .env, or pass --port N",
        ) from exc

@lru_cache(maxsize=1)
def lock_keys() -> frozenset[str]:
    """The allowlist: every ``.env`` key a committed lock may carry.

    Derived from three sources, none of them a hand-written list of names:

    1. the role-knob grammar — :data:`lobes.profiles.render.ROLE_ENV_PREFIX`
       crossed with the knob suffixes
       (:data:`lobes.profiles.render._KNOB_ENV_SUFFIX`) plus ``MODEL`` /
       ``SERVED_NAME`` / ``FEASIBLE``;
    2. every card-level ``host_env`` key declared by a packaged built-in
       profile (``LOBES_IOWAIT_DEGRADED_THRESHOLD`` on ``orin`` today);
    3. the activation keys an alternative-engine or opt-in lane renders
       (:data:`lobes.profiles.render.LLAMA_CPP_ACTIVATION_ENV`,
       :data:`lobes.profiles.shape_render.OPT_IN_ACTIVATION_ENV`,
       :data:`lobes.profiles.shape_render.OPT_IN_CORE_ACTIVATION_ENV`).

    :func:`is_excluded` then narrows the result — see
    :data:`EXCLUDED_RENDERED_KEYS` / :data:`EXCLUDED_KEY_SUFFIXES`.

    Adding a role, a knob or a ``host_env`` declaration widens this set
    automatically. Adding a *secret* does not: a credential is not a
    :class:`~lobes.profiles.schema.RoleProfile` field, so it can never appear
    here without someone deliberately declaring it as a rendered knob.
    """
    suffixes = set(_KNOB_ENV_SUFFIX.values()) | set(_NON_KNOB_SUFFIXES)
    keys = {f"{prefix}_{suffix}" for prefix in ROLE_ENV_PREFIX.values() for suffix in suffixes}
    for name in builtin_names():
        keys |= set(resolve_profile(name).host_env)
    for table in (
        LLAMA_CPP_ACTIVATION_ENV,
        OPT_IN_ACTIVATION_ENV,
        OPT_IN_CORE_ACTIVATION_ENV,
    ):
        for activation in table.values():
            keys |= set(activation)
    return frozenset(key for key in keys if not is_excluded(key))

def allowlist_env(env: Mapping[str, str]) -> dict[str, str]:
    """*env* filtered down to :func:`lock_keys`, sorted.

    Closed over its input by construction: a key the renderer does not produce
    changes nothing about the result, whatever it is called.
    """
    return {key: env[key] for key in sorted(env) if key in lock_keys()}

def _toml_key(key: str) -> str:
    """A bare key where TOML allows one, a quoted key otherwise (``docker-compose.yml``)."""
    if key and set(key) <= _BARE_KEY_CHARS:
        return key
    return _toml_string(key)

def lock_toml(lock: DeploymentLock) -> str:
    """Render *lock* to the committed ``deployment.lock.toml`` text.

    Deterministic: both tables are emitted in sorted key order, so re-capturing
    an unchanged deployment produces a byte-identical file and any diff is a
    real change.
    """
    _assert_secret_free(lock)
    lines = [_HEADER, f"schema_version = {SCHEMA_VERSION}\n", "\n[variation]\n"]
    lines.append(f"id = {_toml_string(lock.variation)}\n")
    for field, value in (
        ("profile", lock.profile),
        ("shape", lock.shape),
        ("lobes_version", lock.lobes_version),
        ("evidence", lock.evidence),
    ):
        if value is not None:
            lines.append(f"{field} = {_toml_string(value)}\n")
    lines.append("\n[env]\n")
    for key in sorted(lock.env):
        lines.append(f"{_toml_key(key)} = {_toml_string(lock.env[key])}\n")
    if lock.files:
        lines.append("\n[files]\n")
        for name in sorted(lock.files):
            lines.append(f"{_toml_key(name)} = {_toml_string(lock.files[name])}\n")
    return "".join(lines)

def _lock_table(raw: Mapping[str, object], name: str, path: os.PathLike | str) -> Mapping:
    """``raw[name]`` as a table, or a controlled error."""
    value = raw.get(name, {})
    if not isinstance(value, dict):
        raise _malformed(path, f"[{name}] must be a table, not {type(value).__name__}")
    return value

def _lock_str_table(
    raw: Mapping[str, object], name: str, path: os.PathLike | str
) -> dict[str, str]:
    """``raw[name]`` as a table whose every value is a string."""
    table = _lock_table(raw, name, path)
    for key, value in table.items():
        if not isinstance(value, str):
            raise _malformed(
                path, f"[{name}] key {key!r} must be a string, not {type(value).__name__}"
            )
    return dict(table)

def _lock_str(
    table: Mapping, field: str, path: os.PathLike | str, *, default: str | None = None
) -> str | None:
    """``table[field]`` as a string (or *default* when absent)."""
    value = table.get(field, default)
    if value is not None and not isinstance(value, str):
        raise _malformed(path, f"[variation] {field} must be a string, not {type(value).__name__}")
    return value

def infer_parser(model: str) -> str | None:
    """Return the tool-call parser for ``model``, or ``None`` if unknown.

    ``None`` means "I can't tell" — the caller should leave the existing
    ``VLLM_TOOL_CALL_PARSER`` in place and rely on an explicit override.
    """
    name = (model or "").lower()
    for markers, parser in _RULES:
        if any(marker in name for marker in markers):
            return parser
    return None

def resolve_hostname(explicit: str | None, deploy_dir: os.PathLike | str) -> str:
    """Public hostname: ``--hostname`` → ``$CULTURE_VLLM_PUBLIC_HOSTNAME`` → ``.cf-tunnel.env``.

    Never committed — raises a USER_ERROR (with a hint) when none of the three is set,
    and validates the resolved value against the safe charset.
    """
    if explicit:
        return _require_safe(explicit, what=_HOSTNAME_LABEL)
    env_val = os.environ.get(HOSTNAME_KEY)
    if env_val:
        return _require_safe(env_val, what=_HOSTNAME_LABEL)
    file_val = _env.read_env(tunnel_env_path(deploy_dir), HOSTNAME_KEY)
    if file_val:
        return _require_safe(file_val, what=_HOSTNAME_LABEL)
    raise ModelGearError(
        code=EXIT_USER_ERROR,
        message="no public hostname set",
        remediation=(
            f"pass --hostname, export ${HOSTNAME_KEY}, or set {HOSTNAME_KEY} in "
            f"{tunnel_env_path(deploy_dir)} (copy the scaffolded cf-tunnel.env.example)"
        ),
    )

def resolve_token(deploy_dir: os.PathLike | str) -> tuple[str, str]:
    """Token source from ``.cf-tunnel.env`` as ``(mode, value)``.

    ``("shushu", name)`` (preferred, the sealed-secret name) if set, else
    ``("plain", token)``. The sealed-secret *name* reaches the argv, so it is
    validated; the plaintext token goes via the environment and is not. Raises a
    USER_ERROR when neither key is set.
    """
    env_path = tunnel_env_path(deploy_dir)
    shushu_name = _env.read_env(env_path, TOKEN_SHUSHU_KEY)
    if shushu_name:
        return ("shushu", _require_safe(shushu_name, what=_SHUSHU_LABEL))
    plain = _env.read_env(env_path, TOKEN_PLAIN_KEY)
    if plain:
        return ("plain", plain)
    raise ModelGearError(
        code=EXIT_USER_ERROR,
        message="no cloudflared run-token configured",
        remediation=(
            f"set {TOKEN_SHUSHU_KEY} (preferred) or {TOKEN_PLAIN_KEY} in {env_path}; "
            "provision it with 'cultureflare remote-login setup --no-access --shushu --apply'"
        ),
    )

def token_env(mode: str, value: str) -> dict[str, str]:
    """Extra child environment for the launcher: the plaintext token, or nothing.

    ``plain`` mode sets ``TUNNEL_TOKEN`` so cloudflared authenticates without the
    token ever touching argv. ``shushu`` mode injects it itself, so this is empty.
    """
    if mode == "plain":
        return {TOKEN_ENV_VAR: value}
    return {}

def read_pidfile(deploy_dir: os.PathLike | str) -> dict | None:
    """Parse the recorded ``{pid, pgid, argv0}``, tolerating a legacy bare-integer file."""
    try:
        text = pid_path(deploy_dir).read_text(encoding="utf-8").strip()
    except OSError:
        return None
    if not text:
        return None
    try:
        rec = json.loads(text)
        pid = int(rec["pid"])
        return {"pid": pid, "pgid": int(rec.get("pgid", pid)), "argv0": str(rec.get("argv0", ""))}
    except (ValueError, TypeError, KeyError):
        try:
            pid = int(text)  # legacy / hand-written bare-integer pidfile
        except ValueError:
            return None
        return {"pid": pid, "pgid": pid, "argv0": ""}

def _process_matches(pid: int, argv0: str) -> bool:
    """Best-effort check that live ``pid`` is the program we recorded (PID-reuse guard).

    On Linux, require ``/proc/<pid>/cmdline`` to mention the recorded ``argv0``; if
    procfs is absent (e.g. macOS) fall back to the liveness probe alone. If procfs
    exists but the cmdline is unreadable (a reused pid owned by another user), treat
    it as a non-match so stop never signals an unrelated process.
    """
    if not argv0:
        return True  # nothing recorded to verify against (legacy pidfile)
    proc = Path("/proc")
    if not proc.is_dir():
        return True  # no procfs — rely on the liveness probe only
    try:
        raw = (proc / str(pid) / "cmdline").read_bytes()
    except OSError:
        return False  # can't read it (gone, or not ours) — do not signal it
    cmdline = raw.replace(b"\x00", b" ").decode("utf-8", "replace")
    return argv0 in cmdline

def tunnel_pid(deploy_dir: os.PathLike | str) -> int | None:
    """Return the live, identity-verified cloudflared pid for this deployment, or ``None``."""
    rec = read_pidfile(deploy_dir)
    if rec is None:
        return None
    pid = rec["pid"]
    try:
        os.kill(pid, 0)  # signal 0 — liveness probe, sends nothing
    except OSError:
        return None
    if not _process_matches(pid, rec["argv0"]):
        return None
    return pid

def _still_running(pid: int) -> bool:
    """Liveness for the stop loop; reaps the process first if it is our own zombie child."""
    try:
        os.waitpid(pid, os.WNOHANG)  # reap a dead-but-unreaped child so kill(0) reflects reality
    except OSError:
        pass  # not our child (the common case — cloudflared was reparented to init)
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True

def _signal_group(pid: int, pgid: int, sig: int) -> None:
    """Signal the recorded process group, falling back to the bare pid."""
    try:
        os.killpg(pgid, sig)
    except OSError:
        try:
            os.kill(pid, sig)
        except OSError:
            pass

def _wait_gone(pid: int, timeout: float) -> bool:
    """Poll until ``pid`` exits or ``timeout`` elapses; True if it is gone."""
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        if not _still_running(pid):
            return True
        time.sleep(0.1)
    return not _still_running(pid)

def discover_system_bots(server_name: str, config: dict | None = None) -> list:
    """Return BotConfigs for enabled system bots."""
    root = Path(__file__).parent
    found = []
    sb_config = (config or {}).get("system_bots", {})
    for entry in sorted(root.iterdir()):
        if not entry.is_dir() or entry.name.startswith("_"):
            continue
        yaml_path = entry / "bot.yaml"
        if not yaml_path.is_file():
            continue
        enabled = sb_config.get(entry.name, {}).get("enabled", True)
        if not enabled:
            continue
        try:
            cfg = load_bot_config(yaml_path)
        except Exception:
            logger.warning("Failed to load system bot %s", entry.name, exc_info=True)
            continue
        cfg.name = f"{SYSTEM_USER_PREFIX}{server_name}-{entry.name}"
        cfg.owner = "system"
        found.append(cfg)
    return found

def _names_of(group) -> set[str]:
    names = getattr(group, "NAMES", None)
    if names is not None:
        return set(names)
    return {group.NAME}

def _json_mode_active(argv: list[str]) -> bool:
    """``--json`` is meaningful only on the three universal verbs.

    Other groups (`agents`, `server`, …) reject ``--json`` themselves; we
    only honor the AgentCulture JSON-error contract when the user is
    addressing an introspection verb. This matches what katvan's
    reference-sync actually invokes.
    """
    if "--json" not in argv:
        return False
    return any(v in argv for v in introspect.NAMES)

def _maybe_forward_to_steward(argv: list[str]) -> int | None:
    """Bypass argparse for steward verbs forwarded under ``agents`` / ``skills``.

    Mirrors ``_maybe_forward_to_agentirc``: argparse REMAINDER can't capture
    ``--help`` reliably, so forwarded steward verbs are short-circuited here and
    replayed through ``steward.cli.main`` verbatim (the ``skills`` verb is remapped
    to steward's canonical name). Returns the exit code, or None to let
    argparse handle a native verb.
    """
    if len(argv) < 2:
        return None
    noun, verb = argv[0], argv[1]
    if noun == "agents" and verb in agents._STEWARD_FORWARDED_VERBS:
        steward_argv = [verb, *argv[2:]]
    elif noun == "skills" and verb in skills._STEWARD_FORWARDED:
        steward_argv = [skills._STEWARD_FORWARDED[verb], *argv[2:]]
    else:
        return None
    try:
        from steward.cli import main as steward_main
    except ImportError as exc:  # pragma: no cover — declared dep
        print(f"steward-cli is not installed: {exc}", file=sys.stderr)
        return 2
    return steward_main(steward_argv)

def to_dict(self) -> dict[str, object]:
    return {
        "code": self.code,
        "message": self.message,
        "remediation": self.remediation,
    }

def _translate_exit(code: "int | str | None") -> "tuple[int, str | None]":
    """Map a ``SystemExit.code`` to ``(rc, message)``.

    Python's ``sys.exit`` accepts ``None`` (rc 0), an ``int`` (rc = int), or
    anything else (rc 1 with the stringified value printed to stderr). We
    mirror all three so an embedded CLI using any ``sys.exit`` form is
    surfaced to culture's caller the way a bare invocation would be.
    """
    if code is None:
        return 0, None
    if isinstance(code, int):
        return code, None
    return 1, str(code)

