def _validate_name_or_raise(name: str) -> None:
    """Reject names that are not a safe single path segment (#19)."""
    from culture_core.bots.config import validate_bot_name

    if not validate_bot_name(name):
        raise CultureError(
            EXIT_USER_ERROR,
            f"invalid bot name '{name}'",
            "use a single path segment (no '/', '\\' or '..'), e.g. spark-ori-ghci; "
            "run 'culture bot list' to see existing bots",
        )

def _should_include_bot(bot_config, owner: str | None, show_archived: bool) -> bool:
    """Return True if the bot should be included in the listing."""
    if owner and bot_config.owner != owner:
        return False
    if not show_archived and bot_config.archived:
        return False
    return True

def _load_and_filter_bots(args) -> list:
    """Load bot configs, filtering by owner and archived status."""
    from culture_core.bots.config import BOTS_DIR, load_bot_config

    if not BOTS_DIR.is_dir():
        return []
    show_all = getattr(args, "all", False)
    bots = []
    for bot_dir in sorted(BOTS_DIR.iterdir()):
        yaml_path = bot_dir / BOT_CONFIG_FILE
        if not yaml_path.is_file():
            continue
        try:
            config = load_bot_config(yaml_path)
        except Exception:
            continue
        if not config.name:
            continue
        if _should_include_bot(config, args.owner, show_all):
            bots.append(config)
    return bots

def _bot_list(args: argparse.Namespace) -> None:
    from culture_core.bots.config import BOTS_DIR

    if not BOTS_DIR.is_dir():
        print("No bots configured.")
        return

    bots = _load_and_filter_bots(args)
    if not bots:
        if args.owner:
            print(f"No bots found for owner '{args.owner}'.")
        else:
            print("No bots configured.")
        return

    show_all = getattr(args, "all", False)
    print(f"{'NAME':<35} {'TRIGGER':<10} {'CHANNELS':<20} {'OWNER':<20}")
    for config in bots:
        channels = ", ".join(config.channels) if config.channels else "-"
        name = f"{config.name} [archived]" if show_all and config.archived else config.name
        print(f"{name:<35} {config.trigger_type:<10} {channels:<20} {config.owner:<20}")

def _valid_nick(nick: str) -> bool:
    """Check nick matches the required <server>-<agent> format."""
    parts = nick.split("-", 1)
    return len(parts) == 2 and all(parts)

def _daemon_error(action: str, resp: dict) -> CultureError:
    """Build the CultureError for a daemon IPC response with ``ok=False``."""
    nick = os.environ.get("CULTURE_NICK")
    status_cmd = (
        f"culture agents status {nick}" if nick and _valid_nick(nick) else "culture agents status"
    )
    return CultureError(
        EXIT_USER_ERROR,
        f"{action} failed: {resp.get('error', 'unknown error')}",
        f"check the agent daemon: {status_cmd}",
    )

def _require_channel_name(target: str, example: str) -> None:
    """Reject blank channel names with a per-command usage example (#19)."""
    if not target.strip():
        raise CultureError(
            EXIT_USER_ERROR,
            "channel name cannot be empty",
            f"pass a channel name, e.g. {example}",
        )

def _is_connection_error(msg: str) -> bool:
    """Return True if the exception message indicates a connection failure."""
    return (
        "Timed out" in msg or "Connection refused" in msg or "Connect call failed" in msg or not msg
    )

def dispatch(args: argparse.Namespace) -> None:
    if not args.channel_command:
        print(f"Usage: culture channel {{{_ALL_CMDS}}}", file=sys.stderr)
        sys.exit(1)

    handlers = {
        "list": _cmd_list,
        "read": _cmd_read,
        "message": _cmd_message,
        "who": _cmd_who,
        "join": _cmd_join,
        "part": _cmd_part,
        "ask": _cmd_ask,
        "topic": _cmd_topic,
        "compact": _cmd_compact,
        "clear": _cmd_clear,
    }
    handler = handlers.get(args.channel_command)
    if not handler:
        raise CultureError(
            EXIT_USER_ERROR,
            f"Unknown channel command: {args.channel_command}",
            f"run 'culture channel --help' to list subcommands ({_ALL_CMDS})",
        )
    try:
        handler(args)
    except OSError as exc:
        if _is_connection_error(str(exc)):
            raise CultureError(
                EXIT_USER_ERROR,
                "cannot connect to IRC server. Is the server running?",
                "start it with: culture server start",
            ) from exc
        raise

def _cmd_list(args: argparse.Namespace) -> None:
    resp = _try_ipc("irc_channels")
    if resp and resp.get("ok"):
        channels = resp.get("data", {}).get("channels", [])
        if not channels:
            print("No active channels")
            return
        print("Active channels:")
        for ch in channels:
            print(f"  {ch}")
        return

    _warn_observer_fallback("channel list")
    observer = get_observer(args.config)
    channels = asyncio.run(observer.list_channels())

    if not channels:
        print("No active channels")
        return

    print("Active channels:")
    for ch in channels:
        print(f"  {ch}")

def _cmd_join(args: argparse.Namespace) -> None:
    target = args.target if args.target.startswith("#") else f"#{args.target}"
    resp = _require_ipc("irc_join", channel=target)
    if not resp.get("ok"):
        raise _daemon_error(f"join {target}", resp)
    print(f"Joined {target}")

def _cmd_part(args: argparse.Namespace) -> None:
    target = args.target if args.target.startswith("#") else f"#{args.target}"
    resp = _require_ipc("irc_part", channel=target)
