def _collect_mesh_data(
    host: str,
    port: int,
    server_name: str,
    message_limit: int,
    manifest_agents: list | None = None,
):
    """Collect mesh state, raising a remediated CultureError on connection failure."""
    from culture_core.overview.collector import collect_mesh_state

    try:
        return asyncio.run(
            collect_mesh_state(
                host=host,
                port=port,
                server_name=server_name,
                message_limit=message_limit,
                manifest_agents=manifest_agents,
            )
        )
    except ConnectionRefusedError as exc:
        raise CultureError(
            EXIT_USER_ERROR,
            f"could not connect to {host}:{port} — is the server running?",
            f"start it with: culture server start --name {server_name}",
        ) from exc
    except TimeoutError as exc:
        raise CultureError(
            EXIT_USER_ERROR,
            f"server at {host}:{port} not responding — it may still be starting up",
            "wait a few seconds and retry, or check: culture server status",
        ) from exc
    except OSError as exc:
        raise CultureError(
            EXIT_USER_ERROR,
            f"cannot reach {host}:{port}: {exc}",
            "verify the server host/port in ~/.culture/server.yaml, then retry",
        ) from exc

def _store_mesh_credentials(mesh) -> None:
    """Prompt for link passwords and store them in the OS keyring (never in files)."""
    import getpass

    from culture_core.credentials import lookup_credential, store_credential

    for link in mesh.server.links:
        try:
            existing = lookup_credential(link.name)
        except ValueError as exc:
            print(
                f"  Warning: skipping link '{link.name}': {exc}. "
                "Fix the link name in mesh.yaml.",
                file=sys.stderr,
            )
            continue
        if existing:
            print(f"  Credential for '{link.name}' already in keyring")
        else:
            password = getpass.getpass(f"Link password for {link.name}: ")
            if store_credential(link.name, password):
                print(f"  Stored credential for '{link.name}' in OS keyring")
            else:
                print(
                    f"  Warning: failed to store credential for '{link.name}'",
                    file=sys.stderr,
                )
                print(
                    "  You may need to install secret-tool (Linux)"
                    " or check Keychain access (macOS)",
                    file=sys.stderr,
                )

def _find_upgrade_tool() -> tuple[str, list[str]] | None:
    """Return (tool_name, command_args) for the first available upgrade tool, or None."""
    uv = shutil.which("uv")
    if uv:
        return "uv", [uv, "tool", "upgrade", "culture"]

    pip = shutil.which("pip") or shutil.which("pip3")
    if pip:
        return "pip", [pip, "install", "--upgrade", "culture"]

    return None

def _dry_run_restart(mesh, server_name: str) -> None:
    """Print what a restart would do without executing."""
    for agent in mesh.agents:
        print(f"[dry-run] Would stop agent {server_name}-{agent.nick}")
    print(f"[dry-run] Would stop server {server_name}")
    print("[dry-run] Would regenerate auto-start entries")
    print(f"[dry-run] Would start server {server_name}")
    for agent in mesh.agents:
        print(f"[dry-run] Would start agent {server_name}-{agent.nick}")

def _restart_single_service(svc_name: str, fallback_cmd: list[str], restart_service_fn) -> None:
    """Restart a service, falling back to a CLI command if no service file exists."""
    print(f"  Restarting {svc_name}...")
    if restart_service_fn(svc_name):
        return
    if sys.platform == "win32":
        print(
            "  No service file found. Run 'culture mesh setup' to install services; starting via CLI...",
            file=sys.stderr,
        )
    else:
        print("  No service file found, starting via CLI...")
    try:
        subprocess.run(fallback_cmd, check=False, timeout=_FALLBACK_START_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        print(
            f"  Warning: startup command for {svc_name} timed out after "
            f"{_FALLBACK_START_TIMEOUT_SECONDS}s — continuing",
            file=sys.stderr,
        )

def _restart_running_servers(running, args, culture_bin):
    """Restart all running servers, returning names of any that failed."""
    failed = []
    for srv in running:
        mesh = _resolve_mesh_for_server(srv["name"], args.config)
        if mesh is None:
            print(
                f"  Warning: no config found for server '{srv['name']}', skipping",
                file=sys.stderr,
            )
            continue
        if not _restart_mesh_services(mesh, srv["name"], culture_bin, args.config, args.dry_run):
            failed.append(srv["name"])
    return failed

def _restart_from_config(args, culture_bin):
    """Start services from config when none are running, returning names of any that failed."""
    from culture_core.mesh_config import load_mesh_config

    try:
        mesh = load_mesh_config(args.config)
    except FileNotFoundError:
        mesh = generate_mesh_from_agents(args.config)
        if mesh is None:
            raise CultureError(
                EXIT_USER_ERROR,
                f"no mesh config at {args.config} and no server config at {DEFAULT_CONFIG}",
                "start a server with 'culture server start' and add agents with "
                "'culture agents create', then rerun: culture mesh update",
            ) from None
    failed = []
    if not _restart_mesh_services(mesh, mesh.server.name, culture_bin, args.config, args.dry_run):
        failed.append(mesh.server.name)
    return failed

def _cmd_update(args: argparse.Namespace) -> None:
    from culture_core.pidfile import list_servers

    if not _upgrade_culture_package(args):
        return

    culture_bin = [sys.executable, "-m", "culture_core"]

    running = list_servers()
    failed = (
        _restart_running_servers(running, args, culture_bin)
        if running
        else _restart_from_config(args, culture_bin)
    )

    if failed:
        raise CultureError(
            EXIT_USER_ERROR,
            f"Update finished with errors. Failed to restart: {', '.join(failed)}",
            "check the service logs (Linux: journalctl --user -u culture-server-<name>; "
            "otherwise ~/.culture/logs/) and rerun: culture mesh update --skip-upgrade",
        )

    if args.dry_run:
        print("Dry run complete. No services were restarted.")
    else:
        print("Update complete. All services restarted.")

def _tokens_cell(resident: Resident) -> str:
    if resident.tokens_in is None and resident.tokens_out is None:
        return _MISSING
    left = _MISSING if resident.tokens_in is None else str(resident.tokens_in)
    right = _MISSING if resident.tokens_out is None else str(resident.tokens_out)
    return f"{left}/{right}"

def _budget_cell(resident: Resident) -> str:
    if resident.budget_used_pct is None:
        return _MISSING
    return f"{resident.budget_used_pct:g}%"

def _flags_cell(resident: Resident) -> str:
    flags = []
    if resident.presumed_hung:
        flags.append("HUNG?")
    if resident.budget_warning:
        flags.append("BUDGET")
    return ",".join(flags) or _MISSING

def _render_table(residents: list[Resident]) -> str:
    """Render the human table — readable even for state-only residents.

    Rows are sorted by nick (same order as the JSON payload); every missing
    field renders as a dash.
    """
    rows = [_row(r) for r in sorted(residents, key=lambda r: r.nick)]
    widths = [
        max(len(_COLUMNS[i]), *(len(row[i]) for row in rows)) if rows else len(_COLUMNS[i])
        for i in range(len(_COLUMNS))
    ]
    lines = ["  ".join(_COLUMNS[i].ljust(widths[i]) for i in range(len(_COLUMNS))).rstrip()]
    for row in rows:
        lines.append("  ".join(row[i].ljust(widths[i]) for i in range(len(_COLUMNS))).rstrip())
    return "\n".join(lines)

def _resolve_server_name(args: argparse.Namespace) -> str:
    """Resolve the server name from args, default server file, or fallback."""
    if args.name is not None:
        return args.name
    return read_default_server() or _DEFAULT_SERVER

def _server_rename(args: argparse.Namespace) -> None:
    """Rename the server: update config, agent nicks, and PID files."""
    from culture_core.config import rename_manifest_server, sanitize_agent_name
    from culture_core.pidfile import (
        is_process_alive,
        read_default_server,
        read_pid,
        rename_pid,
        write_default_server,
    )

    try:
        new_name = sanitize_agent_name(args.new_name)
    except ValueError:
        raise CultureError(
            EXIT_USER_ERROR,
            f"Invalid server name: {args.new_name!r}",
            "use a name containing letters, digits, or hyphens, "
            "e.g. 'culture server rename spark2'",
        ) from None

    try:
        old_name, renamed = rename_manifest_server(args.config, new_name)
    except ValueError as exc:
        raise CultureError(
            EXIT_USER_ERROR,
            str(exc),
            f"check the config path ({args.config}) and the current server name "
            "with 'culture server status'",
        ) from exc

    if old_name == new_name:
        print(f"Server is already named '{new_name}'")
        return

    rename_pid(f"server-{old_name}", f"server-{new_name}")

    for old_nick, new_nick in renamed:
        rename_pid(f"agent-{old_nick}", f"agent-{new_nick}")

    if read_default_server() == old_name:
        write_default_server(new_name)

    print(f"Server renamed: {old_name} → {new_name}")
    for old_nick, new_nick in renamed:
        print(f"  Agent: {old_nick} → {new_nick}")

    server_pid = read_pid(f"server-{new_name}")
    server_running = server_pid and is_process_alive(server_pid)

    print()
    if server_running:
        print("The server is still running under the old name.")
        print("Restart it for the rename to take effect:")
        print(f"  culture server stop --name {new_name}")
        print(f"  culture server start --name {new_name}")
    if renamed:
        print("Restart agents for the new nicks to take effect:")
        print("  culture agents stop --all && culture agents start --all")

def _daemon_child_exit_code(pid: int) -> int | None:
    """Reap-and-detect: return *pid*'s exit code if it has exited, else None.

    Only meaningful from the direct parent of the forked daemon child. A
    child that dies before the parent reaps it becomes a zombie, and
    ``os.kill(pid, 0)`` (``is_process_alive``) reports zombies as alive —
    so the verification loops must use ``os.waitpid(pid, os.WNOHANG)``
    instead. Returns None while the child is still running, and also when
    *pid* is not our child (``ChildProcessError``) so callers can fall back
    to ``is_process_alive``.
    """
    try:
        wpid, status = os.waitpid(pid, os.WNOHANG)
    except ChildProcessError:
        return None
    if wpid == 0:
        return None
    if os.WIFSIGNALED(status):
        return 128 + os.WTERMSIG(status)
    return os.WEXITSTATUS(status)

def _describe_daemon_exit(code: int) -> str:
    """Human-readable failure text for a daemon child that exited early."""
    if code == EXIT_DAEMON_PERMANENT:
        return f"exited with code {code} (permanent error — will not be restarted)"
    return f"exited with code {code}"

def _probe_daemon_failure(pid: int) -> str | None:
    """Return a failure description if the daemon child is gone, else None.

    Prefers the reap-and-detect probe (which sees zombies and knows the
    exit status); falls back to ``is_process_alive`` when *pid* is not our
    child — e.g. it was already reaped elsewhere.
    """
    code = _daemon_child_exit_code(pid)
    if code is not None:
        return _describe_daemon_exit(code)
    if not is_process_alive(pid):
        return "failed to start"
    return None

def _maybe_set_default_server(name: str) -> None:
    """Set this server as default if none is configured."""
    from culture_core.pidfile import read_default_server, write_default_server

    if read_default_server() is None:
        write_default_server(name)

def _check_already_running(pid_name: str, name: str) -> None:
    """Raise if the server is already running."""
    existing = read_pid(pid_name)
    if existing and is_process_alive(existing):
        raise CultureError(
            EXIT_USER_ERROR,
            f"Server '{name}' is already running (PID {existing})",
            f"stop it first with 'culture server stop --name {name}' " "if you want to restart it",
        )

def _wait_for_graceful_stop(pid: int, timeout_ticks: int = 50) -> bool:
    """Wait for a process to exit gracefully. Return True if it stopped."""
    for _ in range(timeout_ticks):
        if not is_process_alive(pid):
            return True
        time.sleep(0.1)
    return False

def _force_kill(pid: int, name: str) -> None:
    """Force-kill a process that didn't stop gracefully."""
    if sys.platform == "win32":
        print(f"Server '{name}' did not stop gracefully, terminating")
        sig = signal.SIGTERM
    else:
        print(f"Server '{name}' did not stop gracefully, sending SIGKILL")
        sig = signal.SIGKILL
    try:
        # NOSONAR S4828: PID was validated by is_process_alive +
        # is_culture_process in _server_stop before reaching this
        # graceful-stop fallback; we are signaling our own daemon.
        os.kill(pid, sig)
    except ProcessLookupError:
        pass

def _server_status(args: argparse.Namespace) -> None:
    pid_name = f"server-{args.name}"
    pid = read_pid(pid_name)

    if pid is None:
        print(f"Server '{args.name}': not running (no PID file)")
        return

    if is_process_alive(pid):
        print(f"Server '{args.name}': running (PID {pid})")
    else:
        print(f"Server '{args.name}': not running (stale PID {pid})")
        remove_pid(pid_name)

def _server_uninstall(args: argparse.Namespace) -> None:
