def _set_bots_archive_state(agent_nicks: set, *, archive: bool, reason: str = "") -> list[str]:
    """Archive or unarchive bots owned by any of the given agent nicks."""
    from culture_core.bots.config import BOTS_DIR, load_bot_config

    changed = []
    if not BOTS_DIR.is_dir():
        return changed
    today = time.strftime("%Y-%m-%d")
    for bot_dir in BOTS_DIR.iterdir():
        yaml_path = bot_dir / BOT_CONFIG_FILE
        if not yaml_path.is_file():
            continue
        try:
            bot_config = load_bot_config(yaml_path)
        except (OSError, ValueError) as exc:
            print(f"  Warning: skipping bot '{bot_dir.name}': {exc}", file=sys.stderr)
            continue
        if bot_config.owner not in agent_nicks:
            continue
        name = _update_single_bot_archive(yaml_path, bot_config, archive, reason, today)
        if name:
            changed.append(name)
    return changed

def shutdown_cli_tracing() -> None:
    """Flush and drop the local provider (call after the verb completes)."""
    global _provider
    if _provider is not None:
        try:
            _provider.shutdown()
        except Exception:  # noqa: BLE001 - teardown must not mask the verb's outcome
            logger.debug("CLI tracer provider shutdown failed", exc_info=True)
        _provider = None

def resolve_console_nick() -> str:
    """Resolve the human nick: git user.name -> OS USER -> 'human'."""
    try:
        result = subprocess.run(
            ["git", "config", "user.name"],
            capture_output=True,
            text=True,
            timeout=2,
            check=False,
        )
        if result.returncode == 0 and result.stdout.strip():
            name = result.stdout.strip().lower()
            name = re.sub(r"[^a-z0-9-]", "", name.replace(" ", "-"))
            if name:
                return name
    except (subprocess.SubprocessError, FileNotFoundError):
        pass

    return os.environ.get("USER", "human")

def agent_process_status(agent) -> tuple[str, int | None]:
    """Return (status_str, pid_or_none) for an agent."""
    pid_name = f"agent-{agent.nick}"
    pid = read_pid(pid_name)
    if pid and is_process_alive(pid):
        socket_path = agent_socket_path(agent.nick)
        if os.path.exists(socket_path):
            return "running", pid
        return "starting", pid
    if pid:
        remove_pid(pid_name)
    return "stopped", None

def _format_agent_status(base_status: str, archived: bool, show_archived_marker: bool) -> str:
    """Format the display status string for an agent."""
    if not archived:
        return base_status
    if show_archived_marker:
        return f"{base_status} (archived)"
    if base_status == "stopped":
        return "archived"
    return base_status

def _fetch_ipc_data(agent) -> dict | None:
    """Fetch full IPC status data from a running agent."""
    resp = asyncio.run(ipc_request(agent_socket_path(agent.nick), "status"))
    if resp and resp.get("ok"):
        return resp.get("data", {})
    return None

def _agent_overview_row(
    agent, show_activity: bool, show_archived_marker: bool
) -> tuple[str, str, str, str]:
    """Build (nick, status, pid_str, activity) for one agent row."""
    base_status, pid = agent_process_status(agent)
    activity = "-"
    if base_status == "running":
        ipc_data = _fetch_ipc_data(agent)
        if ipc_data:
            if ipc_data.get("circuit_open"):
                base_status = "circuit-open"
            elif ipc_data.get("paused"):
                base_status = "paused"
            if show_activity:
                activity = ipc_data.get("description", "nothing")
    status = _format_agent_status(
        base_status, getattr(agent, "archived", False), show_archived_marker
    )
    return agent.nick, status, str(pid or "-"), activity

def print_agents_overview(
    agents: list, show_activity: bool, show_archived_marker: bool = False
) -> None:
    """Print a table of all agents with status, PID, and optionally activity."""
    if show_activity:
        print(f"{'NICK':<30} {'STATUS':<12} {'PID':<10} {'ACTIVITY'}")
        print("-" * 72)
    else:
        print(f"{'NICK':<30} {'STATUS':<12} {'PID':<10}")
        print("-" * 52)

    for agent in agents:
        nick, status, pid_str, activity = _agent_overview_row(
            agent, show_activity, show_archived_marker
        )
        if show_activity:
            print(f"{nick:<30} {status:<12} {pid_str:<10} {activity}")
        else:
            print(f"{nick:<30} {status:<12} {pid_str:<10}")

def _load_bot_configs(*, show_archived: bool = False) -> list:
    """Load valid bot configs from the bots directory.

    Filters out archived bots by default (matching `culture bot list`) and
    skips configs with empty names so malformed entries don't leak into the
    UI.
    """
    from culture_core.bots.config import BOTS_DIR, load_bot_config

    if not BOTS_DIR.is_dir():
        return []
    configs = []
    for bot_dir in sorted(BOTS_DIR.iterdir()):
        yaml_path = bot_dir / BOT_CONFIG_FILE
        if not yaml_path.is_file():
            continue
        try:
            config = load_bot_config(yaml_path)
        except Exception as exc:
            logger.warning("Failed to load bot config %s: %s", yaml_path, exc)
            continue
        if not config.name:
            continue
        if config.archived and not show_archived:
            continue
        configs.append(config)
    return configs

def agent_socket_path(nick: str) -> str:
    from culture_core.cli.shared.constants import culture_runtime_dir

    return os.path.join(
        culture_runtime_dir(),
        f"culture-{nick}.sock",
    )

def _nick_from_socket_path(socket_path: str) -> str:
    """Best-effort reverse of :func:`agent_socket_path` for log context."""
    basename = os.path.basename(socket_path)
    if basename.startswith("culture-") and basename.endswith(".sock"):
        return basename[len("culture-") : -len(".sock")]
    return ""

def parse_link(value: str):
    """Parse a link spec: name:host:port:password[:trust]

    Trust is extracted from the end if it matches a known value.
    This allows passwords containing colons.
    """
    from agentirc.config import LinkConfig

    trust = "full"
    if value.endswith((":full", ":restricted")):
        value, trust = value.rsplit(":", 1)

    parts = value.split(":", 3)
    if len(parts) != 4:
        raise argparse.ArgumentTypeError(
            f"Link must be name:host:port:password[:trust], got: {value}"
        )
    name, host, port_str, password = parts
    try:
        port = int(port_str)
    except ValueError:
        raise argparse.ArgumentTypeError(f"Invalid port: {port_str}")
    return LinkConfig(name=name, host=host, port=port, password=password, trust=trust)

def load_mesh_or_generate(config_path: str):
    """Load mesh.yaml, falling back to generating it from the server manifest.

    This is the one config resolution used by every verb that provisions
    the server's service unit (``culture mesh setup``,
    ``culture server install``/``uninstall``): read *config_path*
    (mesh.yaml); if it doesn't exist, derive one from ``DEFAULT_CONFIG``
    (``~/.culture/server.yaml``) and save it. Returns ``None`` when
    neither file exists — callers raise their own user error.
    """
    from culture_core.mesh_config import load_mesh_config

    try:
        return load_mesh_config(config_path)
    except FileNotFoundError:
        return generate_mesh_from_agents(config_path)

def stop_agent(nick: str) -> None:
    """Stop a single agent by trying IPC shutdown first, then PID file."""
    socket_path = agent_socket_path(nick)

    if _try_ipc_shutdown(nick, socket_path):
        return

    _try_pid_shutdown(nick)

def _try_ipc_shutdown(nick: str, socket_path: str) -> bool:
    """Attempt graceful IPC shutdown. Return True if the agent stopped."""
    if not os.path.exists(socket_path):
        return False
    try:
        success = asyncio.run(ipc_shutdown(socket_path))
        if not success:
            return False
    except Exception:
        return False

    print(f"Agent '{nick}' shutdown requested via IPC")
    pid_name = f"agent-{nick}"
    pid = read_pid(pid_name)
    if not pid:
        print(f"Agent '{nick}' stopped")
        return True
    for _ in range(50):
        if not is_process_alive(pid):
            remove_pid(pid_name)
            print(f"Agent '{nick}' stopped")
            return True
        time.sleep(0.1)
    return False

def server_stop_by_name(name: str) -> None:
    """Stop a server by name (helper for setup --uninstall and update)."""
    pid_name = f"server-{name}"
    pid = read_pid(pid_name)
    if not pid or not is_process_alive(pid):
        if pid:
            remove_pid(pid_name)
        return

    if not is_culture_process(pid):
        remove_pid(pid_name)
        return

    os.kill(pid, signal.SIGTERM)
    for _ in range(50):
        if not is_process_alive(pid):
            remove_pid(pid_name)
            return
        time.sleep(0.1)

    if sys.platform == "win32":
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
    else:
        try:
            os.kill(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
    remove_pid(pid_name)

def dispatch(args: argparse.Namespace) -> None:
    if not hasattr(args, "skills_command") or args.skills_command != "install":
        print(
            "Usage: culture skills install <claude|codex|copilot|acp|opencode|all>",
            file=sys.stderr,
        )
        sys.exit(1)

    target = args.target

    if target in ("claude", "all"):
        _install_skill_claude()
    if target in ("codex", "all"):
        _install_skill_codex()
    if target in ("copilot", "all"):
        _install_skill_copilot()
    if target in ("acp", "opencode", "all"):
        _install_skill_acp()

    if target == "all":
        print("\nSkills installed for Claude Code, Codex, Copilot, and ACP.")
    print("\nSet CULTURE_NICK in your shell profile to enable the skill.")

