def check_unregistered(config, discovered) -> list[Finding]:
    """Class 2: on-disk repos not registered in the manifest."""
    manifest_dirs = {str(Path(d).resolve()) for d in config.manifest.values()}
    findings: list[Finding] = []
    for repo in discovered:
        if str(Path(repo.directory).resolve()) not in manifest_dirs:
            findings.append(
                Finding(
                    2,
                    "warning",
                    Path(repo.directory).name,
                    repo.directory,
                    f"on-disk culture.yaml not registered: {repo.directory}",
                    f"culture agents register {repo.directory}",
                )
            )
    return findings

def _manifest_collisions(config, discovered) -> list[Finding]:
    """A discovered suffix already bound to a DIFFERENT path in the manifest."""
    findings: list[Finding] = []
    for repo in discovered:
        for s in repo.suffixes:
            if s in config.manifest and str(Path(config.manifest[s]).resolve()) != str(
                Path(repo.directory).resolve()
            ):
                findings.append(
                    Finding(
                        3,
                        "error",
                        s,
                        repo.directory,
                        f"suffix '{s}' at {repo.directory} collides with registered {config.manifest[s]}",
                        "",
                    )
                )
    return findings

def _discovered_duplicates(config, discovered) -> list[Finding]:
    """The same suffix declared by two discovered repos. Suffixes already bound
    in the manifest are :func:`_manifest_collisions`' responsibility — skip them
    here so a manifest collision isn't double-reported."""
    findings: list[Finding] = []
    seen: dict[str, str] = {}
    for repo in discovered:
        for s in repo.suffixes:
            if s in config.manifest:
                continue
            resolved = str(Path(repo.directory).resolve())
            if s in seen and seen[s] != resolved:
                findings.append(
                    Finding(
                        3,
                        "error",
                        s,
                        repo.directory,
                        f"suffix '{s}' declared by both {seen[s]} and {repo.directory}",
                        "",
                    )
                )
            else:
                seen[s] = resolved
    return findings

def _parse_systemctl_show(output: str) -> dict[str, str]:
    """Parse ``Key=Value`` lines from ``systemctl show`` output."""
    props: dict[str, str] = {}
    for line in output.splitlines():
        key, sep, value = line.partition("=")
        if sep:
            props[key.strip()] = value.strip()
    return props

def check_services(
    services: list[str] | None = None,
    run_systemctl: Callable[[str], str | None] | None = None,
) -> list[Finding]:
    """Class 4: installed culture services that are parked or restart-looping.

    *run_systemctl* is the injectable command-runner seam — tests feed
    canned ``systemctl --user show`` output without systemd. With the
    default (real) runner the check passes gracefully on non-Linux
    platforms and when systemctl is absent.
    """
    if run_systemctl is None:
        if get_platform() != "linux" or shutil.which("systemctl") is None:
            return []
        run_systemctl = _systemctl_show
    if services is None:
        services = list_services()

    findings: list[Finding] = []
    for name in services:
        output = run_systemctl(f"{name}.service")
        if output is None:
            continue
        findings.extend(_service_findings(name, _parse_systemctl_show(output)))
    return findings

@dataclass
class RepoOnDisk:
    """A repo directory discovered on disk."""

    directory: str  # resolved absolute path
    suffixes: list[str]  # declared suffix(es) from its culture.yaml

def resolve_scan_root(config, cwd=None, override=None) -> Path:
    """Determine the root directory to scan.

    Priority:
    1. *override* if provided.
    2. Parent of the culture repo found via manifest or git walk.
    """
    if override is not None:
        return Path(override).resolve()

    repo_dir = _find_culture_repo(config, Path(cwd) if cwd else Path.cwd())
    return repo_dir.parent.resolve()

def _find_culture_repo(config, start: Path) -> Path:
    """Find the culture repo directory.

    PRIMARY: check manifest entries for a path that contains this module.
    FALLBACK: walk up from *start* until a ``.git`` entry is found.
    """
    this_file = Path(__file__).resolve()
    for d in config.manifest.values():
        rd = Path(d).resolve()
        if rd == this_file or rd in this_file.parents:
            return rd

    current = start.resolve()
    while True:
        if (current / ".git").exists():
            return current
        parent = current.parent
        if parent == current:
            return start
        current = parent

def discover_ondisk_repos(root) -> list[RepoOnDisk]:
    """Discover repos under *root* that have a culture.yaml."""

    root = Path(root)
    results: list[RepoOnDisk] = []

    for child in sorted(p for p in root.iterdir() if p.is_dir()):
        try:
            agents = load_culture_yaml(str(child))
        except (OSError, ValueError, YAMLError) as exc:
            # No culture.yaml (the common case) or an unreadable/malformed one:
            # skip it, but don't swallow the reason entirely.
            logger.debug("skipping %s during doctor scan: %s", child, exc)
            continue
        results.append(
            RepoOnDisk(
                directory=str(child.resolve()),
                suffixes=[a.suffix for a in agents],
            )
        )

    return results

def register_unregistered(
    config_path: str, class2_findings: list[Finding]
) -> list[tuple[str, str]]:
    """Register each class-2 (unregistered on-disk) repo into the server.yaml at config_path.

    Reuses add_to_manifest (writes ONLY server.yaml; never the repo's culture.yaml).
    Idempotent: a suffix already in the manifest is skipped. Returns the (suffix, directory)
    pairs actually added. Empty findings -> no writes, returns [].
    """
    added: list[tuple[str, str]] = []
    for f in class2_findings:
        try:
            agents = load_culture_yaml(f.path)
        except Exception:
            continue
        for a in agents:
            try:
                add_to_manifest(config_path, a.suffix, f.path)
                added.append((a.suffix, f.path))
            except ValueError:
                continue  # already registered -> idempotent skip
    return added

@property
def exit_code(self) -> int:
    # Class-4 warnings (restart-looping) don't fail the run; parked
    # (failed) units are errors and do — same policy as class 2 vs 1/3.
    class4_errors = any(f.severity == "error" for f in self.class4)
    return 1 if (self.class1 or self.class3 or class4_errors) else 0

async def _query_roommeta(
    reader: asyncio.StreamReader,
    writer: asyncio.StreamWriter,
    _nick: str,
    channel: str,
) -> dict:
    """Query ROOMMETA and return a dict with room metadata fields."""
    writer.write(f"ROOMMETA {channel}\r\n".encode())
    await writer.drain()
    messages = await _recv_until(
        reader, writer, {"ROOMETAEND", "ERR_NOSUCHCHANNEL", "ERR_UNKNOWNCOMMAND"}
    )
    result: dict = {}
    for msg in messages:
        if msg.command == "ROOMMETA" and len(msg.params) >= 3:
            # Server sends: ROOMMETA <channel> <key> <value>
            key = msg.params[1].strip().lower()
            value = msg.params[2]
            if key == "room_id":
                result["room_id"] = value
            elif key == "owner":
                result["owner"] = value
            elif key == "purpose":
                result["purpose"] = value
            elif key == "tags":
                result["tags"] = [t.strip() for t in value.split(",") if t.strip()]
            elif key == "persistent":
                result["persistent"] = value.lower() in ("1", "true", "yes")
    return result

@dataclass
class FailedRoom:
    """A room whose collection failed; the snapshot continued without it."""

    name: str
    error: str  # exception class name, e.g. "TimeoutError"
    phase: str  # query phase that failed, e.g. "WHO"

def _agent_table(members: list[Agent]) -> str:
    """Render a markdown table of agents."""
    lines = [
        "| Agent | Status | Activity |",
        "|-------|--------|----------|",
    ]
    for a in members:
        activity = _escape_cell(a.activity) if a.is_local else ""
        lines.append(f"| {_escape_cell(a.nick)} | {a.status} | {activity} |")
    return "\n".join(lines)

def _message_list(messages: list[Message], limit: int) -> str:
    """Render recent messages as a markdown bullet list."""
    if not messages:
        return "No recent messages."
    shown = messages[:limit]
    lines = []
    for m in shown:
        lines.append(f"- {m.nick} ({_relative_time(m.timestamp)}): {m.text}")
    return "\n".join(lines)

def render_text(
    mesh: MeshState,
    *,
    room_filter: str | None = None,
    agent_filter: str | None = None,
    message_limit: int = 4,
) -> str:
    """Render a full mesh overview as markdown."""
    if agent_filter:
        return _render_agent_detail(mesh, agent_filter, message_limit)
    if room_filter:
        return _render_room_detail(mesh, room_filter, message_limit)
    return _render_default(mesh, message_limit)

def _summary_line(mesh: MeshState, fed_str: str) -> str:
    """Build the summary line with room/agent counts."""
    room_str = f"{len(mesh.rooms)} room{'s' if len(mesh.rooms) != 1 else ''}"
    stopped = [a for a in mesh.agents if a.status == "stopped"]
    if stopped:
        online = len(mesh.agents) - len(stopped)
        agent_str = f"{online} online, {len(stopped)} stopped ({len(mesh.agents)} total)"
    else:
        agent_str = f"{len(mesh.agents)} agent{'s' if len(mesh.agents) != 1 else ''}"
    return f"{room_str} | {agent_str} | {fed_str}"

def _render_default(mesh: MeshState, message_limit: int) -> str:
    """Render the full mesh overview."""
    fed_count = len(mesh.federation_links)
    fed_str = f"{fed_count} federation link{'s' if fed_count != 1 else ''}"
    if mesh.federation_links:
        fed_str += f" ({', '.join(mesh.federation_links)})"

    parts = [f"# {mesh.server_name} mesh", "", _summary_line(mesh, fed_str)]

    if mesh.failed_rooms:
        parts.append("")
        parts.append(_partial_snapshot_line(mesh))

    for room in mesh.rooms:
        parts.append("")
        parts.append(_render_room(room, message_limit))

    stopped_agents = [a for a in mesh.agents if a.status == "stopped"]
    if stopped_agents:
        parts.extend(["", "## Stopped agents", "", _agent_table(stopped_agents)])

    if mesh.bots:
        parts.extend(_bots_section(mesh.bots))

    return "\n".join(parts) + "\n"

def _build_agent_metadata_rows(agent: Agent) -> list[tuple[str, str]]:
    rows = [
        ("Status", agent.status),
    ]
    if agent.backend:
        rows.append(("Backend", agent.backend))
    if agent.model:
        rows.append(("Model", agent.model))
    if agent.directory:
        rows.append(("Directory", agent.directory))
    rows.append(("Activity", agent.activity or "none"))
    if agent.turns is not None:
        rows.append(("Turns", str(agent.turns)))
    if agent.uptime:
        rows.append(("Uptime", agent.uptime))
    if agent.tags:
        rows.append(("Tags", ", ".join(agent.tags)))
    return rows

def _find_last_spoke(nick: str, ch_name: str, rooms: list[Room]) -> str:
    for room in rooms:
        if room.name == ch_name:
            for msg in room.messages:
                if msg.nick == nick:
                    return _relative_time(msg.timestamp)
            break
    return "never"

def _render_agent_activity(agent: Agent, rooms: list[Room], message_limit: int) -> list[str]:
    all_msgs = []
    for room in rooms:
        for msg in room.messages:
            if msg.nick == agent.nick:
                all_msgs.append(msg)
    all_msgs.sort(key=lambda m: m.timestamp, reverse=True)

    parts = []
    parts.append(f"## Recent activity across channels (last {message_limit})")
    parts.append("")
    if all_msgs:
        for msg in all_msgs[:message_limit]:
            parts.append(f"- {msg.channel} ({_relative_time(msg.timestamp)}): {msg.text}")
    else:
        parts.append("No recent activity.")
    return parts

def _load_css() -> str:
    """Load the cream stylesheet."""
    css_path = Path(__file__).parent / "web" / "style.css"
    return css_path.read_text()

def _inject_status_badges(html: str) -> str:
    """Replace status text in table cells with styled badges."""
    for status in ("active", "idle", "paused", "remote", "stopped", "circuit-open"):
        html = re.sub(
            rf"(<td>)\s*{status}\s*(</td>)",
            rf'\1<span class="status-{status}">{status}</span>\2',
            html,
        )
    return html

def _inject_partial_banner(html: str) -> str:
    """Style the partial-snapshot paragraph as a warning banner."""
    return html.replace(
        "<p><strong>Partial snapshot:</strong>",
        '<p class="partial-warning"><strong>Partial snapshot:</strong>',
        1,
    )

def _terminate_process(pid, timeout=2.0):
    """Send SIGTERM, poll until dead, fall back to SIGKILL. Returns True if killed."""
    try:
        os.kill(pid, signal.SIGTERM)
    except (PermissionError, ProcessLookupError):
        return False
    steps = int(timeout / 0.1)
    for _ in range(steps):
        if not is_process_alive(pid):
            return True
        time.sleep(0.1)
    try:
        os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        return True
    except PermissionError:
        pass
    return not is_process_alive(pid)

def _fetch_residents(self) -> list[Resident]:
    """Seam: query the bound culture server for the presence aggregation.

    Tests override this to inject fixtures; production queries the same
    server the overview renders, joining budgets from the same manifest.
    """
    config = ServerConfig(
        server=ServerConnConfig(name=self.server_name, host=self.irc_host, port=self.irc_port),
        agents=list(self.manifest_agents or []),
    )
    return asyncio.run(fetch_residents_async(config))

def _serve_residents(self) -> None:
    """GET /residents.json — the resource view (plan task t7).

    Read-only, no side effects, and byte-compatible with
    ``culture residents --json``: both emit exactly
    :func:`culture_core.resource_view.to_json` of
    :func:`culture_core.resource_view.serialize_residents`. Four
    response cases, never an unhandled traceback (the irc-lens console
    consumes this and must never see a bare 500):

    * presence supported          -> 200, canonical payload;
    * no PRESENCE surface         -> 200, ``supported: false`` payload
      (a presence-less mesh is a known state, not an error — pending
      agentirc#53);
    * culture server unreachable  -> 503, ``{code, message, remediation}``;
    * anything unexpected         -> 500, ``{code, message, remediation}``
      (defensive last resort — still structured JSON).
    """
    try:
        try:
            residents = self._fetch_residents()
            supported = True
        except PresenceUnsupportedError:
            residents, supported = [], False
    except OSError:
        # Covers ConnectionRefusedError, ConnectionError (including the
        # mid-stream presence stall), TimeoutError — all OSError
        # subclasses. Same voice as the residents CLI error.
        self._send_json(
            503,
            {
                "code": 503,
                "message": UNREACHABLE_MESSAGE,
                "remediation": UNREACHABLE_REMEDIATION,
            },
        )
        return
    except Exception as exc:
        # Defensive catch-all: whatever escapes the fetch seam, the
        # irc-lens console gets structured JSON — never a traceback
        # page or the default HTML 500.
        self._send_json(
            500,
            {
                "code": 500,
                "message": f"internal error building the resource view: {exc}",
                "remediation": "check the overview server logs and report a culture bug",
            },
        )
        return
    self._send_json(200, serialize_residents(residents, supported, now=self.residents_now))

def _setup_signal_handlers(httpd: HTTPServer) -> None:
    """Register SIGTERM handler to gracefully shut down the server."""
    if threading.current_thread() is not threading.main_thread():
        return

    def _handle_term(_sig, _frame):
        threading.Thread(target=httpd.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, _handle_term)

def _escape_tag_value(value: str) -> str:
    out = []
    for ch in value:
        if ch in _TAG_ESCAPE:
            out.append(_TAG_ESCAPE[ch])
        else:
            out.append(ch)
    return "".join(out)

@staticmethod
def _parse_tag_block(line: str) -> "tuple[dict[str, str], str]":
    """Extract leading @tag block from a wire line.

    Returns (tags_dict, remaining_line). If no tag block, returns ({}, line).
    """
    if not line.startswith("@"):
        return {}, line
    if " " not in line:
        return {}, ""  # malformed — no command after tags
    tag_blob, rest = line[1:].split(" ", 1)
    tags: dict[str, str] = {}
    for piece in tag_blob.split(";"):
        if not piece:
            continue
        if "=" in piece:
            key, value = piece.split("=", 1)
            tags[key] = _unescape_tag_value(value)
        else:
            tags[piece] = ""
    return tags, rest

@classmethod
def parse(cls, line: str) -> "Message":
    line = line.rstrip("\r\n")
    tags, line = cls._parse_tag_block(line)

    if not line:
        # malformed @-only input
        return cls(tags=tags, prefix=None, command="", params=[])

    prefix = None
    if line.startswith(":"):
        if " " not in line:
            return cls(tags=tags, prefix=None, command="", params=[])
        prefix, line = line.split(" ", 1)
        prefix = prefix[1:]

    trailing = None
    if " :" in line:
        line, trailing = line.split(" :", 1)

    parts = line.split()
    if not parts:
        return cls(tags=tags, prefix=prefix, command="", params=[])
    command = parts[0].upper()
    params = parts[1:]
    if trailing is not None:
        params.append(trailing)

    return cls(tags=tags, prefix=prefix, command=command, params=params)

def format(self) -> str:
    parts = []

    if self.tags:
        tag_pieces = []
        for key, value in self.tags.items():
            if value == "":
                tag_pieces.append(key)
            else:
                tag_pieces.append(f"{key}={_escape_tag_value(value)}")
        parts.append("@" + ";".join(tag_pieces))

    if self.prefix:
        parts.append(f":{self.prefix}")
    parts.append(self.command)

    if self.params:
        for param in self.params[:-1]:
            parts.append(param)
        last = self.params[-1]
        if " " in last or not last or last.startswith(":"):
            parts.append(f":{last}")
        else:
            parts.append(last)

    return " ".join(parts) + "\r\n"
